window.BASAIR_QUESTIONS=window.BASAIR_QUESTIONS.concat([{"id":"s16-144","number":144,"surah":16,"verses":[94],"verseLabel":"النحل: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿وَتَذُوقُوا السُّوءَ﴾؟","answer":"الذوق أدنى مباشرة حسية؛ فإذا ذاقوا السوء تمكن أثره منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص346-357","url":""}]},{"id":"s16-145","number":145,"surah":16,"verses":[95],"verseLabel":"النحل: 95","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تَشْتَرُوا بِعَهْدِ اللَّهِ ثَمَنًا قَلِيلًا﴾؟","answer":"صور استبدال الوفاء بالمصلحة بيعًا خاسرًا، وكل دنيوي قليل أمام ما عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص367-373","url":""}]},{"id":"s16-146","number":146,"surah":16,"verses":[96],"verseLabel":"النحل: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا عِنْدَكُمْ يَنْفَدُ وَمَا عِنْدَ اللَّهِ بَاقٍ﴾ بالمضارع؟","answer":"ليصور النفاد جارياً في كل لحظة، ويقابله ببقاء ثابت عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص377","url":""}]},{"id":"s16-147","number":147,"surah":16,"verses":[96],"verseLabel":"النحل: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿الَّذِينَ صَبَرُوا﴾ لا الصابرين؟","answer":"الصلة تستحضر فعل الصبر المتجدد الذي استحقوا به الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص380","url":""}]},{"id":"s16-148","number":148,"surah":16,"verses":[97],"verseLabel":"النحل: 97","question":"لماذا صرّح بـ﴿مِنْ ذَكَرٍ أَوْ أُنْثَى﴾ مع أن ﴿من﴾ تعم؟","answer":"لنفي عرف جاهلي قد يحرم المرأة من كمال الجزاء، وتقرير المساواة صراحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص388","url":""}]},{"id":"s16-149","number":149,"surah":16,"verses":[97],"verseLabel":"النحل: 97","question":"ما سرّ التعبير في قوله تعالى: ﴿حَيَاةً طَيِّبَةً﴾ بالتنكير؟","answer":"للتفخيم والتوسعة؛ تشمل طمأنينة القلب والرزق الحلال والقناعة، لا صورة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص393","url":""}]},{"id":"s16-150","number":150,"surah":16,"verses":[98],"verseLabel":"النحل: 98","question":"ما سرّ التعبير في قوله تعالى: ﴿فَاسْتَعِذْ بِاللَّهِ﴾ عند قراءة القرآن؟","answer":"لتهيئة القلب قبل التلاوة ودفع التشويش الذي يحجب التدبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص395-402","url":""}]},{"id":"s16-151","number":151,"surah":16,"verses":[98],"verseLabel":"النحل: 98","question":"لماذا عُرّف القرآن وأُظهر اسمه؟","answer":"لتفخيم المقروء وتذكير القارئ بأنه الكتاب الجامع الذي يستحق كامل الحضور.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص402","url":""}]},{"id":"s16-152","number":152,"surah":16,"verses":[99],"verseLabel":"النحل: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿لَيْسَ لَهُ سُلْطَانٌ﴾ لا قدرة؟","answer":"السلطان يشمل القهر والحجة والتأثير الملزم، وكلها منفية عن أهل الإيمان والتوكل.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص410-413","url":""}]},{"id":"s16-153","number":153,"surah":16,"verses":[99],"verseLabel":"النحل: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿عَلَى رَبِّهِمْ يَتَوَكَّلُونَ﴾ وقدم الجار؟","answer":"لقصر اعتمادهم على ربهم، وإضافة الرب إليهم وعد بالرعاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص413","url":""}]},{"id":"s16-154","number":154,"surah":16,"verses":[101],"verseLabel":"النحل: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِذَا بَدَّلْنَا آيَةً مَكَانَ آيَةٍ﴾ لا نسخنا؟","answer":"التبديل يصور رفع حكم ووضع آخر في موضعه وفق الحكمة، وهو أوضح للمخاطب من المصطلح.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص420-425","url":""}]},{"id":"s16-155","number":155,"surah":16,"verses":[101],"verseLabel":"النحل: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاللَّهُ أَعْلَمُ بِمَا يُنَزِّلُ﴾ اعتراضًا؟","answer":"رد فوري على تهمة الافتراء: اختلاف الأحكام صادر عن علم بالمصالح لا تناقض.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص425-429","url":""}]},{"id":"s16-156","number":156,"surah":16,"verses":[102],"verseLabel":"النحل: 102","question":"لماذا وصف القرآن بـ﴿هُدًى وَبُشْرَى﴾ بهذا الترتيب؟","answer":"يهدي أولًا إلى الطريق، ثم يبشر من سلكه بالجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص439","url":""}]},{"id":"s16-157","number":157,"surah":16,"verses":[102],"verseLabel":"النحل: 102","question":"لماذا أظهر ﴿رُوحُ الْقُدُسِ﴾ بدل الضمير؟","answer":"لتشريف جبريل وتقرير طهارة الواسطة، ردًا على دعوى أن بشرًا يعلمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص440","url":""}]},{"id":"s16-158","number":158,"surah":16,"verses":[103],"verseLabel":"النحل: 103","question":"ما دلالة قولهم: ﴿إِنَّمَا يُعَلِّمُهُ بَشَرٌ﴾؟","answer":"حصروا مصدره في إنسان واحد ليبطلوا الوحي، فجاء الرد من اختلاف اللسان ووضوح العربية.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص451-458","url":""}]},{"id":"s16-159","number":159,"surah":16,"verses":[103],"verseLabel":"النحل: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿لِسَانُ الَّذِي يُلْحِدُونَ إِلَيْهِ أَعْجَمِيٌّ﴾ لا أعجم؟","answer":"«أعجمي» وصف اللسان غير العربي، وهو المقابل الدقيق لقرآن عربي مبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص458-461","url":""}]},{"id":"s16-160","number":160,"surah":16,"verses":[103],"verseLabel":"النحل: 103","question":"لماذا وصف لسان القرآن بـ﴿عَرَبِيٌّ مُبِينٌ﴾ لا فصيح؟","answer":"الإبانة أوسع؛ تعني أنه واضح في ذاته كاشف للمعنى، والفصاحة بعض ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص461-462","url":""}]},{"id":"s16-161","number":161,"surah":16,"verses":[104],"verseLabel":"النحل: 104","question":"ما سرّ التعبير في قوله تعالى: ﴿الَّذِينَ لَا يُؤْمِنُونَ﴾ لا الكافرون؟","answer":"ليستحضر استمرار اختيارهم عدم الإيمان، وهو سبب عدم هدايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص469","url":""}]},{"id":"s16-162","number":162,"surah":16,"verses":[105],"verseLabel":"النحل: 105","question":"لماذا حصر الافتراء في ﴿الَّذِينَ لَا يُؤْمِنُونَ بِآيَاتِ اللَّهِ﴾؟","answer":"لأن المؤمن بالآيات يعلم حرمة الكذب على الله، أما الجاحد فقد سقط وازعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص480-487","url":""}]},{"id":"s16-163","number":163,"surah":16,"verses":[105],"verseLabel":"النحل: 105","question":"لماذا ختم بـ﴿وَأُولَئِكَ هُمُ الْكَاذِبُونَ﴾؟","answer":"ضمير الفصل وتعريف الطرفين يقصران حقيقة الكذب عليهم، ويردان تهمتهم للرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص486-488","url":""}]},{"id":"s16-164","number":164,"surah":16,"verses":[106],"verseLabel":"النحل: 106","question":"ما سرّ التعبير في قوله تعالى: ﴿إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُ مُطْمَئِنٌّ بِالْإِيمَانِ﴾؟","answer":"فرق بين لفظ اضطر إليه اللسان وقلب ثابت مختار؛ فمحل الاعتقاد لا يتبدل بالإكراه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص494-505","url":""}]},{"id":"s16-165","number":165,"surah":16,"verses":[106],"verseLabel":"النحل: 106","question":"ما سرّ التعبير في قوله تعالى: ﴿قَلْبُهُ﴾ لا فؤاده؟","answer":"القلب محل الاعتقاد والتقلب بين الإيمان والكفر، وهو الأنسب لحكم الإكراه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص501","url":""}]},{"id":"s16-166","number":166,"surah":16,"verses":[106],"verseLabel":"النحل: 106","question":"ما سرّ التعبير في قوله تعالى: ﴿شَرَحَ بِالْكُفْرِ صَدْرًا﴾ لا قلبًا؟","answer":"الصدر وعاء يتسع لما يستقبله؛ فالصورة لمن فتح للكفر مجالًا وقبله راضيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص508-509","url":""}]},{"id":"s16-167","number":167,"surah":16,"verses":[106],"verseLabel":"النحل: 106","question":"ما سرّ تقديم ﴿فَعَلَيْهِمْ غَضَبٌ مِنَ اللَّهِ﴾؟","answer":"لتعجيل الحكم وإلصاق الغضب بهم قبل ذكر العذاب العظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص510-511","url":""}]},{"id":"s16-168","number":168,"surah":16,"verses":[107],"verseLabel":"النحل: 107","question":"ما سرّ التعبير في قوله تعالى: ﴿اسْتَحَبُّوا الْحَيَاةَ الدُّنْيَا عَلَى الْآخِرَةِ﴾؟","answer":"الاستحباب هنا اختيار مقصود وإيثار، لا مجرد ميل عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص521-525","url":""}]},{"id":"s16-169","number":169,"surah":16,"verses":[108],"verseLabel":"النحل: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿طَبَعَ اللَّهُ عَلَى قُلُوبِهِمْ﴾ لا ختم؟","answer":"الطبع يصور أثرًا راسخًا صار سمة بسبب إصرارهم، فلا تنفذ الموعظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص529-532","url":""}]},{"id":"s16-170","number":170,"surah":16,"verses":[108],"verseLabel":"النحل: 108","question":"لماذا أُفرد السمع وجُمعت الأبصار؟","answer":"السمع يدرك الصوت الواحد المشترك، والأبصار تتعدد بتعدد الجهات والمرئيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص533-535","url":""}]},{"id":"s16-171","number":171,"surah":16,"verses":[109],"verseLabel":"النحل: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿هُمُ الْخَاسِرُونَ﴾ جملة اسمية مقصورة؟","answer":"للدلالة على ثبات الخسران وكماله حتى كأن لا خاسر سواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص542-544","url":""}]},{"id":"s16-172","number":172,"surah":16,"verses":[110],"verseLabel":"النحل: 110","question":"لماذا حُذف متعلق ﴿هَاجَرُوا﴾ و﴿جَاهَدُوا﴾ و﴿صَبَرُوا﴾؟","answer":"لتعم جهات الهجرة وأنواع الجهاد والصبر، فلا يحصر فضلهم في واقعة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص552-556","url":""}]},{"id":"s16-173","number":173,"surah":16,"verses":[110],"verseLabel":"النحل: 110","question":"ما سرّ تقديم ﴿لَغَفُورٌ﴾ على ﴿رَحِيمٌ﴾؟","answer":"المغفرة تزيل أثر ما وقع زمن الفتنة، ثم تأتي الرحمة بالثواب والتثبيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص560-561","url":""}]},{"id":"s16-174","number":174,"surah":16,"verses":[111],"verseLabel":"النحل: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿كُلُّ نَفْسٍ تُجَادِلُ عَنْ نَفْسِهَا﴾؟","answer":"أفرد كل إنسان بمصيره، و«تجادل» تصور شدة دفاعه حين تنقطع النصرة الخارجية.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص566-570","url":""}]},{"id":"s16-175","number":175,"surah":16,"verses":[111],"verseLabel":"النحل: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا عَمِلَتْ﴾ لا ما قدمت؟","answer":"العمل أعم من المقدمات الظاهرة، فيشمل كل كسب باطن وظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص570-571","url":""}]},{"id":"s16-176","number":176,"surah":16,"verses":[112],"verseLabel":"النحل: 112","question":"لماذا ضُرب المثل بالقرية لا بأهلها؟","answer":"لتصبح السكينة والرزق ثم الجوع والخوف مشهدًا يحيط بالمكان كله وأهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص576-580","url":""}]},{"id":"s16-177","number":177,"surah":16,"verses":[112],"verseLabel":"النحل: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿يَأْتِيهَا رِزْقُهَا رَغَدًا مِنْ كُلِّ مَكَانٍ﴾؟","answer":"«يأتيها» يصور الرزق قاصدًا إليها، و«كل مكان» يبالغ في سعة موارده.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص580-589","url":""}]},{"id":"s16-178","number":178,"surah":16,"verses":[112],"verseLabel":"النحل: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿فَأَذَاقَهَا اللَّهُ لِبَاسَ الْجُوعِ وَالْخَوْفِ﴾ فجمع الذوق واللباس؟","answer":"الذوق يدل على مباشرة الألم، واللباس على إحاطته ودوامه؛ فاجتمعت شدة الداخل والخارج.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص576-597","url":""}]},{"id":"s16-179","number":179,"surah":16,"verses":[112],"verseLabel":"النحل: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿بِمَا كَانُوا يَصْنَعُونَ﴾ لا يعملون؟","answer":"الصنع عمل متقن مقصود؛ يوحي بأن كفرهم صار منهجًا يتعمدونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص598-599","url":""}]},{"id":"s16-180","number":180,"surah":16,"verses":[113],"verseLabel":"النحل: 113","question":"ما سرّ التعبير في قوله تعالى: ﴿فَأَخَذَهُمُ الْعَذَابُ وَهُمْ ظَالِمُونَ﴾؟","answer":"الحال تثبت أن الأخذ وافق استمرار ظلمهم، فلا شبهة في عدل الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص600-601","url":""}]},{"id":"s16-181","number":181,"surah":16,"verses":[114],"verseLabel":"النحل: 114","question":"ما سرّ تقديم ﴿حَلَالًا﴾ على ﴿طَيِّبًا﴾؟","answer":"الحل حكم الإذن أولًا، ثم الطيب وصف المنفعة والاستلذاذ؛ فلا يغني أحدهما عن الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص612","url":""}]},{"id":"s16-182","number":182,"surah":16,"verses":[114],"verseLabel":"النحل: 114","question":"لماذا أُفردت ﴿نِعْمَتَ اللَّهِ﴾؟","answer":"اسم جنس يستوعب الرزق وسائر النعم، وكل واحدة منها تستحق الشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص613","url":""}]},{"id":"s16-183","number":183,"surah":16,"verses":[114],"verseLabel":"النحل: 114","question":"ما سرّ تقديم ﴿إِيَّاهُ﴾ في ﴿إِنْ كُنْتُمْ إِيَّاهُ تَعْبُدُونَ﴾؟","answer":"لقصر العبادة عليه؛ من خصه بالعبادة لزمه أن يخصه بالشكر والطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص615","url":""}]},{"id":"s16-184","number":184,"surah":16,"verses":[115],"verseLabel":"النحل: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ﴾ ولم يصرح بالأصنام؟","answer":"ليعم كل جهة سوى الله ذُبح لها، فلا يضيق الحكم بأسماء معينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص618-619","url":""}]},{"id":"s16-185","number":185,"surah":16,"verses":[115],"verseLabel":"النحل: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَنِ اضْطُرَّ﴾ لا أُجبر؟","answer":"الاضطرار حال تدفعه الحاجة الملجئة دون اختيار، وهو مناط الرخصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص621","url":""}]},{"id":"s16-186","number":186,"surah":16,"verses":[115],"verseLabel":"النحل: 115","question":"ما مناسبة ختام حكم المضطر بقوله تعالى: ﴿إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ﴾؟","answer":"غفور للمضطر فيما أكل، رحيم به حين رخّص له عند الاضطرار؛ فجمع له العفو والرخصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص621–623.","url":""}]},{"id":"s16-187","number":187,"surah":16,"verses":[116],"verseLabel":"النحل: 116","question":"لماذا أسند الكذب إلى الألسنة: ﴿لِمَا تَصِفُ أَلْسِنَتُكُمُ الْكَذِبَ﴾؟","answer":"في إسناد وصف الكذب إلى الألسنة مزيد تشنيع؛ إذ جعل ألسنتهم تتولى الافتراء، مع علم قلوبهم بخلافه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص630-634","url":""}]},{"id":"s16-188","number":188,"surah":16,"verses":[116],"verseLabel":"النحل: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿تَفْتَرُوا عَلَى اللَّهِ الْكَذِبَ﴾؟","answer":"الافتراء اختلاق متعمد لا مجرد خبر خاطئ، وتقديم ﴿على الله﴾ يعظم الجناية.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص633–634.","url":""}]},{"id":"s16-189","number":189,"surah":16,"verses":[117],"verseLabel":"النحل: 117","question":"ما سر الجمع بين قوله تعالى: ﴿مَتَاعٌ قَلِيلٌ﴾ وقوله: ﴿وَلَهُمْ عَذَابٌ أَلِيمٌ﴾؟","answer":"قابل متاع الدنيا القليل الزائل بما ينتظر المفترين في الآخرة من عذاب أليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص639.","url":""}]},{"id":"s16-190","number":190,"surah":16,"verses":[119],"verseLabel":"النحل: 119","question":"ما سر تكرار قوله تعالى: ﴿ثُمَّ إِنَّ رَبَّكَ﴾؟","answer":"لطول الكلام الفاصل، أعيدت الجملة حتى يتصل وعد المغفرة بأهله ويقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص657–662.","url":""}]},{"id":"s16-191","number":191,"surah":16,"verses":[119],"verseLabel":"النحل: 119","question":"ما سر حذف مفعول ﴿أَصْلَحُوا﴾؟","answer":"ليعم إصلاح الاعتقاد والعمل وما أفسدته الجهالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص658.","url":""}]},{"id":"s16-192","number":192,"surah":16,"verses":[120],"verseLabel":"النحل: 120","question":"ما سر وصف إبراهيم عليه السلام وحده بأنه ﴿أُمَّةً﴾؟","answer":"لجمعه خصال الخير التي تتفرق في أمة، ولكونه إمامًا يُقتدى به.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص666-675","url":""}]},{"id":"s16-193","number":193,"surah":16,"verses":[120],"verseLabel":"النحل: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿قَانِتًا لِلَّهِ حَنِيفًا﴾؟","answer":"القنوت دوام الطاعة، والحنيف الميل عن الشرك إلى التوحيد؛ فجمع العمل والاعتقاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص670-675","url":""}]},{"id":"s16-194","number":194,"surah":16,"verses":[120],"verseLabel":"النحل: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَمْ يَكُ مِنَ الْمُشْرِكِينَ﴾ بحذف النون؟","answer":"للتخفيف وكثرة الاستعمال، مع انسجام الإيقاع؛ وهو يمهد لنظيره ﴿ولا تك﴾ في ختام السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص670–675.","url":""}]},{"id":"s16-195","number":195,"surah":16,"verses":[121],"verseLabel":"النحل: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿شَاكِرًا لِأَنْعُمِهِ﴾ بجمع القلة؟","answer":"استحضر نعمًا مخصوصة عظيمة قام إبراهيم بشكرها حق القيام، لا أن نعم الله محصورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص675","url":""}]},{"id":"s16-196","number":196,"surah":16,"verses":[121],"verseLabel":"النحل: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿اجْتَبَاهُ﴾؟","answer":"الاجتباء جمع واصطفاء بعناية، يلائم اكتمال خصاله قبل هدايته للصراط.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص676","url":""}]},{"id":"s16-197","number":197,"surah":16,"verses":[122],"verseLabel":"النحل: 122","question":"ما سر تقديم ﴿فِي الدُّنْيَا﴾ و﴿فِي الْآخِرَةِ﴾؟","answer":"لتقسيم الجزاء بوضوح: حسنة عاجلة وصلاح ثابت في الدار الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص679-680","url":""}]},{"id":"s16-198","number":198,"surah":16,"verses":[123],"verseLabel":"النحل: 123","question":"ما سرّ التعبير في قوله تعالى: ﴿اتَّبِعْ مِلَّةَ إِبْرَاهِيمَ﴾؟","answer":"الملة طريق عقدي وعملي موروث، فأمر النبي باتباع أصل التوحيد الذي ينتسب إليه العرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص680-690","url":""}]},{"id":"s16-199","number":199,"surah":16,"verses":[124],"verseLabel":"النحل: 124","question":"ما سر التعبير بقوله تعالى: ﴿إِنَّمَا جُعِلَ السَّبْتُ عَلَى الَّذِينَ اخْتَلَفُوا فِيهِ﴾؟","answer":"«جعل» يبين أنه حكم تشريعي خاص عقوبةً أو اختبارًا، لا أصلًا في ملة إبراهيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص693-697","url":""}]},{"id":"s16-200","number":200,"surah":16,"verses":[124],"verseLabel":"النحل: 124","question":"ما سر تقديم ﴿فِيهِ﴾ في قوله تعالى: ﴿فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ﴾؟","answer":"قُدّمت ﴿فيه﴾ على خبر «كان» لأن ما وقع فيه الاختلاف هو مدار الحديث وسبب الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص694.","url":""}]},{"id":"s16-201","number":201,"surah":16,"verses":[125],"verseLabel":"النحل: 125","question":"ما سر ترتيب وسائل الدعوة: الحكمة ثم الموعظة الحسنة ثم الجدال بالتي هي أحسن؟","answer":"بحسب حال المدعو: طالب الحق يحتاج البرهان، والغافل التذكير، والمعارض حوارًا منضبطًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص697-709","url":""}]},{"id":"s16-202","number":202,"surah":16,"verses":[126],"verseLabel":"النحل: 126","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنْ عَاقَبْتُمْ فَعَاقِبُوا بِمِثْلِ مَا عُوقِبْتُمْ بِهِ﴾؟","answer":"قيد رد الاعتداء بالمماثلة حتى لا يتحول طلب الحق إلى بغي، ثم ندب إلى الصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص709-718","url":""}]},{"id":"s16-203","number":203,"surah":16,"verses":[126],"verseLabel":"النحل: 126","question":"ما سر حذف مفعول ﴿عَاقَبْتُمْ﴾؟","answer":"ليعم كل من يقع منه رد مشروع، وكل معتدٍ وقع عليه الرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص715.","url":""}]},{"id":"s16-204","number":204,"surah":16,"verses":[127],"verseLabel":"النحل: 127","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاصْبِرْ وَمَا صَبْرُكَ إِلَّا بِاللَّهِ﴾؟","answer":"أمره بالصبر ثم نفى استقلال النفس به؛ مصدر الثبات توفيق الله ومعونته.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص718-723","url":""}]},{"id":"s16-205","number":205,"surah":16,"verses":[127],"verseLabel":"النحل: 127","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿وَلَا تَكُ فِي ضَيْقٍ﴾ بحذف النون، وفي النمل: ﴿ولا تكن﴾؟","answer":"الحذف للتخفيف، وناسب ما قبله ﴿ولم يك من المشركين﴾، وفيه مبالغة رشيقة في التسلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص720.","url":""}]},{"id":"s16-206","number":206,"surah":16,"verses":[127],"verseLabel":"النحل: 127","question":"ما سرّ التعبير في قوله تعالى: ﴿فِي ضَيْقٍ﴾ لا ذا ضيق؟","answer":"جعل الضيق ظرفًا يحيط بالنفس، ثم نهى أن يدخل فيه أصلًا بسبب مكرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص723","url":""}]},{"id":"s16-207","number":207,"surah":16,"verses":[128],"verseLabel":"النحل: 128","question":"ما مناسبة ختام السورة بقوله تعالى: ﴿إِنَّ اللَّهَ مَعَ الَّذِينَ اتَّقَوْا وَالَّذِينَ هُمْ مُحْسِنُونَ﴾؟","answer":"معية نصر وتأييد تقابل مكر الخصوم؛ التقوى تكف عن الشر والإحسان يبلغ كمال الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص723-730","url":""}]},{"id":"s17-1","number":1,"surah":17,"verses":[1],"verseLabel":"الإسراء: 1","question":"ما سر افتتاح السورة بـ﴿سُبْحَانَ﴾ قبل خبر الإسراء؟","answer":"لتهيئة السامع لخبر عجيب يدل على عظيم القدرة، وتنزيه الله عن العجز عن هذا الحدث الخارق للعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص748–749، تحت الإسراء: 1.","url":""}]},{"id":"s17-2","number":2,"surah":17,"verses":[1],"verseLabel":"الإسراء: 1","question":"ما سر التعبير بـ﴿أَسْرَى بِعَبْدِهِ﴾ لا «سرى بعبده»؟","answer":"لأن ﴿أسرى﴾ هنا متعدٍّ في المعنى: أي جعل البراق يسري بعبده؛ وفي الصيغة إيماء إلى عناية الله برسوله وتوفيقه في الرحلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص750–751، تحت الإسراء: 1.","url":""}]},{"id":"s17-3","number":3,"surah":17,"verses":[1],"verseLabel":"الإسراء: 1","question":"ما سر التعبير بـ﴿بِعَبْدِهِ﴾ لا «برسوله»؟","answer":"لأن العبودية أعلى مقامات القرب والرفعة، وفي وصفه بها تشريف له مع سد باب الغلو فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص751–754، تحت الإسراء: 1.","url":""}]},{"id":"s17-4","number":4,"surah":17,"verses":[1],"verseLabel":"الإسراء: 1","question":"ما سر ذكر ﴿لَيْلًا﴾ مع أن الإسراء لا يكون إلا ليلًا؟","answer":"لأن تنكيره يدل على أن الرحلة العظيمة وقعت في بعض ليلة، فيظهر بذلك ما فيها من خرق للعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص752–756، تحت الإسراء: 1.","url":""}]},{"id":"s17-5","number":5,"surah":17,"verses":[1],"verseLabel":"الإسراء: 1","question":"ما دلالة وصف المسجد بـ﴿الْأَقْصَى﴾؟","answer":"هو وصف تفضيل يبين شدة بعده عن المسجد الحرام، فيبرز طول المسافة التي قطعت في بعض ليلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص759، تحت الإسراء: 1.","url":""}]},{"id":"s17-6","number":6,"surah":17,"verses":[1],"verseLabel":"الإسراء: 1","question":"ما سر التعبير بـ﴿بَارَكْنَا حَوْلَهُ﴾ لا «باركنا فيه»؟","answer":"ليعم الخير المسجد وما حوله؛ فإذا ثبتت البركة لما أحاط به كان ثبوتها فيه من باب أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص762، تحت الإسراء: 1.","url":""}]},{"id":"s17-7","number":7,"surah":17,"verses":[1],"verseLabel":"الإسراء: 1","question":"ما دلالة ﴿مِنْ﴾ في قوله تعالى: ﴿لِنُرِيَهُ مِنْ آيَاتِنَا﴾؟","answer":"هي للتبعيض؛ فما أُريه بعض آيات الله، وفي ذلك تعظيم لما شاهده مع بقاء آيات لا تتناهى.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص765، تحت الإسراء: 1.","url":""}]},{"id":"s17-8","number":8,"surah":17,"verses":[1],"verseLabel":"الإسراء: 1","question":"ما مناسبة ختام آية الإسراء بقوله تعالى: ﴿إِنَّهُ هُوَ السَّمِيعُ الْبَصِيرُ﴾؟","answer":"على عود الضمير إلى الله يكون المعنى أنه القادر على إسماع عبده وإبصاره تلك الآيات؛ وقد ذكر ابن عاشور احتمال عود الضمير إلى النبي ﷺ، فيكون وصفًا لقوة إدراكه لما سمع وأبصر وردًّا لتكذيب المشركين.","sources":[{"label":"ابن عاشور، التحرير والتنوير، 15/21–22، تفسير الإسراء: 1؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-9","number":9,"surah":17,"verses":[2],"verseLabel":"الإسراء: 2","question":"ما سر التعبير في قوله تعالى: ﴿آتَيْنَا مُوسَى الْكِتَابَ﴾ بالإيتاء لا الإعطاء؟","answer":"الإيتاء إيصال للمقصود مطلقًا، بخلاف الإعطاء الذي يغلب اتصاله بالعطية والمناولة؛ فناسب إنزال الكتاب وإيصاله إلى موسى عليه السلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص771، تحت الإسراء: 2.","url":""}]},{"id":"s17-10","number":10,"surah":17,"verses":[2],"verseLabel":"الإسراء: 2","question":"ما سر التعبير بـ﴿بَنِي إِسْرَائِيلَ﴾ لا «اليهود»؟","answer":"للتذكير بأصلهم ونسبتهم إلى نبي كريم، وبما يقتضيه ذلك من اتباع الهدى والوفاء بالميثاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص774، تحت الإسراء: 2.","url":""}]},{"id":"s17-11","number":11,"surah":17,"verses":[2],"verseLabel":"الإسراء: 2","question":"ما مناسبة قوله تعالى: ﴿أَلَّا تَتَّخِذُوا مِنْ دُونِي وَكِيلًا﴾ بعد ذكر الكتاب؟","answer":"لأن الكتاب هدى إلى إفراد الله بالاعتماد والعبادة، فلا يُتخذ من دونه من يفوض إليه الأمر استقلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص775–780، تحت الإسراء: 2.","url":""}]},{"id":"s17-12","number":12,"surah":17,"verses":[3],"verseLabel":"الإسراء: 3","question":"ما دلالة نداء بني إسرائيل بقوله تعالى: ﴿ذُرِّيَّةَ مَنْ حَمَلْنَا مَعَ نُوحٍ﴾؟","answer":"تذكير لهم بنجاة أصولهم مع نوح وبالنعمة عليهم، وحث لهم على الاقتداء بشكره.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص781–782، تحت الإسراء: 3.","url":""}]},{"id":"s17-13","number":13,"surah":17,"verses":[3],"verseLabel":"الإسراء: 3","question":"ما سر وصف نوح عليه السلام بأنه ﴿عَبْدًا﴾؟","answer":"للتنويه بكمال إخلاصه وخضوعه لله؛ فالعبودية مقام غاية التذلل لمن له غاية الإفضال والإنعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص783، تحت الإسراء: 3.","url":""}]},{"id":"s17-14","number":14,"surah":17,"verses":[3],"verseLabel":"الإسراء: 3","question":"ما دلالة وصف نوح عليه السلام بـ﴿شَكُورًا﴾ بصيغة «فعول»؟","answer":"تدل صيغة المبالغة على كثرة شكره حتى صار الشكر وصفًا معروفًا ملازمًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص784، تحت الإسراء: 3.","url":""}]},{"id":"s17-15","number":15,"surah":17,"verses":[4],"verseLabel":"الإسراء: 4","question":"ما سر تعدية ﴿قَضَيْنَا﴾ بـ﴿إِلَى﴾ في قوله تعالى: ﴿وَقَضَيْنَا إِلَى بَنِي إِسْرَائِيلَ﴾؟","answer":"ضُمّن القضاء معنى الإيحاء والإبلاغ، فجمع حتم الأمر وإيصاله إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص788، تحت الإسراء: 4.","url":""}]},{"id":"s17-16","number":16,"surah":17,"verses":[4],"verseLabel":"الإسراء: 4","question":"ما دلالة توكيد الفعلين في قوله تعالى: ﴿لَتُفْسِدُنَّ﴾ و﴿لَتَعْلُنَّ﴾؟","answer":"اللام جواب لقسم مقدر، وجاءت نون التوكيد الثقيلة لتقرير تحقق الإفساد والعلو المخبَر بهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص790–792، تحت الإسراء: 4.","url":""}]},{"id":"s17-17","number":17,"surah":17,"verses":[4],"verseLabel":"الإسراء: 4","question":"ما دلالة وصف العلو بقوله تعالى: ﴿عُلُوًّا كَبِيرًا﴾؟","answer":"يفخم ما يبلغونه من الاستكبار والتسلط، ويصور اتساع أثره وشدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص793–795، تحت الإسراء: 4.","url":""}]},{"id":"s17-18","number":18,"surah":17,"verses":[5],"verseLabel":"الإسراء: 5","question":"ما سر التعبير بـ﴿جَاءَ وَعْدُ أُولَاهُمَا﴾؟","answer":"يصور تحقق الوعد وحلوله عند مجيء وقته، حتى كأنه شيء وافد وصل إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص797–799، تحت الإسراء: 5.","url":""}]},{"id":"s17-19","number":19,"surah":17,"verses":[5],"verseLabel":"الإسراء: 5","question":"ما دلالة وصف العباد بقوله تعالى: ﴿أُولِي بَأْسٍ شَدِيدٍ﴾؟","answer":"البأس قوة يظهر أثرها في الحرب والبطش، ووصفه بالشديد يصور قوة العقوبة المسلطة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص801–802، تحت الإسراء: 5.","url":""}]},{"id":"s17-20","number":20,"surah":17,"verses":[5],"verseLabel":"الإسراء: 5","question":"ما سر التعبير في قوله تعالى: ﴿فَجَاسُوا خِلَالَ الدِّيَارِ﴾؟","answer":"الجوس تتبع وتخلل باستقصاء، و﴿خلال الديار﴾ يصور دخولهم بين المساكن وانتشارهم فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص803–805، تحت الإسراء: 5.","url":""}]},{"id":"s17-21","number":21,"surah":17,"verses":[6],"verseLabel":"الإسراء: 6","question":"ما سرّ التعبير بقوله تعالى: ﴿رَدَدْنَا لَكُمُ الْكَرَّةَ عَلَيْهِمْ﴾ لا «الغلبة»؟","answer":"الكرة رجوع الدولة والقوة بعد انكسار؛ فهي تصور انقلاب الحال لا مجرد نصر عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص15.","url":""}]},{"id":"s17-22","number":22,"surah":17,"verses":[6],"verseLabel":"الإسراء: 6","question":"ما سرّ التعبير بقوله تعالى: ﴿وَأَمْدَدْنَاكُمْ بِأَمْوَالٍ وَبَنِينَ﴾؟","answer":"الإمداد زيادة متتابعة، وذكر البنين لأنهم موضع القوة والنصرة في ذلك السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص18.","url":""}]},{"id":"s17-23","number":23,"surah":17,"verses":[7],"verseLabel":"الإسراء: 7","question":"ما سرّ التعبير بقوله تعالى: ﴿إِنْ أَحْسَنْتُمْ أَحْسَنْتُمْ لِأَنْفُسِكُمْ﴾؟","answer":"لأن ثمرة الإحسان راجعة إليهم، فلا يزيد إحسانهم في ملك الله وإنما يبنون مصيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص24.","url":""}]},{"id":"s17-24","number":24,"surah":17,"verses":[7],"verseLabel":"الإسراء: 7","question":"ما سرّ التعبير في الإساءة ﴿فَلَهَا﴾ ولم يقل «فلأنفسكم»؟","answer":"حُذف فعل الجواب لدلالة الفعل الأول عليه؛ والتقدير: وإن أسأتم فأسأتم لها، أي فعاقبة الإساءة راجعة إلى النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص28.","url":""}]},{"id":"s17-25","number":25,"surah":17,"verses":[7],"verseLabel":"الإسراء: 7","question":"ما سرّ التعبير بقوله تعالى: ﴿وَعْدُ الْآخِرَةِ﴾ لا «الثانية»؟","answer":"لأن «الآخرة» تقابل الأولى وتوحي بأنها نهاية الكرتين وعاقبتهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص31.","url":""}]},{"id":"s17-26","number":26,"surah":17,"verses":[7],"verseLabel":"الإسراء: 7","question":"ما سرّ التعبير بقوله تعالى: ﴿لِيَسُوءُوا وُجُوهَكُمْ﴾؟","answer":"جعلت الإساءة واقعة على الوجوه لأنها أظهر موضع للعزة والسرور، فيظهر عليها الذل والحزن.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص33.","url":""}]},{"id":"s17-27","number":27,"surah":17,"verses":[8],"verseLabel":"الإسراء: 8","question":"لماذا عُلّق الرجاء بـ﴿عَسَى رَبُّكُمْ أَنْ يَرْحَمَكُمْ﴾ بعد العقوبة؟","answer":"فتح باب العودة ولم يجعل التاريخ قدرًا مغلقًا؛ فالرحمة قريبة إن عادوا إلى الصلاح.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 8؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-28","number":28,"surah":17,"verses":[8],"verseLabel":"الإسراء: 8","question":"ما سرّ التعبير بقوله تعالى: ﴿وَإِنْ عُدْتُمْ عُدْنَا﴾ بهذه المقابلة القصيرة؟","answer":"قابل عودهم إلى الإفساد بعودة العقاب؛ فالجملة تجمع الترهيب مع الرجاء السابق في رحمة الله.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 8؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-29","number":29,"surah":17,"verses":[9],"verseLabel":"الإسراء: 9","question":"ما سرّ التعبير بقوله تعالى: ﴿يَهْدِي لِلَّتِي هِيَ أَقْوَمُ﴾ ولم يذكر الموصوف؟","answer":"ليعم الطريقة والملة والحال والخصلة التي هي أشد استقامة في كل شأن.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص40؛ التحرير والتنوير، تفسير الإسراء 9.","url":""}]},{"id":"s17-30","number":30,"surah":17,"verses":[9],"verseLabel":"الإسراء: 9","question":"ما سرّ التعبير بقوله تعالى: ﴿أَقْوَمُ﴾ لا «مستقيمة»؟","answer":"لإفادة التفاضل: هداية القرآن أعدل وأثبت من كل طريق يُدّعى فيه الصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص40.","url":""}]},{"id":"s17-31","number":31,"surah":17,"verses":[9],"verseLabel":"الإسراء: 9","question":"لماذا جمع بين الهداية والبشارة؟","answer":"الهداية ترسم الطريق، والبشارة تقوي الإرادة للسير فيه؛ فجمع البيان والتحفيز.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص45.","url":""}]},{"id":"s17-32","number":32,"surah":17,"verses":[10],"verseLabel":"الإسراء: 10","question":"لماذا خُصّ عدم الإيمان بـ﴿الْآخِرَةِ﴾؟","answer":"لأن إنكار الجزاء يهدم باعث العمل ويُبقي صاحبه أسير العاجلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص61.","url":""}]},{"id":"s17-33","number":33,"surah":17,"verses":[11],"verseLabel":"الإسراء: 11","question":"ما سرّ التعبير بقوله تعالى: ﴿وَيَدْعُ الْإِنْسَانُ بِالشَّرِّ دُعَاءَهُ بِالْخَيْرِ﴾؟","answer":"سوّى بين الدعاءين في الاندفاع ليكشف أن العجلة قد تجعل الإنسان يطلب هلاكه كما يطلب نفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص67.","url":""}]},{"id":"s17-34","number":34,"surah":17,"verses":[11],"verseLabel":"الإسراء: 11","question":"لماذا وصف الإنسان بـ﴿عَجُولًا﴾ لا «سريعًا»؟","answer":"العجلة طلب الشيء قبل أوانه من غير روية، أما السرعة فقد تكون محمودة بعد التثبت.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص70.","url":""}]},{"id":"s17-35","number":35,"surah":17,"verses":[12],"verseLabel":"الإسراء: 12","question":"ما سرّ التعبير بقوله تعالى: ﴿فَمَحَوْنَا آيَةَ اللَّيْلِ﴾ لا «أزلناها»؟","answer":"المحو إزالة الأثر أو الضوء مع بقاء الآية نفسها، فالليل باقٍ لكن علامته مظلمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص79.","url":""}]},{"id":"s17-36","number":36,"surah":17,"verses":[12],"verseLabel":"الإسراء: 12","question":"ما سرّ التعبير بقوله تعالى: ﴿لِتَبْتَغُوا فَضْلًا مِنْ رَبِّكُمْ﴾ لا «لتطلبوا رزقًا»؟","answer":"الابتغاء طلب بجد، والفضل أوسع من الرزق؛ يشمل وجوه النفع التي ييسرها النهار.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص82.","url":""}]},{"id":"s17-37","number":37,"surah":17,"verses":[12],"verseLabel":"الإسراء: 12","question":"لماذا عُللت آية النهار ولم تُذكر علة الليل صراحة؟","answer":"اكتُفي بما يفهم من المقابلة: النهار للإبصار والابتغاء، والليل للسكون.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص82.","url":""}]},{"id":"s17-38","number":38,"surah":17,"verses":[12],"verseLabel":"الإسراء: 12","question":"ما سرّ التعبير بقوله تعالى: ﴿وَكُلَّ شَيْءٍ فَصَّلْنَاهُ تَفْصِيلًا﴾؟","answer":"التفصيل تفريق المعاني وإيضاح حدودها، وهو أبلغ من مجرد البيان المجمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص84.","url":""}]},{"id":"s17-39","number":39,"surah":17,"verses":[13],"verseLabel":"الإسراء: 13","question":"ما سرّ التعبير بقوله تعالى: ﴿أَلْزَمْنَاهُ طَائِرَهُ فِي عُنُقِهِ﴾؟","answer":"استعار الطائر للعمل والمصير، والعنق لما لا يفارق صاحبه؛ فلا مهرب من مسؤولية الاختيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص88.","url":""}]},{"id":"s17-40","number":40,"surah":17,"verses":[13],"verseLabel":"الإسراء: 13","question":"ما سرّ التعبير بقوله تعالى: ﴿فِي عُنُقِهِ﴾ لا «على عنقه»؟","answer":"«في» أشد في تصوير اللزوم والتداخل، كأن العمل مطوق ثابت لا موضوع يمكن نزعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص90.","url":""}]},{"id":"s17-41","number":41,"surah":17,"verses":[14],"verseLabel":"الإسراء: 14","question":"ما سرّ التعبير بقوله تعالى: ﴿اقْرَأْ كِتَابَكَ﴾ لا «اتل كتابك»؟","answer":"القراءة أعم في الاطلاع على المكتوب، والمقام مقام مواجهة سجل العمل لا مجرد تلاوة تعبدية.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص98.","url":""}]},{"id":"s17-42","number":42,"surah":17,"verses":[14],"verseLabel":"الإسراء: 14","question":"ما سرّ التعبير بقوله تعالى: ﴿كَفَى بِنَفْسِكَ الْيَوْمَ عَلَيْكَ حَسِيبًا﴾؟","answer":"لأن السجل يبلغ من الوضوح أن صاحبه يحاسب نفسه بنفسه ولا يحتاج إلى شاهد أبلغ منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص99.","url":""}]},{"id":"s17-43","number":43,"surah":17,"verses":[15],"verseLabel":"الإسراء: 15","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى﴾؟","answer":"صوّر الذنب حملًا ثقيلًا، وقرر عدل المسؤولية الفردية فلا تنقل تبعة نفس إلى غيرها.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 15؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-44","number":44,"surah":17,"verses":[15],"verseLabel":"الإسراء: 15","question":"لماذا صرّح بنفي العذاب ولم يصرح بالإثابة قبل إرسال الرسل؟","answer":"لأن المقام دفع توهم المؤاخذة بلا حجة؛ أما الإحسان ففضل لا ظلم فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص110.","url":""}]},{"id":"s17-45","number":45,"surah":17,"verses":[16],"verseLabel":"الإسراء: 16","question":"ما سرّ التعبير بقوله تعالى: ﴿إِذَا أَرَدْنَا أَنْ نُهْلِكَ قَرْيَةً﴾ بـ«إذا»؟","answer":"لأن الكلام في سنة متحققة الوقوع عند تحقق أسبابها، لا في احتمال بعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص116.","url":""}]},{"id":"s17-46","number":46,"surah":17,"verses":[16],"verseLabel":"الإسراء: 16","question":"لماذا خُصّ ﴿مُتْرَفِيهَا﴾؟","answer":"لأن أهل الترف أقدر على توجيه المجتمع، فإذا فسق قادته شاع الفساد واستحق الجميع المؤاخذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص120.","url":""}]},{"id":"s17-47","number":47,"surah":17,"verses":[16],"verseLabel":"الإسراء: 16","question":"ما سرّ التعبير بقوله تعالى: ﴿فَفَسَقُوا فِيهَا﴾ لا «عليها»؟","answer":"«في» تصور تغلغل الفسق في كيان القرية وانتشاره داخلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص121.","url":""}]},{"id":"s17-48","number":48,"surah":17,"verses":[16],"verseLabel":"الإسراء: 16","question":"ما سرّ التعبير بقوله تعالى: ﴿فَدَمَّرْنَاهَا تَدْمِيرًا﴾ لا «أهلكناها»؟","answer":"التدمير أبلغ في استئصال البنية وآثار العمران، وأكده بالمصدر لتصوير تمامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص123.","url":""}]},{"id":"s17-49","number":49,"surah":17,"verses":[18],"verseLabel":"الإسراء: 18","question":"لماذا سمّى الدنيا ﴿الْعَاجِلَةَ﴾؟","answer":"ليفضح قصر نظر طالبها: اختار ما يعجل وينفد وترك ما يبقى.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص134.","url":""}]},{"id":"s17-50","number":50,"surah":17,"verses":[18],"verseLabel":"الإسراء: 18","question":"ما سرّ التعبير بقوله تعالى: ﴿عَجَّلْنَا لَهُ فِيهَا مَا نَشَاءُ لِمَنْ نُرِيدُ﴾؟","answer":"قيّد مطلوبه بالمشيئة والقدر؛ فطالب الدنيا لا ينال كل ما يريد ولا كل طالب ينال.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص135.","url":""}]},{"id":"s17-51","number":51,"surah":17,"verses":[18],"verseLabel":"الإسراء: 18","question":"ما سرّ التعبير بقوله تعالى: ﴿ثُمَّ جَعَلْنَا لَهُ جَهَنَّمَ﴾؟","answer":"«ثم» تبرز الفارق الهائل بين متاع قريب قليل وعاقبة بعيدة ثقيلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص141.","url":""}]},{"id":"s17-52","number":52,"surah":17,"verses":[19],"verseLabel":"الإسراء: 19","question":"ما سرّ التعبير بقوله تعالى: ﴿وَسَعَى لَهَا سَعْيَهَا﴾؟","answer":"الإضافة تفيد السعي اللائق بالآخرة قدرًا ونوعًا، لا أي حركة يدعيها صاحبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص146.","url":""}]},{"id":"s17-53","number":53,"surah":17,"verses":[19],"verseLabel":"الإسراء: 19","question":"لماذا اشترط ﴿وَهُوَ مُؤْمِنٌ﴾ بعد السعي؟","answer":"لأن العمل لا يثمر ثواب الآخرة بلا أصل يوجهه إلى الله ويصدق بوعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص149.","url":""}]},{"id":"s17-54","number":54,"surah":17,"verses":[20],"verseLabel":"الإسراء: 20","question":"ما سرّ التعبير بقوله تعالى: ﴿كُلًّا نُمِدُّ هَؤُلَاءِ وَهَؤُلَاءِ﴾؟","answer":"قدّم «كلا» لإفادة العموم: عطاء الربوبية يصل إلى طالب الدنيا وطالب الآخرة في دار الابتلاء.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 20؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-55","number":55,"surah":17,"verses":[20],"verseLabel":"الإسراء: 20","question":"ما سرّ التعبير بقوله تعالى: ﴿وَمَا كَانَ عَطَاءُ رَبِّكَ مَحْظُورًا﴾؟","answer":"ينفي أن يمنع رزقه الدنيوي عن أحد بسبب كفره؛ فالعطاء هنا امتحان لا علامة رضا.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 20؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-56","number":56,"surah":17,"verses":[21],"verseLabel":"الإسراء: 21","question":"ما سرّ التعبير بقوله تعالى: ﴿انْظُرْ كَيْفَ فَضَّلْنَا بَعْضَهُمْ عَلَى بَعْضٍ﴾؟","answer":"وجّه إلى تفاوت الدنيا المشاهد ليقاس عليه تفاوت الآخرة الأعظم والأبقى.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 21؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-57","number":57,"surah":17,"verses":[22],"verseLabel":"الإسراء: 22","question":"ما سرّ تقديم ﴿مَعَ اللَّهِ﴾ في النهي عن الشرك؟","answer":"لتشنيع مجرد الجمع بين الله وغيره في العبادة، قبل النظر في ماهية الشريك.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص169.","url":""}]},{"id":"s17-58","number":58,"surah":17,"verses":[22],"verseLabel":"الإسراء: 22","question":"لماذا كانت عاقبة الشرك ﴿مَذْمُومًا مَخْذُولًا﴾؟","answer":"يذمه العقلاء على اختياره، ثم يخذله من جعله شريكًا فلا ينصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص169.","url":""}]},{"id":"s17-59","number":59,"surah":17,"verses":[23],"verseLabel":"الإسراء: 23","question":"ما سرّ التعبير بقوله تعالى: ﴿وَقَضَى رَبُّكَ﴾؟","answer":"القضاء يدل على الأمر المحكم الذي لا يقبل التردد، و«ربك» تلطف يربط التكليف بالتربية والنعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص176.","url":""}]},{"id":"s17-60","number":60,"surah":17,"verses":[23],"verseLabel":"الإسراء: 23","question":"لماذا انتقل من حق الله إلى حق الوالدين؟","answer":"لأنهما السبب الظاهر في الوجود والتربية بعد فضل الخالق، فجاء شكرهما عقب توحيده.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 23؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-61","number":61,"surah":17,"verses":[23],"verseLabel":"الإسراء: 23","question":"ما سرّ التعبير بقوله تعالى: ﴿إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ﴾؟","answer":"«عندك» تجعل رعايتهما مسؤولية حاضرة في بيت الولد، والكِبر هو زمن اشتداد حاجتهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص182.","url":""}]},{"id":"s17-62","number":62,"surah":17,"verses":[23],"verseLabel":"الإسراء: 23","question":"لماذا بدأ بالنهي عن كلمة ﴿أُفٍّ﴾؟","answer":"نهى عن أدنى صوت تضجر ليكون ما فوقه من الإيذاء أولى بالتحريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص186.","url":""}]},{"id":"s17-63","number":63,"surah":17,"verses":[23],"verseLabel":"الإسراء: 23","question":"ما سرّ التعبير بقوله تعالى: ﴿قَوْلًا كَرِيمًا﴾؟","answer":"لم يطلب ترك الأذى فقط، بل كلامًا يكرم الوالدين ويشعرهما بالمكانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص187.","url":""}]},{"id":"s17-64","number":64,"surah":17,"verses":[24],"verseLabel":"الإسراء: 24","question":"ما سرّ التعبير بقوله تعالى: ﴿وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ﴾؟","answer":"استعار جناح الطائر لِلين الجانب والحماية، وجعل الذل ناشئًا من الرحمة لا المهانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص190.","url":""}]},{"id":"s17-65","number":65,"surah":17,"verses":[24],"verseLabel":"الإسراء: 24","question":"لماذا دعا بـ﴿رَبِّ ارْحَمْهُمَا﴾ لا «اللهم»؟","answer":"اسم الرب يستحضر التربية التي تلقاها منهما، فيسأل ربه أن يجازيهما برحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص196.","url":""}]},{"id":"s17-66","number":66,"surah":17,"verses":[25],"verseLabel":"الإسراء: 25","question":"ما سرّ التعبير بقوله تعالى: ﴿رَبُّكُمْ أَعْلَمُ بِمَا فِي نُفُوسِكُمْ﴾ لا «بنفوسكم»؟","answer":"«في» تتناول ما يستقر ويجول داخل النفس من قصد خفي لا يطلع عليه الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص202.","url":""}]},{"id":"s17-67","number":67,"surah":17,"verses":[25],"verseLabel":"الإسراء: 25","question":"ما سرّ التعبير بقوله تعالى: ﴿لِلْأَوَّابِينَ غَفُورًا﴾؟","answer":"لأن البر قد تقع فيه هفوة، ففتح المغفرة لمن يكثر الرجوع إلى الله وإصلاح التقصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص204.","url":""}]},{"id":"s17-68","number":68,"surah":17,"verses":[26],"verseLabel":"الإسراء: 26","question":"لماذا جمع بين القريب والمسكين وابن السبيل؟","answer":"ليجمع الحق الناشئ من القرابة، والحاجة المقيمة، والحاجة العارضة في السفر.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 26؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-69","number":69,"surah":17,"verses":[27],"verseLabel":"الإسراء: 27","question":"لماذا سُمّي المبذرون ﴿إِخْوَانَ الشَّيَاطِينِ﴾؟","answer":"لأنهم شابهوهم في إفساد النعمة وصرفها في غير وجهها، فالأخوة أخوة طريقة.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 27؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-70","number":70,"surah":17,"verses":[27],"verseLabel":"الإسراء: 27","question":"ما سرّ التعبير بقوله تعالى: ﴿وَكَانَ الشَّيْطَانُ لِرَبِّهِ كَفُورًا﴾؟","answer":"يربط التبذير بجذره الباطني: كفران النعمة وعدم وضعها فيما أراد المنعم.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 27؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-71","number":71,"surah":17,"verses":[28],"verseLabel":"الإسراء: 28","question":"لماذا سمّى عدم القدرة على العطاء ﴿إِعْرَاضًا﴾؟","answer":"صوّر اضطرار المحتاج إلى الانتظار كأنه صرف للوجه، ثم علّمه أن يجبره بالكلمة الحسنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص221.","url":""}]},{"id":"s17-72","number":72,"surah":17,"verses":[28],"verseLabel":"الإسراء: 28","question":"ما سرّ التعبير بقوله تعالى: ﴿رَحْمَةٍ مِنْ رَبِّكَ تَرْجُوهَا﴾؟","answer":"سمّى الرزق رحمة ليبقى المعطي نفسه راجيًا فضل ربه لا مالكًا مستقلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص225.","url":""}]},{"id":"s17-73","number":73,"surah":17,"verses":[28],"verseLabel":"الإسراء: 28","question":"ما سرّ التعبير بقوله تعالى: ﴿قَوْلًا مَيْسُورًا﴾ لا «معروفًا»؟","answer":"الميسور كلام سهل لطيف يخفف الحرج ويعد بالخير، فكأنه عطاء ميسر حين تعذر المال.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص229.","url":""}]},{"id":"s17-74","number":74,"surah":17,"verses":[29],"verseLabel":"الإسراء: 29","question":"لماذا مثّل البخل بيد مغلولة إلى العنق؟","answer":"يجسد شدة الإمساك بصورة يد لا تستطيع الامتداد أصلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص236.","url":""}]},{"id":"s17-75","number":75,"surah":17,"verses":[29],"verseLabel":"الإسراء: 29","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَا تَبْسُطْهَا كُلَّ الْبَسْطِ﴾؟","answer":"لم ينه عن البسط بل عن استغراقه، فدل على الاقتصاد بين البخل والإسراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص238.","url":""}]},{"id":"s17-76","number":76,"surah":17,"verses":[30],"verseLabel":"الإسراء: 30","question":"ما سرّ التعبير بقوله تعالى: ﴿إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ... وَيَقْدِرُ﴾ بعد الأمر بالاعتدال؟","answer":"ليعلّم أن تفاوت الرزق بتدبير خبير، فلا يحمل الضيق على بخل ولا السعة على إسراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص253.","url":""}]},{"id":"s17-77","number":77,"surah":17,"verses":[30],"verseLabel":"الإسراء: 30","question":"ما سرّ تقديم ﴿بِعِبَادِهِ﴾ في ﴿كَانَ بِعِبَادِهِ خَبِيرًا بَصِيرًا﴾؟","answer":"للاهتمام بمن يجري عليهم البسط والتقدير، وطمأنتهم أن التدبير قائم على علم بأحوالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص256.","url":""}]},{"id":"s17-78","number":78,"surah":17,"verses":[31],"verseLabel":"الإسراء: 31","question":"ما سرّ التعبير هنا بـ﴿خَشْيَةَ إِمْلَاقٍ﴾ وفي الأنعام ﴿مِنْ إِمْلَاقٍ﴾؟","answer":"هنا الفقر متوقع فقدم رزق الأولاد: ﴿نحن نرزقهم وإياكم﴾؛ وهناك الفقر واقع فقدم رزق الآباء: ﴿نحن نرزقكم وإياهم﴾.","sources":[{"label":"الكرماني، أسرار التكرار؛ موسوعة التفسير البلاغي، ج28، ص264؛ مسح عكسي.","url":""}]},{"id":"s17-79","number":79,"surah":17,"verses":[31],"verseLabel":"الإسراء: 31","question":"لماذا وصف قتل الأولاد بأنه ﴿خِطْئًا كَبِيرًا﴾؟","answer":"لأن فيه اعتداء على نفس بريئة وسوء ظن بالرازق وقلبًا لوظيفة الأبوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص267.","url":""}]},{"id":"s17-80","number":80,"surah":17,"verses":[32],"verseLabel":"الإسراء: 32","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَا تَقْرَبُوا الزِّنَا﴾ لا «ولا تزنوا»؟","answer":"ليحرم الفعل وكل الطرق والمقدمات التي تقرب إليه، فيسد الباب قبل الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص273.","url":""}]},{"id":"s17-81","number":81,"surah":17,"verses":[32],"verseLabel":"الإسراء: 32","question":"ما سرّ التعبير بقوله تعالى: ﴿إِنَّهُ كَانَ فَاحِشَةً وَسَاءَ سَبِيلًا﴾؟","answer":"جمع قبح الفعل في ذاته وقبح الطريق الذي يفضي إليه من اختلاط الأنساب وفساد المجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص275.","url":""}]},{"id":"s17-82","number":82,"surah":17,"verses":[33],"verseLabel":"الإسراء: 33","question":"ما سرّ التعبير بقوله تعالى: ﴿النَّفْسَ الَّتِي حَرَّمَ اللَّهُ﴾؟","answer":"أظهر اسم الجلالة ليعظم حرمة النفس؛ فالاعتداء عليها انتهاك لما حرمه الله نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص282.","url":""}]},{"id":"s17-83","number":83,"surah":17,"verses":[33],"verseLabel":"الإسراء: 33","question":"ما سرّ التعبير بقوله تعالى: ﴿فَقَدْ جَعَلْنَا لِوَلِيِّهِ سُلْطَانًا﴾؟","answer":"«سلطانًا» لفظ جامع للحجة والحق والقدرة المشروعة في المطالبة بالقصاص أو العفو.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص289.","url":""}]},{"id":"s17-84","number":84,"surah":17,"verses":[33],"verseLabel":"الإسراء: 33","question":"لماذا نهى الولي عن الإسراف في القتل؟","answer":"حتى لا يتحول إنصاف المظلوم إلى ظلم جديد بتجاوز القاتل إلى غيره أو التمثيل به.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 33؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-85","number":85,"surah":17,"verses":[34],"verseLabel":"الإسراء: 34","question":"لماذا كرر ﴿وَلَا تَقْرَبُوا﴾ مع مال اليتيم؟","answer":"لحماية المال من مقدمات الاعتداء والحيل، لا من أكله الصريح وحده.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 34؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-86","number":86,"surah":17,"verses":[34],"verseLabel":"الإسراء: 34","question":"ما سرّ التعبير بقوله تعالى: ﴿إِنَّ الْعَهْدَ كَانَ مَسْئُولًا﴾ ولم يذكر المسؤول عنه؟","answer":"حذف المتعلق ليعم السؤال عن كل عهد: بين العبد وربه وبينه وبين الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص305.","url":""}]},{"id":"s17-87","number":87,"surah":17,"verses":[35],"verseLabel":"الإسراء: 35","question":"ما سرّ التعبير بقوله تعالى: ﴿وَزِنُوا بِالْقِسْطَاسِ الْمُسْتَقِيمِ﴾؟","answer":"جمع آلة العدل ووصف الاستقامة ليمنع النقص في المعيار وفي استعماله معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص310.","url":""}]},{"id":"s17-88","number":88,"surah":17,"verses":[35],"verseLabel":"الإسراء: 35","question":"ما سرّ التعبير بقوله تعالى: ﴿ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا﴾؟","answer":"العدل خير في الحال، وأحسن عاقبةً ومرجعًا في الثقة والرزق والآخرة.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 35؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-89","number":89,"surah":17,"verses":[36],"verseLabel":"الإسراء: 36","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهِ عِلْمٌ﴾؟","answer":"«تقف» تتبع الأثر؛ فالنهي يشمل اتباع الظن في القول والحكم والسلوك بلا علم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص320.","url":""}]},{"id":"s17-90","number":90,"surah":17,"verses":[36],"verseLabel":"الإسراء: 36","question":"لماذا ذكر ﴿السَّمْعَ وَالْبَصَرَ وَالْفُؤَادَ﴾؟","answer":"جمع منافذ المعرفة الظاهرة وباطن الفهم، ليحمّل الإنسان مسؤولية طريق العلم كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص327.","url":""}]},{"id":"s17-91","number":91,"surah":17,"verses":[36],"verseLabel":"الإسراء: 36","question":"ما سرّ التعبير بقوله تعالى: ﴿الْفُؤَادَ﴾ لا «القلب»؟","answer":"الفؤاد يستحضر القلب في حال التوقد والإدراك، وهو الأنسب لمقام التثبت والشهادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص327.","url":""}]},{"id":"s17-92","number":92,"surah":17,"verses":[37],"verseLabel":"الإسراء: 37","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَا تَمْشِ فِي الْأَرْضِ مَرَحًا﴾ لا «فرحًا»؟","answer":"المرح فرح يتجاوز إلى الخيلاء والبطر، أما الفرح فقد يكون محمودًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص336.","url":""}]},{"id":"s17-93","number":93,"surah":17,"verses":[37],"verseLabel":"الإسراء: 37","question":"لماذا قابل المتكبر بالأرض والجبال؟","answer":"ليحطم وهمه: لن يشق الأرض بخطوه ولن يبلغ الجبال طولًا مهما انتفخ.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 37؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-94","number":94,"surah":17,"verses":[38],"verseLabel":"الإسراء: 38","question":"ما سرّ التعبير بقوله تعالى: ﴿كُلُّ ذَلِكَ كَانَ سَيِّئُهُ﴾ بالإفراد؟","answer":"أعاد اسم الإشارة إلى مجموع الخصال كحزمة أخلاقية واحدة، فجمعها في حكم جامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص347.","url":""}]},{"id":"s17-95","number":95,"surah":17,"verses":[38],"verseLabel":"الإسراء: 38","question":"ما سرّ تقديم ﴿عِنْدَ رَبِّكَ﴾ على ﴿مَكْرُوهًا﴾؟","answer":"ليجعل الميزان أولًا حكم الرب لا ذوق المجتمع، ويعظم قبحها عند المربي المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص349.","url":""}]},{"id":"s17-96","number":96,"surah":17,"verses":[39],"verseLabel":"الإسراء: 39","question":"لماذا سمّى هذه الوصايا ﴿مِنَ الْحِكْمَةِ﴾؟","answer":"لأنها تضع العقيدة والحقوق والسلوك في مواضعها التي تصلح الفرد والمجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص353.","url":""}]},{"id":"s17-97","number":97,"surah":17,"verses":[39],"verseLabel":"الإسراء: 39","question":"لماذا كرر النهي عن الشرك بعد سلسلة الوصايا؟","answer":"ليطوق الأحكام بالتوحيد أولًا وآخرًا، فكل الأخلاق بين أصلها وعاقبتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص357.","url":""}]},{"id":"s17-98","number":98,"surah":17,"verses":[39],"verseLabel":"الإسراء: 39","question":"لماذا اختلفت الخاتمتان: ﴿مذمومًا مخذولًا﴾ و﴿ملومًا مدحورًا﴾؟","answer":"الأولى حال المشرك في الدنيا بين الذم والخذلان، والثانية عاقبته في جهنم بين اللوم والطرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص359.","url":""}]},{"id":"s17-99","number":99,"surah":17,"verses":[40],"verseLabel":"الإسراء: 40","question":"ما سرّ التعبير بقوله تعالى: ﴿أَفَأَصْفَاكُمْ رَبُّكُمْ بِالْبَنِينَ﴾؟","answer":"الاستفهام يفضح تناقضهم: زعموا لأنفسهم ما يحبون ونسبوا إلى الله ما يكرهون.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص366.","url":""}]},{"id":"s17-100","number":100,"surah":17,"verses":[41],"verseLabel":"الإسراء: 41","question":"ما سرّ التعبير بقوله تعالى: ﴿صَرَّفْنَا فِي هَذَا الْقُرْآنِ﴾؟","answer":"التصريف تنويع الحجج والأمثال والأساليب حتى تتفتح للحق طرق متعددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص377.","url":""}]},{"id":"s17-101","number":101,"surah":17,"verses":[41],"verseLabel":"الإسراء: 41","question":"لماذا حذف مفعول ﴿صَرَّفْنَا﴾؟","answer":"ليعم ما صُرف من دلائل التوحيد والبعث والمواعظ والوعد والوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص377.","url":""}]},{"id":"s17-102","number":102,"surah":17,"verses":[41],"verseLabel":"الإسراء: 41","question":"ما سرّ التعبير بقوله تعالى: ﴿وَمَا يَزِيدُهُمْ إِلَّا نُفُورًا﴾؟","answer":"المضارع يصور تجدد نفورهم كلما تجدد البيان، فيكشف أن الخلل في الإرادة لا في الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص379.","url":""}]},{"id":"s17-103","number":103,"surah":17,"verses":[42],"verseLabel":"الإسراء: 42","question":"ما سرّ التعبير بقوله تعالى: ﴿لَابْتَغَوْا إِلَى ذِي الْعَرْشِ سَبِيلًا﴾؟","answer":"ألزمهم بنتيجة دعواهم: لو وجدت آلهة لطلبت منازعة صاحب العرش أو التقرب إليه، وكلاهما يبطل استقلالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص383.","url":""}]},{"id":"s17-104","number":104,"surah":17,"verses":[43],"verseLabel":"الإسراء: 43","question":"ما سرّ التعبير بقوله تعالى: ﴿عُلُوًّا كَبِيرًا﴾ بعد ﴿سُبْحَانَهُ وَتَعَالَى﴾؟","answer":"المصدر المؤكد يقرر أن تنزهه عن الشركاء فوق تصورهم، ووصفه بالكبير يعظم الفارق.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص390.","url":""}]},{"id":"s17-105","number":105,"surah":17,"verses":[44],"verseLabel":"الإسراء: 44","question":"ما سرّ التعبير بقوله تعالى: ﴿وَإِنْ مِنْ شَيْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِ﴾؟","answer":"النفي والاستثناء يستغرقان كل موجود، فيتحول الكون كله إلى شاهد توحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص396.","url":""}]},{"id":"s17-106","number":106,"surah":17,"verses":[44],"verseLabel":"الإسراء: 44","question":"ما سرّ التعبير بقوله تعالى: ﴿لَا تَفْقَهُونَ تَسْبِيحَهُمْ﴾ لا «لا تسمعون»؟","answer":"قد يقع إدراك الصوت ولا يفهم معناه؛ فنفى الفقه الأخص ليبقي حقيقة التسبيح.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص397.","url":""}]},{"id":"s17-107","number":107,"surah":17,"verses":[44],"verseLabel":"الإسراء: 44","question":"لماذا ختم بـ﴿حَلِيمًا غَفُورًا﴾؟","answer":"مع أن الكون يسبحه والإنسان يقصر أو يشرك، يمهله بحلمه ويفتح له المغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص403.","url":""}]},{"id":"s17-108","number":108,"surah":17,"verses":[45],"verseLabel":"الإسراء: 45","question":"لماذا صار بين النبي والكافرين ﴿حِجَابًا مَسْتُورًا﴾ عند قراءة القرآن؟","answer":"هو حجاب خفي لا تراه العيون، يحول بسبب عنادهم دون الانتفاع لا دون سماع الألفاظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص408.","url":""}]},{"id":"s17-109","number":109,"surah":17,"verses":[46],"verseLabel":"الإسراء: 46","question":"ما سرّ التعبير بقوله تعالى: ﴿عَلَى قُلُوبِهِمْ أَكِنَّةً﴾ و﴿فِي آذَانِهِمْ وَقْرًا﴾؟","answer":"الأكنة تعلو القلب فتغطيه، والوقر مستقر داخل الأذن؛ فوافق كل حرف صورته.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص417.","url":""}]},{"id":"s17-110","number":110,"surah":17,"verses":[46],"verseLabel":"الإسراء: 46","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَّوْا عَلَى أَدْبَارِهِمْ نُفُورًا﴾؟","answer":"لم يكتف بالإعراض، بل صور فرارًا ظاهرًا سريعًا كلما انفرد الله بالذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص420.","url":""}]},{"id":"s17-111","number":111,"surah":17,"verses":[47],"verseLabel":"الإسراء: 47","question":"ما سرّ التعبير بقوله تعالى: ﴿نَحْنُ أَعْلَمُ بِمَا يَسْتَمِعُونَ بِهِ﴾؟","answer":"يكشف أن استماعهم لم يكن طلب هدى بل ترصدًا واستهزاء، والله أعلم بدافع السماع الخفي.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 47؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-112","number":112,"surah":17,"verses":[47],"verseLabel":"الإسراء: 47","question":"لماذا سمّى تناجيهم ﴿نَجْوَى﴾؟","answer":"لأنه حديث خافت يتسترون به عن المؤمنين، لكن خفاءه لا يحجبه عن علم الله.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 47؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-113","number":113,"surah":17,"verses":[48],"verseLabel":"الإسراء: 48","question":"ما سرّ التعبير بقوله تعالى: ﴿انْظُرْ كَيْفَ ضَرَبُوا لَكَ الْأَمْثَالَ﴾؟","answer":"لفت إلى اضطراب أوصافهم للنبي: ساحر وشاعر ومجنون؛ فتعددها دليل حيرتهم.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 48؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-114","number":114,"surah":17,"verses":[49],"verseLabel":"الإسراء: 49","question":"لماذا جمعوا بين ﴿عِظَامًا وَرُفَاتًا﴾؟","answer":"ذكروا بقايا الجسد الصلبة ثم المفتتة ليبالغوا في استبعاد الإعادة.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 49؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-115","number":115,"surah":17,"verses":[50],"verseLabel":"الإسراء: 50","question":"ما سرّ التعبير بقوله تعالى: لهم ﴿كُونُوا حِجَارَةً أَوْ حَدِيدًا﴾؟","answer":"حتى لو تحولوا في وهمهم إلى أصلب ما يعرفون، فلن يعجز الخالق عن إعادتهم.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 50؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-116","number":116,"surah":17,"verses":[51],"verseLabel":"الإسراء: 51","question":"ما سرّ التعبير بقوله تعالى: ﴿أَوْ خَلْقًا مِمَّا يَكْبُرُ فِي صُدُورِكُمْ﴾؟","answer":"عمم إلى أي خلق يرونه أشد امتناعًا، فيقطع كل مهرب يتخيله المنكر.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 51؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-117","number":117,"surah":17,"verses":[52],"verseLabel":"الإسراء: 52","question":"لماذا وصف يوم البعث بأنه ﴿يَوْمَ يَدْعُوكُمْ فَتَسْتَجِيبُونَ بِحَمْدِهِ﴾؟","answer":"صوّر البعث دعوةً من الله تعقبها استجابة لا يملكون التخلف عنها؛ و﴿بحمده﴾ تحتمل أنهم يبعثون حامدين، أو مستجيبين لأمره وطاعته.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 52؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-118","number":118,"surah":17,"verses":[52],"verseLabel":"الإسراء: 52","question":"لماذا يظنون أنهم لبثوا ﴿إِلَّا قَلِيلًا﴾؟","answer":"لهول ما يشاهدون يصغر في نفوسهم طول الدنيا أو القبور حتى يبدو لحظة.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 52؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-119","number":119,"surah":17,"verses":[53],"verseLabel":"الإسراء: 53","question":"ما سرّ التعبير بقوله تعالى: ﴿يَقُولُوا الَّتِي هِيَ أَحْسَنُ﴾ ولم يقل «قولًا حسنًا»؟","answer":"أمر باختيار الأحسن من البدائل، لأن كلمة صحيحة بعبارة خشنة قد تفتح باب النزاع.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 53؛ موسوعة التفسير البلاغي، ج28، ص484–485.","url":""}]},{"id":"s17-120","number":120,"surah":17,"verses":[53],"verseLabel":"الإسراء: 53","question":"لماذا علّل حسن القول بأن ﴿الشَّيْطَانَ يَنْزَغُ بَيْنَهُمْ﴾؟","answer":"لأن الشيطان يستثمر الكلمة المحتملة ويحول الخلاف الصغير إلى عداوة.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 53؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-121","number":121,"surah":17,"verses":[54],"verseLabel":"الإسراء: 54","question":"ما سرّ التعبير بقوله تعالى: ﴿رَبُّكُمْ أَعْلَمُ بِكُمْ﴾ بعد الأمر بأحسن القول؟","answer":"ليمنع المؤمن من تزكية نفسه والحكم النهائي على غيره؛ فمصائر العباد إلى علم ربهم.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 54؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-122","number":122,"surah":17,"verses":[55],"verseLabel":"الإسراء: 55","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَقَدْ فَضَّلْنَا بَعْضَ النَّبِيِّينَ عَلَى بَعْضٍ﴾؟","answer":"ليرد اعتراضهم على اختيار محمد؛ فالتفضيل بين الرسل سنة ربانية لا حق للمقترحين فيها.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 55؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-123","number":123,"surah":17,"verses":[55],"verseLabel":"الإسراء: 55","question":"لماذا خُص داود بإيتاء الزبور؟","answer":"مثال قريب على تفاضل مواهب الأنبياء وكتبهم، مع اشتراكهم في أصل النبوة.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 55؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-124","number":124,"surah":17,"verses":[56],"verseLabel":"الإسراء: 56","question":"ما سرّ التعبير بقوله تعالى: ﴿فَلَا يَمْلِكُونَ كَشْفَ الضُّرِّ عَنْكُمْ وَلَا تَحْوِيلًا﴾؟","answer":"نفى قدرتهم على إزالة الضر وعلى نقله إلى جهة أخرى، فاستوعب وجهي الخلاص.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 56؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-125","number":125,"surah":17,"verses":[57],"verseLabel":"الإسراء: 57","question":"ما سرّ التعبير بقوله تعالى: عن المعبودين ﴿يَبْتَغُونَ إِلَى رَبِّهِمُ الْوَسِيلَةَ﴾؟","answer":"من يعبدونهم هم أنفسهم عباد يطلبون القرب من الله، فكيف يُجعل المحتاج إلهًا؟","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 57؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-126","number":126,"surah":17,"verses":[58],"verseLabel":"الإسراء: 58","question":"ما سرّ التعبير بقوله تعالى: ﴿وَإِنْ مِنْ قَرْيَةٍ إِلَّا نَحْنُ مُهْلِكُوهَا﴾؟","answer":"ليقرر فناء العمران كله بالموت أو العذاب، فلا تغرهم قوة مدينة أو دوام حضارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص548.","url":""}]},{"id":"s17-127","number":127,"surah":17,"verses":[58],"verseLabel":"الإسراء: 58","question":"لماذا نُكرت ﴿قَرْيَةٍ﴾؟","answer":"لوقوعها في سياق النفي والاستثناء فتعم كل قرية بلا استثناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص552.","url":""}]},{"id":"s17-128","number":128,"surah":17,"verses":[59],"verseLabel":"الإسراء: 59","question":"لماذا سُمّيت الناقة ﴿مُبْصِرَةً﴾؟","answer":"أي آية واضحة تُبصر الناس بالحق، أو ذات علامة ظاهرة لا تلتبس.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 59؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-129","number":129,"surah":17,"verses":[59],"verseLabel":"الإسراء: 59","question":"ما سرّ التعبير بقوله تعالى: ﴿وَمَا نُرْسِلُ بِالْآيَاتِ إِلَّا تَخْوِيفًا﴾؟","answer":"ليبين أن الآيات المقترحة ليست فرجة؛ إن كُذب بها صارت مقدمة للعذاب.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 59؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-130","number":130,"surah":17,"verses":[60],"verseLabel":"الإسراء: 60","question":"لماذا سميت الرؤيا والشجرة ﴿فِتْنَةً لِلنَّاسِ﴾؟","answer":"لأن الخبر الخارق يكشف المصدق من المكابر، كما كشفت الشجرة المذكورة من يسخر من الغيب.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 60؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-131","number":131,"surah":17,"verses":[61],"verseLabel":"الإسراء: 61","question":"ما دلالة قول إبليس: ﴿أَأَسْجُدُ لِمَنْ خَلَقْتَ طِينًا﴾؟","answer":"حذف «من» قبل طين أو ضمن الخلق معنى التكوين، ليجعل مادة آدم محور اعتراضه المتكبر.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 61؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-132","number":132,"surah":17,"verses":[62],"verseLabel":"الإسراء: 62","question":"ما دلالة قول إبليس: ﴿لَأَحْتَنِكَنَّ ذُرِّيَّتَهُ﴾؟","answer":"الاحتناك أخذ الدابة بحنكها وقيادها؛ فصوّر طمعه في الاستيلاء على أكثر البشر.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 62؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-133","number":133,"surah":17,"verses":[63],"verseLabel":"الإسراء: 63","question":"لماذا جاء الرد ﴿اذْهَبْ﴾؟","answer":"أمر إهانة وتهديد: امض في اختيارك، وسترى أنت وأتباعك الجزاء الموفور.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 63؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-134","number":134,"surah":17,"verses":[64],"verseLabel":"الإسراء: 64","question":"ما سرّ التعبير بقوله تعالى: ﴿وَاسْتَفْزِزْ مَنِ اسْتَطَعْتَ مِنْهُمْ بِصَوْتِكَ﴾؟","answer":"الاستفزاز استخفاف يزعج الإنسان من موضعه، والصوت يشمل كل دعوة تثيره إلى المعصية.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 64؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-135","number":135,"surah":17,"verses":[64],"verseLabel":"الإسراء: 64","question":"ما سرّ التعبير بقوله تعالى: ﴿وَأَجْلِبْ عَلَيْهِمْ بِخَيْلِكَ وَرَجِلِكَ﴾؟","answer":"استعارة لحشد وسائل الإغواء كلها، السريعة والبطيئة، كجيش يحيط بفريسته.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 64؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-136","number":136,"surah":17,"verses":[64],"verseLabel":"الإسراء: 64","question":"لماذا وُصف وعد الشيطان بأنه ﴿غُرُورًا﴾؟","answer":"لأنه يزين منفعة عاجلة ويخفي خسارتها، فحقيقته خداع لا وعد.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 64؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-137","number":137,"surah":17,"verses":[65],"verseLabel":"الإسراء: 65","question":"ما سرّ التعبير بقوله تعالى: ﴿لَيْسَ لَكَ عَلَيْهِمْ سُلْطَانٌ﴾؟","answer":"يطَمئن عباد الله أن الشيطان يوسوس ولا يملك إجبار القلب الذي احتمى بربه.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 65؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-138","number":138,"surah":17,"verses":[66],"verseLabel":"الإسراء: 66","question":"ما سرّ التعبير بقوله تعالى: ﴿يُزْجِي لَكُمُ الْفُلْكَ﴾؟","answer":"الإزجاء سوق الشيء برفق؛ يصور السفن الضخمة منقادة بتدبير الله فوق البحر.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 66؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-139","number":139,"surah":17,"verses":[67],"verseLabel":"الإسراء: 67","question":"ما سرّ التعبير بقوله تعالى: ﴿ضَلَّ مَنْ تَدْعُونَ إِلَّا إِيَّاهُ﴾ عند ضر البحر؟","answer":"غاب عن وعيهم كل معبود وبقي الله وحده؛ فالشدّة تكشف التوحيد الكامن تحت الوهم.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 67؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-140","number":140,"surah":17,"verses":[67],"verseLabel":"الإسراء: 67","question":"ما سرّ التعبير بقوله تعالى: ﴿وَكَانَ الْإِنْسَانُ كَفُورًا﴾؟","answer":"لأن عودته إلى الإعراض بعد النجاة ليست نسيانًا عابرًا بل كفران متكرر للنعمة.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 67؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-141","number":141,"surah":17,"verses":[68],"verseLabel":"الإسراء: 68","question":"لماذا خوّفهم بالخسف في البر بعد نجاتهم من البحر؟","answer":"ليبيّن أن الأمان ليس في المكان؛ من نجاهم في البحر قادر أن يأخذهم في اليابسة.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 68؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-142","number":142,"surah":17,"verses":[69],"verseLabel":"الإسراء: 69","question":"ما سرّ التعبير بقوله تعالى: ﴿قَاصِفًا مِنَ الرِّيحِ﴾؟","answer":"القاصف ريح شديدة تكسر ما تمر به، فتلائم مشهد السفن المحطمة والغرق.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 69؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-143","number":143,"surah":17,"verses":[70],"verseLabel":"الإسراء: 70","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَقَدْ كَرَّمْنَا بَنِي آدَمَ﴾ لا «المؤمنين»؟","answer":"التكريم هنا أصلي عام للنوع الإنساني بالعقل والهيئة والتسخير، ثم تتفاوت الكرامة بالإيمان.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 70؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-144","number":144,"surah":17,"verses":[70],"verseLabel":"الإسراء: 70","question":"لماذا جمع بين الحمل في البر والبحر؟","answer":"لاستيعاب وجهي التنقل المعروفين وإظهار تسخير البيئتين المتباينتين للإنسان.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 70؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-145","number":145,"surah":17,"verses":[71],"verseLabel":"الإسراء: 71","question":"ما سرّ التعبير بقوله تعالى: ﴿نَدْعُو كُلَّ أُنَاسٍ بِإِمَامِهِمْ﴾؟","answer":"يُحشرون مع من اقتدوا به أو مع كتاب أعمالهم، فينكشف اتجاههم الذي اختاروه في الدنيا.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 71؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-146","number":146,"surah":17,"verses":[71],"verseLabel":"الإسراء: 71","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَا يُظْلَمُونَ فَتِيلًا﴾؟","answer":"الفتيل خيط دقيق في شق النواة؛ اختير لتصوير انتفاء أدنى قدر من الظلم.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 71؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-147","number":147,"surah":17,"verses":[72],"verseLabel":"الإسراء: 72","question":"لماذا ربط عمى الآخرة بعمى الدنيا؟","answer":"لأن من تعامى عن دلائل الهدى هنا يُبعث على أثر اختياره أشد حيرة وبعدًا عن الطريق.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 72؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-148","number":148,"surah":17,"verses":[73],"verseLabel":"الإسراء: 73","question":"ما سرّ التعبير بقوله تعالى: ﴿لَيَفْتِنُونَكَ عَنِ الَّذِي أَوْحَيْنَا إِلَيْكَ﴾؟","answer":"الفتنة محاولة صرف تحت الضغط والإغراء، والوحي هو المعيار الذي أرادوا التنازل عنه.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 73؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-149","number":149,"surah":17,"verses":[74],"verseLabel":"الإسراء: 74","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَوْلَا أَنْ ثَبَّتْنَاكَ﴾؟","answer":"نسب الثبات إلى فضل الله ليعلّم أن العصمة والتوفيق مدد رباني لا استقلال بشري.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 74؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-150","number":150,"surah":17,"verses":[75],"verseLabel":"الإسراء: 75","question":"لماذا ضوعف العذاب في الحياة والممات لو وقع الركون؟","answer":"لأن منزلة الرسول وحجم أثره يجعلان زلته المفترضة أعظم من زلة غيره.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 75؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-151","number":151,"surah":17,"verses":[76],"verseLabel":"الإسراء: 76","question":"ما سرّ التعبير بقوله تعالى: ﴿لَيَسْتَفِزُّونَكَ مِنَ الْأَرْضِ﴾؟","answer":"الاستفزاز إزعاج بعنف وخفة، فيصور محاولتهم اقتلاعه من وطنه لا مجرد إخراجه.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 76؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-152","number":152,"surah":17,"verses":[77],"verseLabel":"الإسراء: 77","question":"ما سرّ التعبير بقوله تعالى: ﴿سُنَّةَ مَنْ قَدْ أَرْسَلْنَا قَبْلَكَ﴾؟","answer":"يثبت أن إخراج الرسل يعقبه هلاك المكذبين، وأن ما يواجهه ليس حادثًا بلا نظير.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 77.","url":""}]},{"id":"s17-153","number":153,"surah":17,"verses":[78],"verseLabel":"الإسراء: 78","question":"لماذا عبّر بـ﴿لِدُلُوكِ الشَّمْسِ﴾؟","answer":"الدلوك لفظ يتسع لزوال الشمس وغروبها، فيجمع ابتداء أوقات صلوات النهار والليل.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 78؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-154","number":154,"surah":17,"verses":[78],"verseLabel":"الإسراء: 78","question":"لماذا سميت صلاة الفجر ﴿قُرْآنَ الْفَجْرِ﴾؟","answer":"لأن القراءة ركنها الظاهر المشهود، فسميت الصلاة بأبرز ما فيها.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 78؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-155","number":155,"surah":17,"verses":[78],"verseLabel":"الإسراء: 78","question":"لماذا كان قرآن الفجر ﴿مَشْهُودًا﴾؟","answer":"تشهده ملائكة الليل والنهار، وهو وقت اجتماع السكون وبداية الحركة وحضور القلب.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 78؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-156","number":156,"surah":17,"verses":[79],"verseLabel":"الإسراء: 79","question":"ما سرّ التعبير بقوله تعالى: ﴿نَافِلَةً لَكَ﴾ في قيام الليل؟","answer":"هو زيادة في حقه على الفرائض، وسبب لمقام محمود يخصه يوم القيامة.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 79؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-157","number":157,"surah":17,"verses":[80],"verseLabel":"الإسراء: 80","question":"لماذا جمع الدعاء بين ﴿مُدْخَلَ صِدْقٍ﴾ و﴿مُخْرَجَ صِدْقٍ﴾؟","answer":"ليحيط الصدق ببدايات الانتقال ونهاياته، فلا يكون دخول ولا خروج إلا بحق وعاقبة محمودة.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 80؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-158","number":158,"surah":17,"verses":[80],"verseLabel":"الإسراء: 80","question":"لماذا طلب ﴿سُلْطَانًا نَصِيرًا﴾؟","answer":"لأن الحق يحتاج حجةً وقوةً تحميه من العدوان وتمكنه من إقامة العدل.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 80؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-159","number":159,"surah":17,"verses":[81],"verseLabel":"الإسراء: 81","question":"ما سرّ التعبير بقوله تعالى: ﴿جَاءَ الْحَقُّ وَزَهَقَ الْبَاطِلُ﴾؟","answer":"جعل الحق وافدًا ثابتًا، والباطل روحًا تخرج سريعًا؛ فصور طبيعتهما لا حادثة واحدة.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 81؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-160","number":160,"surah":17,"verses":[82],"verseLabel":"الإسراء: 82","question":"كيف يكون القرآن ﴿شِفَاءٌ وَرَحْمَةٌ﴾ ويزيد الظالمين خسارًا؟","answer":"القرآن يزيل عن المؤمنين ضلال العقائد وفساد الأعمال والأخلاق، فهو لهم شفاء ورحمة؛ أما الظالمون فتزيدهم آياته خسارًا بإعراضهم وكفرهم بها.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 82؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-161","number":161,"surah":17,"verses":[83],"verseLabel":"الإسراء: 83","question":"ما سرّ التعبير بقوله تعالى: ﴿نَأَى بِجَانِبِهِ﴾ لا «ابتعد»؟","answer":"يصوّر الإعراض بحركة الجنب المتكبر، كأنه يصرف نفسه كلها عن المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص12.","url":""}]},{"id":"s17-162","number":162,"surah":17,"verses":[83],"verseLabel":"الإسراء: 83","question":"ما سرّ التعبير بقوله تعالى: عند الشر ﴿كَانَ يَئُوسًا﴾؟","answer":"كشف تذبذب من تعلق بالأسباب: بطر عند النعمة وقنوط عند زوالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص17.","url":""}]},{"id":"s17-163","number":163,"surah":17,"verses":[84],"verseLabel":"الإسراء: 84","question":"ما سرّ التعبير بقوله تعالى: ﴿كُلٌّ يَعْمَلُ عَلَى شَاكِلَتِهِ﴾؟","answer":"الشاكلة الهيئة والطبع والطريقة؛ فالعمل يخرج كاشفًا للبنية الداخلية لصاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص25.","url":""}]},{"id":"s17-164","number":164,"surah":17,"verses":[85],"verseLabel":"الإسراء: 85","question":"لماذا جاء جواب سؤال الروح ﴿مِنْ أَمْرِ رَبِّي﴾؟","answer":"ردّهم من طلب الإحاطة بسرها إلى أصل كافٍ: هي من شأن الله وتكوينه الذي لا يحيطون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص35.","url":""}]},{"id":"s17-165","number":165,"surah":17,"verses":[85],"verseLabel":"الإسراء: 85","question":"ما سرّ التعبير بقوله تعالى: ﴿وَمَا أُوتِيتُمْ مِنَ الْعِلْمِ إِلَّا قَلِيلًا﴾؟","answer":"ليضع السؤال في حجمه: جهل حقيقة الروح مثال على محدودية العلم البشري كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص44.","url":""}]},{"id":"s17-166","number":166,"surah":17,"verses":[86],"verseLabel":"الإسراء: 86","question":"ما سرّ التعبير بقوله تعالى: ﴿لَنَذْهَبَنَّ بِالَّذِي أَوْحَيْنَا إِلَيْكَ﴾؟","answer":"ذكّر أن بقاء القرآن فضل متجدد؛ فالذي أنزله قادر على رفعه ولا يستبقيه أحد سواه.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 86؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-167","number":167,"surah":17,"verses":[87],"verseLabel":"الإسراء: 87","question":"لماذا استثنى ﴿إِلَّا رَحْمَةً مِنْ رَبِّكَ﴾؟","answer":"بقاء الوحي وتعليمه رحمة محضة، لا حقًا اكتسبه البشر على الله.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 87؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-168","number":168,"surah":17,"verses":[88],"verseLabel":"الإسراء: 88","question":"لماذا جمع الإنس والجن في تحدي القرآن؟","answer":"ليستوعب جميع العقلاء القادرين على البيان، ثم ينفي قدرتهم ولو تعاونوا.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 88.","url":""}]},{"id":"s17-169","number":169,"surah":17,"verses":[88],"verseLabel":"الإسراء: 88","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَوْ كَانَ بَعْضُهُمْ لِبَعْضٍ ظَهِيرًا﴾؟","answer":"حتى لا ينسب عجزهم إلى التفرق؛ فالمساندة القصوى لا تنتج مثل القرآن.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 88.","url":""}]},{"id":"s17-170","number":170,"surah":17,"verses":[89],"verseLabel":"الإسراء: 89","question":"ما سرّ التعبير بقوله تعالى: ﴿صَرَّفْنَا لِلنَّاسِ فِي هَذَا الْقُرْآنِ مِنْ كُلِّ مَثَلٍ﴾؟","answer":"نوّع البيان ووجّهه للناس ليقطع عذر من يطلب صورة أخرى للحجة.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 89؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-171","number":171,"surah":17,"verses":[90,91,92,93],"verseLabel":"الإسراء: 90-93","question":"لماذا سردوا اقتراحات حسية متتابعة بعد عجزهم عن القرآن؟","answer":"هربوا من الآية القائمة إلى شروط يضعونها هم، فتكشف كثرتها أن المشكلة تعنت لا طلب برهان.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 90-93؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-172","number":172,"surah":17,"verses":[93],"verseLabel":"الإسراء: 93","question":"لماذا كان الجواب ﴿هَلْ كُنْتُ إِلَّا بَشَرًا رَسُولًا﴾؟","answer":"البشرية لا تمنع الرسالة، لكنها تمنع ادعاء خزائن القدرة؛ وظيفة الرسول البلاغ لا تنفيذ الأهواء.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 93؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-173","number":173,"surah":17,"verses":[94],"verseLabel":"الإسراء: 94","question":"لماذا منع الناسَ الإيمانَ قولهم ﴿أَبَعَثَ اللَّهُ بَشَرًا رَسُولًا﴾؟","answer":"استنكروا أن يكون الرسول من جنسهم، مع أن ذلك هو الذي يتيح فهمه والاقتداء به.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 94؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-174","number":174,"surah":17,"verses":[95],"verseLabel":"الإسراء: 95","question":"لماذا لو كان في الأرض ملائكة لنزل إليهم ملك رسولًا؟","answer":"الرسول ينبغي أن يكون من جنس المرسل إليهم ليعيش أحوالهم وتقوم بهم حجة الاقتداء.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 95؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-175","number":175,"surah":17,"verses":[96],"verseLabel":"الإسراء: 96","question":"لماذا كفى بالله شهيدًا بين الرسول وقومه؟","answer":"لأن علمه بخفايا عباده وبصره بأعمالهم يجعل شهادته أصدق وأحاط من كل شهادة.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 96؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-176","number":176,"surah":17,"verses":[97],"verseLabel":"الإسراء: 97","question":"لماذا يحشر الكافرون ﴿عُمْيًا وَبُكْمًا وَصُمًّا﴾؟","answer":"جزاء مناسب لتعطيلهم وسائل الهداية في الدنيا، وحال تزيدهم ذلًا وحيرة.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 97؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-177","number":177,"surah":17,"verses":[97],"verseLabel":"الإسراء: 97","question":"ما سرّ التعبير بقوله تعالى: ﴿كُلَّمَا خَبَتْ زِدْنَاهُمْ سَعِيرًا﴾؟","answer":"يبطل توهم انطفاء النار أو انتهاء الألم؛ كل فتور يعقبه اشتعال أشد.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 97؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-178","number":178,"surah":17,"verses":[99],"verseLabel":"الإسراء: 99","question":"لماذا استدل بخلق السماوات والأرض على إعادة البشر؟","answer":"من قدر على الأعظم ابتداءً لا يعجز عن إعادة الأصغر بعد موته.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 99؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-179","number":179,"surah":17,"verses":[100],"verseLabel":"الإسراء: 100","question":"ما سرّ التعبير بقوله تعالى: عن الإنسان ﴿قَتُورًا﴾ لو ملك خزائن الرحمة؟","answer":"صيغة فعول تصور شدة الإمساك؛ فالإنسان يخشى النفاد حتى لو ملك ما لا ينفد.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 100؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-180","number":180,"surah":17,"verses":[101],"verseLabel":"الإسراء: 101","question":"لماذا وُصفت آيات موسى بأنها ﴿تِسْعَ آيَاتٍ بَيِّنَاتٍ﴾؟","answer":"حدّدها وعدّها ووصفها بالوضوح ليبين أن كثرة الخوارق لم تنفع من استكبر.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 101؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-181","number":181,"surah":17,"verses":[102],"verseLabel":"الإسراء: 102","question":"ما دلالة قول موسى: لفرعون ﴿مَثْبُورًا﴾؟","answer":"المثبور الهالك المصروف عن الخير؛ فقابل اتهام فرعون له بالوضوح عن عاقبة المكذب.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 102؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-182","number":182,"surah":17,"verses":[103],"verseLabel":"الإسراء: 103","question":"ما سرّ التعبير بقوله تعالى: ﴿فَأَرَادَ أَنْ يَسْتَفِزَّهُمْ مِنَ الْأَرْضِ فَأَغْرَقْنَاهُ﴾؟","answer":"قابل إرادة اقتلاع المؤمنين باقتلاع الطاغية نفسه؛ فارتد تدبيره عليه.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 103؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-183","number":183,"surah":17,"verses":[104],"verseLabel":"الإسراء: 104","question":"ما سرّ التعبير بقوله تعالى: ﴿اسْكُنُوا الْأَرْضَ﴾ لبني إسرائيل بعد فرعون؟","answer":"نقلهم من الاستضعاف والإخراج إلى الاستقرار، ثم ذكّر أن السكن مؤقت إلى وعد الآخرة.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 104.","url":""}]},{"id":"s17-184","number":184,"surah":17,"verses":[105],"verseLabel":"الإسراء: 105","question":"لماذا كرر ﴿بِالْحَقِّ أَنْزَلْنَاهُ وَبِالْحَقِّ نَزَلَ﴾؟","answer":"الأولى لحق مصدره وغايته، والثانية لسلامة وصوله وتنزله من التبديل.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 105؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-185","number":185,"surah":17,"verses":[106],"verseLabel":"الإسراء: 106","question":"لماذا نزل القرآن ﴿عَلَى مُكْثٍ﴾؟","answer":"ليتلقاه الناس بتثبت وتدرج، ويحفظوه ويعملوا به مع تجدد الوقائع.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 106؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-186","number":186,"surah":17,"verses":[107],"verseLabel":"الإسراء: 107","question":"ما سرّ التعبير بقوله تعالى: ﴿آمِنُوا بِهِ أَوْ لَا تُؤْمِنُوا﴾؟","answer":"ليس تسوية بين الحالين، بل تهديد: حقيقة القرآن لا تتوقف على قبولهم وقد عرفها أهل العلم.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 107؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-187","number":187,"surah":17,"verses":[107],"verseLabel":"الإسراء: 107","question":"لماذا يخر أهل العلم ﴿لِلْأَذْقَانِ سُجَّدًا﴾؟","answer":"ذكر الذقن يبالغ في تصوير السقوط حتى يقترب الوجه كله من الأرض.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 107؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-188","number":188,"surah":17,"verses":[109],"verseLabel":"الإسراء: 109","question":"لماذا كرر الخرور في ﴿وَيَخِرُّونَ لِلْأَذْقَانِ يَبْكُونَ﴾؟","answer":"التكرار ليس لخرورين مختلفين؛ بل هو خرور واحد أعيد ذكره للاهتمام بحاليه المصاحبتين: السجود والبكاء، وتمهيدًا لذكر ازدياد الخشوع.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 109؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-189","number":189,"surah":17,"verses":[110],"verseLabel":"الإسراء: 110","question":"ما سرّ التعبير بقوله تعالى: ﴿ادْعُوا اللَّهَ أَوِ ادْعُوا الرَّحْمَنَ﴾؟","answer":"يرد توهم تعدد المسمى بتعدد الاسم؛ الأسماء الحسنى كلها لمسمى واحد.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 110؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-190","number":190,"surah":17,"verses":[110],"verseLabel":"الإسراء: 110","question":"لماذا نُهي عن الجهر الشديد والمخافتة في الصلاة؟","answer":"نُهي عن شدة الجهر حتى لا يثير ذلك المشركين ويزيد تصلبهم، وعن شدة الإسرار حتى يسمع المتهيئون للاهتداء؛ فطُلب طريق وسط يحقق المقصودين.","sources":[{"label":"التحرير والتنوير، تفسير الإسراء 110؛ النص مقابل مباشرة في صفحة التفسير.","url":""}]},{"id":"s17-191","number":191,"surah":17,"verses":[111],"verseLabel":"الإسراء: 111","question":"لماذا خُتمت السورة بالحمد بعد أن افتتحت بالتسبيح؟","answer":"التسبيح تنزيه عن النقص، والحمد إثبات للكمال؛ فاستوعبت السورة طرفي التعظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص397؛ التحرير والتنوير، تفسير الإسراء 111.","url":""}]},{"id":"s17-192","number":192,"surah":17,"verses":[111],"verseLabel":"الإسراء: 111","question":"لماذا نُفي الولد والشريك والولي في خاتمة السورة؟","answer":"نُفي ما يوهم الحاجة في البقاء أو الملك أو دفع الذل، فثبت كمال غناه وسلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص397.","url":""}]},{"id":"s17-193","number":193,"surah":17,"verses":[111],"verseLabel":"الإسراء: 111","question":"ما سرّ التعبير بـ﴿وَكَبِّرْهُ تَكْبِيرًا﴾؟","answer":"أُكد الأمر بالمصدر للمبالغة في تعظيم الله وتنزيهه عن كل ما لا يليق بكماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص401.","url":""}]},{"id":"s18-1","number":1,"surah":18,"verses":[1],"verseLabel":"الكهف: 1","question":"لماذا افتتحت سورة الكهف بـ﴿الْحَمْدُ لِلَّهِ﴾؟","answer":"لأن إنزال القرآن من أعظم نعم الله على عباده؛ فهو سبب هدايتهم وصلاح دنياهم ونجاتهم، فاستحق الله عليه أكمل الحمد.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص399–402.","url":""}]},{"id":"s18-2","number":2,"surah":18,"verses":[1],"verseLabel":"الكهف: 1","question":"ما سرّ التعبير بـ﴿عَلَى عَبْدِهِ﴾ دون «على رسوله»؟","answer":"وصفه بالعبودية تنويهٌ بمنزلته ورفعٌ لقدره بإنزال الكتاب عليه، مع تقرير أنه مهما علت منزلته فهو عبد لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص404–405.","url":""}]},{"id":"s18-3","number":3,"surah":18,"verses":[1],"verseLabel":"الكهف: 1","question":"ما سرّ تقديم نفي العوج في ﴿وَلَمْ يَجْعَلْ لَهُ عِوَجًا﴾ على وصف الكتاب بـ﴿قَيِّمًا﴾؟","answer":"نُفي عنه الخلل والميل أولًا، ثم أُثبت له كمال الاستقامة والاعتدال؛ فجمع سلامته من النقص وثبوت الكمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص407–410.","url":""}]},{"id":"s18-4","number":4,"surah":18,"verses":[1,2],"verseLabel":"الكهف: 1-2","question":"لماذا جمع بين نفي العوج ووصف الكتاب بأنه ﴿قَيِّمًا﴾؟","answer":"لأن نفي العوج يثبت خلوه من الخلل والتناقض، ووصفه بالقيم يثبت استقامته وقيامه بمصالح العباد؛ فليس الوصفان تكرارًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص407–412.","url":""}]},{"id":"s18-5","number":5,"surah":18,"verses":[2],"verseLabel":"الكهف: 2","question":"ما سرّ التعبير بـ﴿بَأْسًا شَدِيدًا مِنْ لَدُنْهُ﴾؟","answer":"زاد وصف البأس بالشدة تهويلًا، ودلت ﴿من لدنه﴾ على أن هذا البأس صادر من عند الله، و«لدن» أخص في معنى القرب والصدور من «عند».","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص420–421.","url":""}]},{"id":"s18-6","number":6,"surah":18,"verses":[2],"verseLabel":"الكهف: 2","question":"ما سرّ تقديم الإنذار على البشارة؟","answer":"لأن المقام مقام إنذار المعاندين، ودفع المفسدة مقدّم على جلب المصلحة؛ فكان الإنذار هو الغرض الأهم في السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص418–419.","url":""}]},{"id":"s18-7","number":7,"surah":18,"verses":[2],"verseLabel":"الكهف: 2","question":"ما سرّ التعبير بـ﴿أَجْرًا حَسَنًا﴾ دون التصريح بـ«الجنة»؟","answer":"وصف الأجر بالحسن يجمع ما فيه من البهجة والنفع والخلو من القبح، والمراد به نعيم الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص428.","url":""}]},{"id":"s18-8","number":8,"surah":18,"verses":[3],"verseLabel":"الكهف: 3","question":"ما سرّ التعبير بـ﴿مَاكِثِينَ فِيهِ أَبَدًا﴾؟","answer":"تفيد ﴿ماكثين﴾ استقرارهم وإقامتهم في النعيم، وتفيد ﴿أبدًا﴾ دوام ذلك بلا انتهاء؛ فاجتمع إحاطة المكان ودوام الزمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص429–430.","url":""}]},{"id":"s18-9","number":9,"surah":18,"verses":[4],"verseLabel":"الكهف: 4","question":"لماذا خُصّ الذين قالوا ﴿اتَّخَذَ اللَّهُ وَلَدًا﴾ بإنذار بعد الإنذار العام؟","answer":"للتنبيه على فظاعة هذه المقالة وعظم استحقاقها للوعيد؛ فعُطف الخاص على العام اهتمامًا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص434–436.","url":""}]},{"id":"s18-10","number":10,"surah":18,"verses":[5],"verseLabel":"الكهف: 5","question":"ما سرّ التعبير بـ﴿كَبُرَتْ كَلِمَةً﴾ دون «عظمت»؟","answer":"اختير ﴿كبرت﴾ للدلالة على عظم الذنب وشدة قبح المقالة، وجاءت الصيغة للتعجب من شناعتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص447.","url":""}]},{"id":"s18-11","number":11,"surah":18,"verses":[5],"verseLabel":"الكهف: 5","question":"ما سرّ التعبير بـ﴿تَخْرُجُ مِنْ أَفْوَاهِهِمْ﴾؟","answer":"للدلالة على أنها مقولة لا مصدر لها إلا التلفظ بالأفواه، ولا تقوم على علم أو حقيقة يعقلها العقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص449.","url":""}]},{"id":"s18-12","number":12,"surah":18,"verses":[5],"verseLabel":"الكهف: 5","question":"لماذا حُصر قولهم في الكذب بـ﴿إِنْ يَقُولُونَ إِلَّا كَذِبًا﴾؟","answer":"لنفي كل وصف عن مقالتهم إلا الكذب، مع تأكيد النفي بأسلوب النفي والاستثناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص450.","url":""}]},{"id":"s18-13","number":13,"surah":18,"verses":[6],"verseLabel":"الكهف: 6","question":"ما سرّ التعبير بـ﴿فَلَعَلَّكَ بَاخِعٌ نَفْسَكَ﴾؟","answer":"البخع بلوغ الحزن بالنفس إلى الهلاك؛ والتعبير يصور شدة حرص النبي ﷺ على إيمانهم، وفيه تسلية ونهي عن استهلاك النفس حزنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص457.","url":""}]},{"id":"s18-14","number":14,"surah":18,"verses":[6],"verseLabel":"الكهف: 6","question":"ما سرّ إطلاق ﴿هَذَا الْحَدِيثِ﴾ على القرآن؟","answer":"الحديث هو الخبر والكلام المتلو، والإشارة بـ﴿هذا﴾ تستحضر القرآن الحاضر الذي يسمعونه ويعرضون عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص459.","url":""}]},{"id":"s18-15","number":15,"surah":18,"verses":[7],"verseLabel":"الكهف: 7","question":"ما سرّ التعبير بـ﴿زِينَةً لَهَا﴾ دون «زينة لكم»؟","answer":"جُعل ما على الأرض زينةً للأرض نفسها، فيجمع التعبير الامتنان بجمال المخلوقات والتنبيه إلى أنها موضع ابتلاء زائل، لا ملك ثابت للإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص464–467.","url":""}]},{"id":"s18-16","number":16,"surah":18,"verses":[8],"verseLabel":"الكهف: 8","question":"ما سرّ التعبير بـ﴿صَعِيدًا جُرُزًا﴾؟","answer":"يصوّر انقلاب زينة الأرض إلى أرض مستوية جافة أجرد لا نبات فيها؛ فتكتمل صورة فناء الحياة وزينتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص475.","url":""}]},{"id":"s18-17","number":17,"surah":18,"verses":[9],"verseLabel":"الكهف: 9","question":"ما سرّ التعبير بـ﴿أَمْ حَسِبْتَ﴾ دون «أفظننت»؟","answer":"لأن الحسبان هنا أدنى درجة من الظن وليس اعتقادًا راجحًا؛ فناسب إنكار أدنى توهم أن أصحاب الكهف غاية العجب، كما أن لفظ الحسبان يلائم ما في القصة من حساب مدة لبثهم وعددهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص483.","url":""}]},{"id":"s18-18","number":18,"surah":18,"verses":[9],"verseLabel":"الكهف: 9","question":"ما سرّ تقديم ﴿مِنْ آيَاتِنَا﴾ على ﴿عَجَبًا﴾؟","answer":"لأن الأهم نفي أن تكون قصتهم بالقياس إلى آيات الله هي العجب البالغ؛ فقُدّم تعلقها بآيات الله قبل وصفها بالعجب، وفي ذلك ردّ تهويل السائلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص485.","url":""}]},{"id":"s18-19","number":19,"surah":18,"verses":[9],"verseLabel":"الكهف: 9","question":"لماذا جمع التعبير بين ﴿الْكَهْفِ وَالرَّقِيمِ﴾؟","answer":"عُرّف أصحاب القصة بما اقترنت به شهرتهم: الكهف الذي لزموه، والرقيم الذي اختلف المفسرون فيه؛ فقيل هو لوح كُتب فيه خبرهم، وقيل اسم موضع. فلا يجزم بأنه «الأثر المكتوب» وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص483–484.","url":""}]},{"id":"s18-20","number":20,"surah":18,"verses":[10],"verseLabel":"الكهف: 10","question":"لماذا أُظهر لفظ ﴿الْفِتْيَةُ﴾ بدل الإضمار؟","answer":"للتنبيه على حداثة سنهم وقوة إيمانهم مع الشباب، وفي إظهار الاسم عناية بموضع العبرة في حالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص490–491.","url":""}]},{"id":"s18-21","number":21,"surah":18,"verses":[10],"verseLabel":"الكهف: 10","question":"لماذا حُذف حرف النداء في ﴿رَبَّنَا آتِنَا﴾؟","answer":"لإظهار شدة قربهم من ربهم وقوة لجوئهم إليه، فكأنهم شرعوا في الدعاء فور استقرارهم بلا مهلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص492.","url":""}]},{"id":"s18-22","number":22,"surah":18,"verses":[10],"verseLabel":"الكهف: 10","question":"ما سرّ التعبير بـ﴿مِنْ لَدُنْكَ رَحْمَةً﴾؟","answer":"طلبوا رحمة خاصة صادرة من عند الله؛ و«لدن» أخص من «عند» في الدلالة على الصدور والقرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص494.","url":""}]},{"id":"s18-23","number":23,"surah":18,"verses":[10],"verseLabel":"الكهف: 10","question":"ما سرّ تقديم ﴿لَنَا﴾ في ﴿وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا﴾؟","answer":"للاهتمام بحاجتهم إلى المطلوب وإبراز أنه المرغوب لهم قبل بيان الأمر الذي يطلبون تهيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص496.","url":""}]},{"id":"s18-24","number":24,"surah":18,"verses":[11],"verseLabel":"الكهف: 11","question":"ما سرّ التعبير بـ﴿فَضَرَبْنَا عَلَى آذَانِهِمْ﴾ بدل «أنمناهم»؟","answer":"هو كناية عن إلقاء نوم ثقيل حُجب معه السمع؛ وخصت الآذان لأن السمع هو الطريق المعتاد لتنبه النائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص500–503.","url":""}]},{"id":"s18-25","number":25,"surah":18,"verses":[11],"verseLabel":"الكهف: 11","question":"ما سرّ التعبير بـ﴿سِنِينَ عَدَدًا﴾؟","answer":"جاء ﴿عددًا﴾ وصفًا للسنين للدلالة على كثرتها، مع إبقاء مقدارها مجملًا في هذا الموضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص500، 504.","url":""}]},{"id":"s18-26","number":26,"surah":18,"verses":[12],"verseLabel":"الكهف: 12","question":"ما سرّ التعبير بـ﴿ثُمَّ بَعَثْنَاهُمْ﴾؟","answer":"استُعمل البعث في إيقاظهم بعد سكون النوم الطويل؛ فهو تحريك وإقامة من حال الرقاد، وأسند إلى ضمير العظمة لعجيب القدرة الظاهرة فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص505–508.","url":""}]},{"id":"s18-27","number":27,"surah":18,"verses":[12],"verseLabel":"الكهف: 12","question":"ما سرّ التعبير بـ﴿أَيُّ الْحِزْبَيْنِ أَحْصَى﴾؟","answer":"ليس المراد حدوث علم لله بعد جهل، بل ظهور اختلاف المقدّرين، وبيان أي الفريقين أتقن إحصاءً وأصاب الواقع.","sources":[{"label":"التحرير والتنوير، ج15، ص268–269، تفسير الكهف 12.","url":""}]},{"id":"s18-28","number":28,"surah":18,"verses":[13],"verseLabel":"الكهف: 13","question":"ما سرّ التعبير بـ﴿نَحْنُ نَقُصُّ عَلَيْكَ نَبَأَهُمْ بِالْحَقِّ﴾؟","answer":"لقصر القصص الحق على خبر الله ونفي التخمينات؛ فالمقصود بيان الصدق ومواضع العبرة من القصة.","sources":[{"label":"التحرير والتنوير، ج15، ص269–270، تفسير الكهف 13.","url":""}]},{"id":"s18-29","number":29,"surah":18,"verses":[13],"verseLabel":"الكهف: 13","question":"ما سرّ التعبير بـ﴿إِنَّهُمْ فِتْيَةٌ آمَنُوا﴾؟","answer":"افتتحت الجملة بـ﴿إن﴾ للاهتمام بخبرهم، ووصفوا بالفتية تعريفًا بحالهم، ثم ذُكرت زيادة هداهم بما وهبهم الله من التوفيق والثبات.","sources":[{"label":"التحرير والتنوير، ج15، ص270–271، تفسير الكهف 13.","url":""}]},{"id":"s18-30","number":30,"surah":18,"verses":[14],"verseLabel":"الكهف: 14","question":"ما سرّ التعبير بـ﴿وَرَبَطْنَا عَلَى قُلُوبِهِمْ﴾؟","answer":"الربط استعارة لتثبيت إيمانهم وإزالة التردد والاضطراب عن قلوبهم.","sources":[{"label":"التحرير والتنوير، ج15، ص271، تفسير الكهف 14.","url":""}]},{"id":"s18-31","number":31,"surah":18,"verses":[14],"verseLabel":"الكهف: 14","question":"ما دلالة قولهم ﴿رَبُّنَا رَبُّ السَّمَاوَاتِ وَالْأَرْضِ﴾؟","answer":"أثبتوا أن ربهم هو رب السماوات والأرض، فجاء الوصف كاشفًا لعموم ربوبيته، وبُني عليه امتناعهم من دعاء غيره إلهًا.","sources":[{"label":"التحرير والتنوير، ج15، ص272، تفسير الكهف 14.","url":""}]},{"id":"s18-32","number":32,"surah":18,"verses":[15],"verseLabel":"الكهف: 15","question":"ما سرّ وصف الشرك بأنه ﴿شَطَطًا﴾؟","answer":"الشطط الإفراط في مخالفة الحق والصواب، واستعير من البعد؛ فدعاء غير الله قول بالغ البعد عن الحق.","sources":[{"label":"التحرير والتنوير، ج15، ص273، تفسير الكهف 14.","url":""}]},{"id":"s18-33","number":33,"surah":18,"verses":[15],"verseLabel":"الكهف: 15","question":"لماذا طالبوا قومهم بـ﴿سُلْطَانٍ بَيِّنٍ﴾ على الشرك؟","answer":"للتبكيت وإظهار أن اتخاذ الآلهة قام بلا حجة؛ فالسلطان هو البرهان، والبين واضح الدلالة.","sources":[{"label":"التحرير والتنوير، ج15، ص273–274، تفسير الكهف 15.","url":""}]},{"id":"s18-34","number":34,"surah":18,"verses":[16],"verseLabel":"الكهف: 16","question":"ما سرّ التعبير بقوله تعالى: بعضهم لبعض ﴿فَأْوُوا إِلَى الْكَهْفِ﴾ بعد اعتزال القوم؟","answer":"كان ذلك نصحًا ومشورة بعد اليأس من رجوع قومهم، فانتقلوا من إعلان المفاصلة إلى اتخاذ الكهف مأوى يحفظ دينهم.","sources":[{"label":"التحرير والتنوير، ج15، ص275، تفسير الكهف 16.","url":""}]},{"id":"s18-35","number":35,"surah":18,"verses":[16],"verseLabel":"الكهف: 16","question":"ما سرّ التعبير بـ﴿يَنْشُرْ لَكُمْ رَبُّكُمْ مِنْ رَحْمَتِهِ﴾؟","answer":"صوّر حصول الرحمة لهم بالنشر والبسط، ووعدهم بأن يجعل الله لهم في ضيق الكهف سعةً من لطفه ومرفقًا.","sources":[{"label":"التحرير والتنوير، ج15، ص275–276، تفسير الكهف 16.","url":""}]},{"id":"s18-36","number":36,"surah":18,"verses":[17],"verseLabel":"الكهف: 17","question":"لماذا فُصّل ميل الشمس عن الكهف؟","answer":"لبيان الوضع الدقيق الذي جعل أشعتها لا تخترق الكهف، فظل داخله معتدلًا وسُلّمت أجسادهم من البِلى.","sources":[{"label":"التحرير والتنوير، ج15، ص277–278، تفسير الكهف 17.","url":""}]},{"id":"s18-37","number":37,"surah":18,"verses":[17],"verseLabel":"الكهف: 17","question":"ما سرّ التعبير بـ﴿ذَلِكَ مِنْ آيَاتِ اللَّهِ﴾؟","answer":"الإشارة إلى حال الشمس والكهف، وهي دليل على قدرة الله وعنايته بأوليائه، وجاءت الإشارة للتعظيم.","sources":[{"label":"التحرير والتنوير، ج15، ص278، تفسير الكهف 17.","url":""}]},{"id":"s18-38","number":38,"surah":18,"verses":[18],"verseLabel":"الكهف: 18","question":"ما سرّ التعبير بـ﴿وَتَحْسَبُهُمْ أَيْقَاظًا وَهُمْ رُقُودٌ﴾؟","answer":"لأن هيئتهم كانت تشبه حال اليقظة مع ثبوت رقادهم، فجاء التعبير تعجيبًا من حالهم وبيانًا لعظيم قدرة الله في شأنهم.","sources":[{"label":"التحرير والتنوير، ج15، ص279–280، تفسير الكهف 18.","url":""}]},{"id":"s18-39","number":39,"surah":18,"verses":[18],"verseLabel":"الكهف: 18","question":"لماذا قُلّبوا ﴿ذَاتَ الْيَمِينِ وَذَاتَ الشِّمَالِ﴾؟","answer":"أجرى الله عليهم هيئة الأحياء بتغيّر أوضاعهم، فكان التقليب كرامة وعناية. وذكر ابن عاشور احتمال أثره في سلامة أجسادهم، ثم نبّه إلى أن بقاء الكلب دون تقليب يمنع الجزم بأنه سبب الحفظ.","sources":[{"label":"التحرير والتنوير، ج15، ص280، تفسير الكهف 18.","url":""}]},{"id":"s18-40","number":40,"surah":18,"verses":[18],"verseLabel":"الكهف: 18","question":"ما دلالة كون كلبهم ﴿بَاسِطًا ذِرَاعَيْهِ بِالْوَصِيدِ﴾؟","answer":"يدل على بقائه عند مدخل الكهف في هيئة جلسة الكلب، من غير تقليب كالفتية؛ والوصيد مدخل الكهف المشبه بالباب.","sources":[{"label":"التحرير والتنوير، ج15، ص280، تفسير الكهف 18.","url":""}]},{"id":"s18-41","number":41,"surah":18,"verses":[18],"verseLabel":"الكهف: 18","question":"لماذا يمتلئ من يطلع عليهم رعبًا؟","answer":"لأن من يراهم مجتمعين في كهف من غير علم بقصتهم قد يحسبهم لصوصًا وقطاع طريق، فيملكه الخوف منهم؛ وليس الرعب ناشئًا من مخالفة خلقتهم لخلق الناس.","sources":[{"label":"التحرير والتنوير، ج15، ص281–282، تفسير الكهف 18.","url":""}]},{"id":"s18-42","number":42,"surah":18,"verses":[19],"verseLabel":"الكهف: 19","question":"ما سرّ التعبير بـ﴿وَكَذَلِكَ بَعَثْنَاهُمْ﴾؟","answer":"أي كما أنمناهم تلك القرون بعثناهم؛ فالإفاقة آية على عظيم قدرة الله مثل آية إنامتهم.","sources":[{"label":"التحرير والتنوير، ج15، ص282–283، تفسير الكهف 19.","url":""}]},{"id":"s18-43","number":43,"surah":18,"verses":[19],"verseLabel":"الكهف: 19","question":"لماذا سألوا ﴿كَمْ لَبِثْتُمْ﴾ بعد استيقاظهم؟","answer":"ليتحاوروا في تقدير مدة لبثهم ويتطلب كل منهم رأي الآخر؛ فلما لم يبلغوا اليقين فوضوا العلم إلى الله.","sources":[{"label":"التحرير والتنوير، ج15، ص283، تفسير الكهف 19.","url":""}]},{"id":"s18-44","number":44,"surah":18,"verses":[19],"verseLabel":"الكهف: 19","question":"ما سرّ قولهم ﴿رَبُّكُمْ أَعْلَمُ بِمَا لَبِثْتُمْ﴾؟","answer":"لما اختلفوا عدلوا عن القول بالظن إلى تفويض العلم لله، وذلك من كمال إيمانهم.","sources":[{"label":"التحرير والتنوير، ج15، ص283–284، تفسير الكهف 19.","url":""}]},{"id":"s18-45","number":45,"surah":18,"verses":[19],"verseLabel":"الكهف: 19","question":"ما سرّ التعبير بـ﴿أَيُّهَا أَزْكَى طَعَامًا﴾؟","answer":"طلبوا اختيار المكان الذي طعامه أطيب وأحسن؛ فالزكو هنا زيادة في الخير والنفع.","sources":[{"label":"التحرير والتنوير، ج15، ص284، تفسير الكهف 19.","url":""}]},{"id":"s18-46","number":46,"surah":18,"verses":[20],"verseLabel":"الكهف: 20","question":"ما دلالة الجمع بين ﴿يَرْجُمُوكُمْ﴾ و﴿يُعِيدُوكُمْ فِي مِلَّتِهِمْ﴾؟","answer":"حصروا الخطر في أحد أمرين: القتل رجمًا أو الإكراه على الرجوع إلى دين القوم، والثاني يترتب عليه انتفاء الفلاح أبدًا.","sources":[{"label":"التحرير والتنوير، ج15، ص285–286، تفسير الكهف 20.","url":""}]},{"id":"s18-47","number":47,"surah":18,"verses":[21],"verseLabel":"الكهف: 21","question":"ما سرّ التعبير بـ﴿وَكَذَلِكَ أَعْثَرْنَا عَلَيْهِمْ﴾؟","answer":"كما كان في إنامتهم وبعثهم إظهار للقدرة، أطلع الله أهل المدينة عليهم ليظهر لهم صدق البعث في وقت تنازعهم فيه.","sources":[{"label":"التحرير والتنوير، ج15، ص286–287، تفسير الكهف 21.","url":""}]},{"id":"s18-48","number":48,"surah":18,"verses":[21],"verseLabel":"الكهف: 21","question":"ما دلالة قوله ﴿لِيَعْلَمُوا أَنَّ وَعْدَ اللَّهِ حَقٌّ﴾؟","answer":"جعل العثور عليهم برهانًا مشاهدًا على إحياء الموتى والبعث، فازداد علم القوم بكيفية ما كانوا يؤمنون به.","sources":[{"label":"التحرير والتنوير، ج15، ص286–287، تفسير الكهف 21.","url":""}]},{"id":"s18-49","number":49,"surah":18,"verses":[22],"verseLabel":"الكهف: 22","question":"ما سرّ التعبير بـ﴿رَجْمًا بِالْغَيْبِ﴾؟","answer":"استعير الرجم لرمي الكلام من غير روية ولا تثبت، كما يُرمى الحجر نحو ما لا يُعلم.","sources":[{"label":"التحرير والتنوير، ج15، ص289–290، تفسير الكهف 22.","url":""}]},{"id":"s18-50","number":50,"surah":18,"verses":[22],"verseLabel":"الكهف: 22","question":"لماذا لم يُعلِم القرآن عموم الناس بعدد أصحاب الكهف؟","answer":"ليعوّد الأمة ترك الاشتغال بما لا فائدة فيه للدين أو للناس، مع تقرير أن قليلًا ممن أطلعهم الله يعلمون عدتهم.","sources":[{"label":"التحرير والتنوير، ج15، ص289–290، تفسير الكهف 22.","url":""}]},{"id":"s18-51","number":51,"surah":18,"verses":[22],"verseLabel":"الكهف: 22","question":"ما سرّ التعبير بـ﴿فَلَا تُمَارِ فِيهِمْ إِلَّا مِرَاءً ظَاهِرًا﴾؟","answer":"المراء الظاهر هو ما كانت حجته واضحة ولا يطول الخوض فيه؛ وما وراء ذلك قليل الجدوى محتاج إلى دليل فلا ينبغي الاشتغال به.","sources":[{"label":"التحرير والتنوير، ج15، ص293–294، تفسير الكهف 22.","url":""}]},{"id":"s18-52","number":52,"surah":18,"verses":[23,24],"verseLabel":"الكهف: 23-24","question":"لماذا نُهي عن قول ﴿إِنِّي فَاعِلٌ ذَلِكَ غَدًا﴾ دون ﴿إِلَّا أَنْ يَشَاءَ اللَّهُ﴾؟","answer":"لئلا يُجزم بفعل مستقبل دون تقييده بمشيئة الله وإذنه؛ فجاء النهي تعليمًا لأدب الوعد والإخبار عن العزم.","sources":[{"label":"التحرير والتنوير، ج15، ص294–297، تفسير الكهف 23–24.","url":""}]},{"id":"s18-53","number":53,"surah":18,"verses":[24],"verseLabel":"الكهف: 24","question":"ما دلالة قوله ﴿وَاذْكُرْ رَبَّكَ إِذَا نَسِيتَ﴾؟","answer":"على أشهر توجيه في السياق: إذا نسي المتكلم ذكر المشيئة ثم تذكر، فليذكر ربه؛ مع تنبيه ابن عاشور إلى الخلاف في اتصال الاستثناء وتأخيره.","sources":[{"label":"التحرير والتنوير، ج15، ص297–298، تفسير الكهف 24.","url":""}]},{"id":"s18-54","number":54,"surah":18,"verses":[24],"verseLabel":"الكهف: 24","question":"ما دلالة قوله ﴿عَسَى أَنْ يَهْدِيَنِ رَبِّي لِأَقْرَبَ مِنْ هَذَا رَشَدًا﴾؟","answer":"أُمر النبي ﷺ أن يرجو هداية الله إلى ما هو أقرب للرشد وأهم من مجاراة المتعنتين في سؤال القصص، وهو بيان الشريعة والهداية المقصودة من الرسالة.","sources":[{"label":"التحرير والتنوير، ج15، ص298–299، تفسير الكهف 24.","url":""}]},{"id":"s18-55","number":55,"surah":18,"verses":[25],"verseLabel":"الكهف: 25","question":"ما سرّ التعبير بـ﴿ثَلَاثَ مِائَةٍ سِنِينَ وَازْدَادُوا تِسْعًا﴾؟","answer":"عبّر عن المدة بثلاثمائة وزيادة تسع للإشارة إلى موافقة ثلاثمائة سنة شمسية لثلاثمائة وتسع سنين قمرية، وهو ما بيّن به ابن عاشور نكتة لفظ الازدياد.","sources":[{"label":"التحرير والتنوير، ج15، ص299–300، تفسير الكهف 25.","url":""}]},{"id":"s18-56","number":56,"surah":18,"verses":[26],"verseLabel":"الكهف: 26","question":"ما دلالة قوله ﴿قُلِ اللَّهُ أَعْلَمُ بِمَا لَبِثُوا﴾ بعد ذكر المدة؟","answer":"لقطع المماراة في مدة لبثهم ورد علمها إلى الله؛ وعلى وجه حكاية قول أهل الكتاب يكون تفويضًا للعلم إليه.","sources":[{"label":"التحرير والتنوير، ج15، ص300، تفسير الكهف 26.","url":""}]},{"id":"s18-57","number":57,"surah":18,"verses":[26],"verseLabel":"الكهف: 26","question":"ما سرّ التعبير بـ﴿أَبْصِرْ بِهِ وَأَسْمِعْ﴾؟","answer":"صيغتا تعجب من عموم علم الله بالمغيبات من المبصرات والمسموعات، وهو علم لا يشاركه فيه أحد.","sources":[{"label":"التحرير والتنوير، ج15، ص300، تفسير الكهف 26.","url":""}]},{"id":"s18-58","number":58,"surah":18,"verses":[27],"verseLabel":"الكهف: 27","question":"ما دلالة قوله ﴿لَا مُبَدِّلَ لِكَلِمَاتِهِ﴾ عقب الأمر بتلاوة الوحي؟","answer":"تقرير وجوب تلاوة الوحي كله كما أُنزل؛ فلا يملك أحد تبديل كلماته، ولا يسوغ إخفاء شيء منه بحذف أو زيادة استجابة لضغط المشركين.","sources":[{"label":"التحرير والتنوير، ج15، ص302، تفسير الكهف 27.","url":""}]},{"id":"s18-59","number":59,"surah":18,"verses":[28],"verseLabel":"الكهف: 28","question":"ما سرّ التعبير بـ﴿وَاصْبِرْ نَفْسَكَ﴾؟","answer":"أي احبس نفسك وثبّتها مع الذين يدعون ربهم، ولا تفارقهم استجابة لرغبة أهل الكبر؛ فعدّي الصبر إلى النفس لإفادة حبسها على هذه الملازمة.","sources":[{"label":"التحرير والتنوير، ج15، ص303، تفسير الكهف 28.","url":""}]},{"id":"s18-60","number":60,"surah":18,"verses":[28],"verseLabel":"الكهف: 28","question":"ما سرّ التعبير بـ﴿يُرِيدُونَ وَجْهَهُ﴾؟","answer":"وجه الله استعارة لإقباله على عبده ورضاه عنه؛ أي يدعونه طالبين رضاه وإقباله، لا يريدون عرض الدنيا.","sources":[{"label":"التحرير والتنوير، ج15، ص304، تفسير الكهف 28.","url":""}]},{"id":"s18-61","number":61,"surah":18,"verses":[28],"verseLabel":"الكهف: 28","question":"ما سرّ التعبير بـ﴿وَلَا تَعْدُ عَيْنَاكَ عَنْهُمْ﴾؟","answer":"نُسب التجاوز إلى العينين كناية عن ترك مجالستهم؛ أي لا تصرف نظرك عنهم إلى أهل الدنيا طلبًا لزينتها.","sources":[{"label":"التحرير والتنوير، ج15، ص304–305، تفسير الكهف 28.","url":""}]},{"id":"s18-62","number":62,"surah":18,"verses":[28],"verseLabel":"الكهف: 28","question":"ما سرّ وصف أمر الغافل بأنه ﴿فُرُطًا﴾؟","answer":"الفُرُط هو الظلم والاعتداء، من الفروط بمعنى السبق؛ وزيادة فعل الكون تدل على تمكن الإفراط والاعتداء على الحق من شأنه وحاله.","sources":[{"label":"التحرير والتنوير، ج15، ص305–306، تفسير الكهف 28.","url":""}]},{"id":"s18-63","number":63,"surah":18,"verses":[29],"verseLabel":"الكهف: 29","question":"ما دلالة قوله ﴿فَمَنْ شَاءَ فَلْيُؤْمِنْ وَمَنْ شَاءَ فَلْيَكْفُرْ﴾؟","answer":"ليس إذنًا بالكفر، بل الأمر للتسوية المكنى بها عن الوعد والوعيد، وقد كشف ما بعدها وخامة عاقبة من يستمر على الكفر.","sources":[{"label":"التحرير والتنوير، ج15، ص306–307، تفسير الكهف 29.","url":""}]},{"id":"s18-64","number":64,"surah":18,"verses":[29],"verseLabel":"الكهف: 29","question":"ما دلالة إحاطة سرادق النار بالظالمين؟","answer":"صُورت النار دارًا يحيط بها سرادق، مبالغة في إحاطة دار العذاب بهم؛ وفي استعارة شعار بيوت المترفين للنار تهكم بهم.","sources":[{"label":"التحرير والتنوير، ج15، ص307، تفسير الكهف 29.","url":""}]},{"id":"s18-65","number":65,"surah":18,"verses":[29],"verseLabel":"الكهف: 29","question":"ما سرّ تشبيه ماء أهل النار بـ﴿الْمُهْلِ﴾؟","answer":"أشبه معاني المهل هنا دُرديّ الزيت؛ والتشبيه في سواد اللون وشدة الحرارة، فلا يزيد المستغيث إلا التهابًا وحرارة.","sources":[{"label":"التحرير والتنوير، ج15، ص307–308، تفسير الكهف 29.","url":""}]},{"id":"s18-66","number":66,"surah":18,"verses":[30],"verseLabel":"الكهف: 30","question":"ما دلالة قوله ﴿إِنَّا لَا نُضِيعُ أَجْرَ مَنْ أَحْسَنَ عَمَلًا﴾؟","answer":"طمأنة للمؤمنين بأن عملهم مرعي عند ربهم، وصيغ الحكم عامًا ليشملهم وكل من يماثلهم في إحسان العمل، مع مزيد توكيد لتحقيق الجزاء لأربابه.","sources":[{"label":"التحرير والتنوير، ج15، ص309–310، تفسير الكهف 30.","url":""}]},{"id":"s18-67","number":67,"surah":18,"verses":[31],"verseLabel":"الكهف: 31","question":"ما سرّ التعبير بـ﴿تَجْرِي مِنْ تَحْتِهِمُ الْأَنْهَارُ﴾ بدل «من تحتها»؟","answer":"أضيف ﴿تحت﴾ إلى ضمير أهل الجنة زيادة في تقرير ملكهم للجنات واستحقاقهم للبشارة؛ فاجتمعت مؤكدات الخبر لإتمام بشارتهم والتعريض بإغاظة المشركين.","sources":[{"label":"التحرير والتنوير، ج15، ص310–311، تفسير الكهف 31.","url":""}]},{"id":"s18-68","number":68,"surah":18,"verses":[32],"verseLabel":"الكهف: 32","question":"لماذا ضُرب مثل الرجلين بعد ذكر فريقي الإيمان والكفر؟","answer":"لتمثيل حال الفريقين بقصة تظهر عاقبة غرور الكافر وخسارته، وعاقبة المؤمن المتواضع العارف بسنن الله؛ فتجعل المعنى العقدي في صورة محسوسة أوقع في العبرة.","sources":[{"label":"التحرير والتنوير، ج15، ص314–316، تفسير الكهف 32.","url":""}]},{"id":"s18-69","number":69,"surah":18,"verses":[32],"verseLabel":"الكهف: 32","question":"ما دلالة إحاطة الجنتين بالنخل وجعل الزرع بينهما؟","answer":"من محاسن الجنات إحاطتها بالأشجار المثمرة، وكان الزرع فاصلًا بين الجنتين وهما تكتنفانه، فصار المجموع ضيعة واحدة محكمة التكوين.","sources":[{"label":"التحرير والتنوير، ج15، ص316، تفسير الكهف 32.","url":""}]},{"id":"s18-70","number":70,"surah":18,"verses":[33],"verseLabel":"الكهف: 33","question":"ما سرّ التعبير بـ﴿وَلَمْ تَظْلِمْ مِنْهُ شَيْئًا﴾ في وصف الجنتين؟","answer":"استعير الظلم للنقص: فقد أوفت كل جنة بما يُترقب من مقدار الثمر في حال الخصب، فكأن نقصان الغلة حرمان لصاحب حق.","sources":[{"label":"التحرير والتنوير، ج15، ص317–318، تفسير الكهف 33.","url":""}]},{"id":"s18-71","number":71,"surah":18,"verses":[34],"verseLabel":"الكهف: 34","question":"ما سرّ التعبير بـ﴿وَكَانَ لَهُ ثَمَرٌ﴾ بعد ذكر الجنتين؟","answer":"الثُّمُر هنا المال الكثير المتنوع من النقد والأنعام والجنات والمزارع؛ أي كان له مال غير الجنتين أيضًا، فليس المراد مجرد محصولهما.","sources":[{"label":"التحرير والتنوير، ج15، ص318، تفسير الكهف 34.","url":""}]},{"id":"s18-72","number":72,"surah":18,"verses":[34],"verseLabel":"الكهف: 34","question":"ما دلالة قوله ﴿وَهُوَ يُحَاوِرُهُ﴾؟","answer":"المحاورة مراجعة الكلام بين متكلمين؛ ودلت هنا على أن صاحبه وعظه في الإيمان والعمل الصالح، فرد صاحب الجنتين بالفخر والتطاول بدل المجادلة بالحسنى.","sources":[{"label":"التحرير والتنوير، ج15، ص318–319، تفسير الكهف 34.","url":""}]},{"id":"s18-73","number":73,"surah":18,"verses":[35],"verseLabel":"الكهف: 35","question":"ما دلالة قوله ﴿وَهُوَ ظَالِمٌ لِنَفْسِهِ﴾ عند دخوله جنته؟","answer":"يكشف الوصف حقيقة حاله وهو داخل في زهو نعمته: كان مشركًا مكذبًا بالبعث بطرًا بنعمة الله عليه.","sources":[{"label":"التحرير والتنوير، ج15، ص319، تفسير الكهف 35.","url":""}]},{"id":"s18-74","number":74,"surah":18,"verses":[35],"verseLabel":"الكهف: 35","question":"ما سرّ التعبير بـ﴿مَا أَظُنُّ أَنْ تَبِيدَ هَذِهِ أَبَدًا﴾؟","answer":"أشار بـ﴿هذه﴾ إلى الجنة الحاضرة التي دخلاها، ونفى اعتقاده زوالها؛ والمراد بالأبد طول المدة وبقاؤها بقاء أمثالها، اغترارًا بقوة أسباب نمائها ودوامها.","sources":[{"label":"التحرير والتنوير، ج15، ص319–320، تفسير الكهف 35.","url":""}]},{"id":"s18-75","number":75,"surah":18,"verses":[36],"verseLabel":"الكهف: 36","question":"ما دلالة قوله ﴿وَلَئِنْ رُدِدْتُ إِلَى رَبِّي﴾؟","answer":"قاله تهكمًا بصاحبه المؤمن بعد أن نفى قيام الساعة؛ ثم بالغ في التهكم بلام القسم ونون التوكيد مدعيًا أنه ـ على فرض الرد ـ سيجد خيرًا من جنتيه.","sources":[{"label":"التحرير والتنوير، ج15، ص320، تفسير الكهف 36.","url":""}]},{"id":"s18-76","number":76,"surah":18,"verses":[37],"verseLabel":"الكهف: 37","question":"لماذا ذكّره صاحبه بالتراب ثم النطفة؟","answer":"يرده من وهم الاستغناء إلى مراحل عجزه الأولى؛ من خلقه منهما قادر على بعثه وسلب نعمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص14, تفسير الكهف 37.","url":""}]},{"id":"s18-77","number":77,"surah":18,"verses":[37],"verseLabel":"الكهف: 37","question":"ما سرّ التعبير بـ﴿ثُمَّ سَوَّاكَ رَجُلًا﴾؟","answer":"التسوية تصور نقل القدرة للنطفة إلى إنسان كامل، و«رجلًا» تذكره أن قوته نفسها عطية.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص18, تفسير الكهف 37.","url":""}]},{"id":"s18-78","number":78,"surah":18,"verses":[38],"verseLabel":"الكهف: 38","question":"ما سرّ التعبير بـالمؤمن ﴿لَكِنَّا هُوَ اللَّهُ رَبِّي﴾؟","answer":"استدرك على كفر صاحبه بإعلان التوحيد، وحذف بعض الحروف في الأصل من اندماج «لكن أنا».","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص20, تفسير الكهف 38.","url":""}]},{"id":"s18-79","number":79,"surah":18,"verses":[38],"verseLabel":"الكهف: 38","question":"ما سرّ التعبير بـ﴿وَلَا أُشْرِكُ بِرَبِّي أَحَدًا﴾ لا «واحدًا»؟","answer":"«أحدًا» في سياق النفي أعم؛ تنفي أي شريك على أي صورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص22, تفسير الكهف 38.","url":""}]},{"id":"s18-80","number":80,"surah":18,"verses":[39],"verseLabel":"الكهف: 39","question":"لماذا أرشده إلى قول ﴿مَا شَاءَ اللَّهُ لَا قُوَّةَ إِلَّا بِاللَّهِ﴾؟","answer":"الأولى ترد وجود النعمة إلى مشيئة الله، والثانية ترد بقاءها والقدرة عليها إلى معونته.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص25, تفسير الكهف 39.","url":""}]},{"id":"s18-81","number":81,"surah":18,"verses":[39],"verseLabel":"الكهف: 39","question":"ما سرّ التعبير بـ﴿إِنْ تَرَنِ أَنَا أَقَلَّ مِنْكَ﴾؟","answer":"واجه تفاخره بهدوء: القلة المرئية الآن لا تحكم بالعاقبة التي بيد الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص30, تفسير الكهف 39.","url":""}]},{"id":"s18-82","number":82,"surah":18,"verses":[40],"verseLabel":"الكهف: 40","question":"ما سرّ التعبير بـ﴿حُسْبَانًا مِنَ السَّمَاءِ﴾؟","answer":"الحسبان عذاب مقدر كالصواعق أو المطر المهلك، يأتي من الجهة التي ينتظر منها الغيث.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص36, تفسير الكهف 40.","url":""}]},{"id":"s18-83","number":83,"surah":18,"verses":[40],"verseLabel":"الكهف: 40","question":"لماذا تصير الأرض ﴿صَعِيدًا زَلَقًا﴾؟","answer":"بعد خضرتها تصبح أرضًا ملساء لا يثبت عليها قدم ولا ينبت فيها زرع؛ انقلاب كامل للمشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص39, تفسير الكهف 40.","url":""}]},{"id":"s18-84","number":84,"surah":18,"verses":[41],"verseLabel":"الكهف: 41","question":"ما سرّ التعبير بـ﴿غَوْرًا فَلَنْ تَسْتَطِيعَ لَهُ طَلَبًا﴾؟","answer":"إذا غاص الماء في باطن الأرض عجزت الثروة كلها عن رده، فينكشف اعتمادها على نعمة خفية.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص41, تفسير الكهف 41.","url":""}]},{"id":"s18-85","number":85,"surah":18,"verses":[42],"verseLabel":"الكهف: 42","question":"ما سرّ التعبير بـ﴿وَأُحِيطَ بِثَمَرِهِ﴾ بالبناء للمجهول؟","answer":"لتهويل الإحاطة الشاملة من غير حاجة لتسمية الآفة، فالمهم أنه لم يفلت شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص44, تفسير الكهف 42.","url":""}]},{"id":"s18-86","number":86,"surah":18,"verses":[42],"verseLabel":"الكهف: 42","question":"ما سرّ التعبير بـ﴿بِثَمَرِهِ﴾ لا «بزرعه» أو «جنتيه»؟","answer":"الثمر يشمل حصيلة ملكه كلها التي كان موضع افتخاره.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص45, تفسير الكهف 42.","url":""}]},{"id":"s18-87","number":87,"surah":18,"verses":[42],"verseLabel":"الكهف: 42","question":"ما سرّ التعبير بـ﴿يُقَلِّبُ كَفَّيْهِ﴾؟","answer":"صورة حسية للندم والحيرة بعد أن صارت اليد التي امتلكت المال خالية لا تملك دفعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص46, تفسير الكهف 42.","url":""}]},{"id":"s18-88","number":88,"surah":18,"verses":[42],"verseLabel":"الكهف: 42","question":"ما سرّ التعبير بـ﴿خَاوِيَةٌ عَلَى عُرُوشِهَا﴾؟","answer":"العروش سقطت ثم انهارت الجدران فوقها؛ فالصورة تبلغ غاية الخراب بعد تمام الزينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص50, تفسير الكهف 42.","url":""}]},{"id":"s18-89","number":89,"surah":18,"verses":[43],"verseLabel":"الكهف: 43","question":"ما سرّ التعبير بـ﴿وَلَمْ تَكُنْ لَهُ فِئَةٌ يَنْصُرُونَهُ﴾؟","answer":"نفى أصل وجود جماعة قادرة، لا مجرد وقوع النصرة؛ فالمال والأنصار تبخروا معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص52, تفسير الكهف 43.","url":""}]},{"id":"s18-90","number":90,"surah":18,"verses":[44],"verseLabel":"الكهف: 44","question":"ما سرّ تقديم ﴿هُنَالِكَ﴾ في ﴿هُنَالِكَ الْوَلَايَةُ لِلَّهِ الْحَقِّ﴾؟","answer":"يشير إلى لحظة سقوط الأسباب خاصة؛ عندها يظهر بلا غطاء أن السلطان والنصرة لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص62, تفسير الكهف 44.","url":""}]},{"id":"s18-91","number":91,"surah":18,"verses":[45],"verseLabel":"الكهف: 45","question":"لماذا شُبهت الدنيا بماء السماء والنبات؟","answer":"لأن الماء يصنع ازدهارًا سريعًا ثم يتحول النبات هشيمًا؛ دورة كاملة للجمال والزوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص67, تفسير الكهف 45.","url":""}]},{"id":"s18-92","number":92,"surah":18,"verses":[45],"verseLabel":"الكهف: 45","question":"ما سرّ التعبير بـ﴿فَأَصْبَحَ هَشِيمًا تَذْرُوهُ الرِّيَاحُ﴾؟","answer":"الفاء تسرع الانتقال من الاخضرار إلى التفتت، والرياح تفرق ما ظن ثابتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص72, تفسير الكهف 45.","url":""}]},{"id":"s18-93","number":93,"surah":18,"verses":[46],"verseLabel":"الكهف: 46","question":"لماذا سمّى المال والبنين ﴿زِينَةُ الْحَيَاةِ الدُّنْيَا﴾؟","answer":"الزينة جميلة لكنها خارجية زائلة، فلا يجوز جعلها قيمة الإنسان الباقية.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص78, تفسير الكهف 46.","url":""}]},{"id":"s18-94","number":94,"surah":18,"verses":[46],"verseLabel":"الكهف: 46","question":"لماذا كانت ﴿الْبَاقِيَاتُ الصَّالِحَاتُ﴾ خيرًا أملًا؟","answer":"لأن أثرها يبقى عند الله، فهي خير في الثواب وخير فيما يصح أن يعلّق به الرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص81, تفسير الكهف 46.","url":""}]},{"id":"s18-95","number":95,"surah":18,"verses":[47],"verseLabel":"الكهف: 47","question":"ما سرّ التعبير بـ﴿وَيَوْمَ نُسَيِّرُ الْجِبَالَ﴾؟","answer":"تحريك أثبت رموز الأرض يهدم وهم الثبات الذي قامت عليه فتنة الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص87, تفسير الكهف 47.","url":""}]},{"id":"s18-96","number":96,"surah":18,"verses":[47],"verseLabel":"الكهف: 47","question":"ما سرّ التعبير بـ﴿وَتَرَى الْأَرْضَ بَارِزَةً﴾؟","answer":"بعد زوال الجبال والستر تبدو الأرض مكشوفة لا مخبأ فيها ولا معلم يحجب أحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص90, تفسير الكهف 47.","url":""}]},{"id":"s18-97","number":97,"surah":18,"verses":[47],"verseLabel":"الكهف: 47","question":"ما سرّ التعبير بـ﴿فَلَمْ نُغَادِرْ مِنْهُمْ أَحَدًا﴾؟","answer":"نفى ترك أي فرد، ليقرر استيعاب الحشر لمن اشتهر ومن نسيه الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص94, تفسير الكهف 47.","url":""}]},{"id":"s18-98","number":98,"surah":18,"verses":[48],"verseLabel":"الكهف: 48","question":"لماذا عُرضوا على الرب ﴿صَفًّا﴾؟","answer":"يصوّر انتظامهم وتجردهم من الفوارق والزحام أمام الحكم الواحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص98, تفسير الكهف 48.","url":""}]},{"id":"s18-99","number":99,"surah":18,"verses":[48],"verseLabel":"الكهف: 48","question":"ما سرّ التعبير بقوله تعالى: لهم ﴿لَقَدْ جِئْتُمُونَا كَمَا خَلَقْنَاكُمْ أَوَّلَ مَرَّةٍ﴾؟","answer":"يبطل إنكارهم بالواقع: عادوا أفرادًا بلا مال كما بدأ خلقهم أول مرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص101, تفسير الكهف 48.","url":""}]},{"id":"s18-100","number":100,"surah":18,"verses":[49],"verseLabel":"الكهف: 49","question":"ما سرّ التعبير بـ﴿وَوُضِعَ الْكِتَابُ﴾ لا «ووضعنا الكتاب»؟","answer":"البناء للمجهول يوجه الأنظار إلى رهبة السجل الموضوع نفسه وما يكشفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص108, تفسير الكهف 49.","url":""}]},{"id":"s18-101","number":101,"surah":18,"verses":[49],"verseLabel":"الكهف: 49","question":"ما سرّ التعبير بقوله تعالى: ﴿يَا وَيْلَتَنَا﴾ بصيغة التأنيث؟","answer":"«الويلة» صيحة هلاك مخصوصة يستدعونها من شدة ما رأوا في الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص112, تفسير الكهف 49.","url":""}]},{"id":"s18-102","number":102,"surah":18,"verses":[49],"verseLabel":"الكهف: 49","question":"ما دلالة قولهم: ﴿لَا يُغَادِرُ صَغِيرَةً وَلَا كَبِيرَةً﴾؟","answer":"بدأ بالصغيرة التي يظنون تجاوزها، فإذا هي محصاة مع الكبيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص110, تفسير الكهف 49.","url":""}]},{"id":"s18-103","number":103,"surah":18,"verses":[50],"verseLabel":"الكهف: 50","question":"لماذا أعيدت قصة سجود الملائكة في سورة الكهف؟","answer":"جاءت بعد التحذير من فتنة الدنيا لتكشف أصل العداوة التي تدفع الإنسان إلى الكبر والضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص121, تفسير الكهف 50.","url":""}]},{"id":"s18-104","number":104,"surah":18,"verses":[50],"verseLabel":"الكهف: 50","question":"ما سرّ التعبير بـ﴿فَفَسَقَ عَنْ أَمْرِ رَبِّهِ﴾؟","answer":"«عن» تصور خروجه ومجاوزته دائرة الأمر، والربوبية تشنع عصيانه لمن رباه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص123, تفسير الكهف 50.","url":""}]},{"id":"s18-105","number":105,"surah":18,"verses":[50],"verseLabel":"الكهف: 50","question":"ما سرّ التعبير بـ﴿أَفَتَتَّخِذُونَهُ وَذُرِّيَّتَهُ أَوْلِيَاءَ﴾؟","answer":"الاستفهام يعجب من موالاة عدو أعلن عداوته منذ خلق أبيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص128, تفسير الكهف 50.","url":""}]},{"id":"s18-106","number":106,"surah":18,"verses":[50],"verseLabel":"الكهف: 50","question":"لماذا أظهر ﴿لِلظَّالِمِينَ﴾ في ﴿بِئْسَ لِلظَّالِمِينَ بَدَلًا﴾؟","answer":"ليحكم عليهم بالظلم ويبين أن استبدال ولاية الشيطان بولاية الله هو عين وضع الشيء في غير موضعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص130, تفسير الكهف 50.","url":""}]},{"id":"s18-107","number":107,"surah":18,"verses":[51],"verseLabel":"الكهف: 51","question":"ما سرّ التعبير بـ﴿مَا أَشْهَدْتُهُمْ خَلْقَ السَّمَاوَاتِ وَالْأَرْضِ﴾؟","answer":"من لم يشهد الخلق ولم يعن عليه لا يصلح شريكًا ولا مستشارًا للخالق.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص133, تفسير الكهف 51.","url":""}]},{"id":"s18-108","number":108,"surah":18,"verses":[51],"verseLabel":"الكهف: 51","question":"ما سرّ التعبير بـ﴿وَمَا كُنْتُ مُتَّخِذَ الْمُضِلِّينَ عَضُدًا﴾؟","answer":"العضد كناية عن المعين؛ فنفى أن يستعين بمن يضل، فضلًا عن أن يملكه شريكًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص136, تفسير الكهف 51.","url":""}]},{"id":"s18-109","number":109,"surah":18,"verses":[52],"verseLabel":"الكهف: 52","question":"ما سرّ التعبير بـ﴿نَادُوا شُرَكَائِيَ الَّذِينَ زَعَمْتُمْ﴾؟","answer":"أضافهم إليه على سبيل التهكم بدعواهم، ثم جعل النداء العملي يكشف عجزهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص140, تفسير الكهف 52.","url":""}]},{"id":"s18-110","number":110,"surah":18,"verses":[52],"verseLabel":"الكهف: 52","question":"لماذا جعل بينهم ﴿مَوْبِقًا﴾؟","answer":"الموبق حاجز مهلك أو وادٍ في النار، فينقلب الوصل المتوهم بينهم انفصالًا وهلاكًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص143, تفسير الكهف 52.","url":""}]},{"id":"s18-111","number":111,"surah":18,"verses":[53],"verseLabel":"الكهف: 53","question":"ما سرّ التعبير بـ﴿فَظَنُّوا أَنَّهُمْ مُوَاقِعُوهَا﴾ مع أنهم أيقنوا؟","answer":"الظن قد يأتي بمعنى اليقين، ويستحضر لحظة توقع الوقوع قبل مباشرته فتشتد الرهبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص148, تفسير الكهف 53.","url":""}]},{"id":"s18-112","number":112,"surah":18,"verses":[53],"verseLabel":"الكهف: 53","question":"ما سرّ التعبير بـ﴿وَلَمْ يَجِدُوا عَنْهَا مَصْرِفًا﴾؟","answer":"المصرف مكان أو وسيلة انصراف؛ فنفى كل طريق يحولهم عن النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص149, تفسير الكهف 53.","url":""}]},{"id":"s18-113","number":113,"surah":18,"verses":[54],"verseLabel":"الكهف: 54","question":"لماذا وصف الإنسان بأنه ﴿أَكْثَرَ شَيْءٍ جَدَلًا﴾؟","answer":"بالغ في رسوخ الجدل فيه؛ فهو يحول تنوع الأمثال إلى خصومة بدل الهداية إن فسد قصده.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص161, تفسير الكهف 54.","url":""}]},{"id":"s18-114","number":114,"surah":18,"verses":[55],"verseLabel":"الكهف: 55","question":"ما سرّ التعبير بـ﴿وَمَا مَنَعَ النَّاسَ أَنْ يُؤْمِنُوا﴾؟","answer":"استفهام بمعنى النفي والتعجب: لم يبق مانع حقيقي بعد مجيء الهدى، وإنما العناد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص169, تفسير الكهف 55.","url":""}]},{"id":"s18-115","number":115,"surah":18,"verses":[55],"verseLabel":"الكهف: 55","question":"ما سرّ التعبير بـ﴿إِلَّا أَنْ تَأْتِيَهُمْ سُنَّةُ الْأَوَّلِينَ﴾؟","answer":"جعل إصرارهم كأنهم لا ينتظرون إلا نموذج الهلاك القديم أو العذاب عيانًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص179, تفسير الكهف 55.","url":""}]},{"id":"s18-116","number":116,"surah":18,"verses":[56],"verseLabel":"الكهف: 56","question":"ما سرّ التعبير بقوله تعالى: ﴿وَمَا نُرْسِلُ الْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنْذِرِينَ﴾؟","answer":"حصر وظيفة الرسالة في البلاغ الذي يجمع الرجاء والخوف، لا تنفيذ المقترحات المتعنتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص190, تفسير الكهف 56.","url":""}]},{"id":"s18-117","number":117,"surah":18,"verses":[56],"verseLabel":"الكهف: 56","question":"ما سرّ التعبير بـ﴿وَيُجَادِلُ الَّذِينَ كَفَرُوا بِالْبَاطِلِ﴾؟","answer":"المضارع يصور خصومة تتجدد كلما جاءهم بيان، والباطل آلة لمحاولة إسقاط الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص197, تفسير الكهف 56.","url":""}]},{"id":"s18-118","number":118,"surah":18,"verses":[56],"verseLabel":"الكهف: 56","question":"ما سرّ التعبير بـ﴿لِيُدْحِضُوا بِهِ الْحَقَّ﴾؟","answer":"الإدحاض إزلاق القدم؛ استعارة لمحاولة إزالة ثبات الحق بحجة زائفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص199, تفسير الكهف 56.","url":""}]},{"id":"s18-119","number":119,"surah":18,"verses":[57],"verseLabel":"الكهف: 57","question":"ما سرّ التعبير بـ﴿ذُكِّرَ بِآيَاتِ رَبِّهِ﴾ بالبناء للمجهول؟","answer":"لأن المعتبر وصول التذكير إليه أيًا كان مبلغه، فلا عذر بعد قيام الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص214, تفسير الكهف 57.","url":""}]},{"id":"s18-120","number":120,"surah":18,"verses":[57],"verseLabel":"الكهف: 57","question":"ما سرّ التعبير بـ﴿بِآيَاتِ رَبِّهِ﴾ لا «بالقرآن»؟","answer":"ليعم كل علامة ووحي يربيه به ربه، ويشعره بقبح الإعراض عن رسالة مربيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص216, تفسير الكهف 57.","url":""}]},{"id":"s18-121","number":121,"surah":18,"verses":[57],"verseLabel":"الكهف: 57","question":"ما سرّ التعبير بـ﴿وَنَسِيَ مَا قَدَّمَتْ يَدَاهُ﴾؟","answer":"نسب العمل إلى اليدين لأن أكثر الأفعال بهما، وسمى الإهمال المتعمد نسيانًا تشنيعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص219, تفسير الكهف 57.","url":""}]},{"id":"s18-122","number":122,"surah":18,"verses":[57],"verseLabel":"الكهف: 57","question":"ما سرّ التعبير بـ﴿فِي آذَانِهِمْ وَقْرًا﴾ و﴿عَلَى قُلُوبِهِمْ أَكِنَّةً﴾؟","answer":"وافق الظرف الصورة: الثقل داخل الأذن، والأغطية فوق القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص220, تفسير الكهف 57.","url":""}]},{"id":"s18-123","number":123,"surah":18,"verses":[57],"verseLabel":"الكهف: 57","question":"ما سرّ التعبير بـ﴿وَإِنْ تَدْعُهُمْ إِلَى الْهُدَى فَلَنْ يَهْتَدُوا﴾؟","answer":"«إن» تفيد أن دعوتهم بعد تمكن الإعراض لا تثمر، و«لن» تقطع طمع الهداية ما داموا مصرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص229, تفسير الكهف 57.","url":""}]},{"id":"s18-124","number":124,"surah":18,"verses":[58],"verseLabel":"الكهف: 58","question":"ما سرّ التعبير بـ﴿وَرَبُّكَ الْغَفُورُ ذُو الرَّحْمَةِ﴾ لا «الرحيم»؟","answer":"«ذو الرحمة» يصور الرحمة وصفًا واسعًا ثابتًا يفسر إمهالهم رغم استحقاق المؤاخذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص235, تفسير الكهف 58.","url":""}]},{"id":"s18-125","number":125,"surah":18,"verses":[58],"verseLabel":"الكهف: 58","question":"ما سرّ التعبير بـ﴿بِمَا كَسَبُوا﴾؟","answer":"الكسب يربط الجزاء بما تعمدوه وجلبوه لأنفسهم، فلا ظلم في المؤاخذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص239, تفسير الكهف 58.","url":""}]},{"id":"s18-126","number":126,"surah":18,"verses":[58],"verseLabel":"الكهف: 58","question":"ما سرّ تقديم ﴿لَهُمْ﴾ في ﴿بَلْ لَهُمْ مَوْعِدٌ﴾؟","answer":"لتخصيصهم وتهديدهم بأن موعدًا معينًا يترصدهم لا يفلتون منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص242, تفسير الكهف 58.","url":""}]},{"id":"s18-127","number":127,"surah":18,"verses":[59],"verseLabel":"الكهف: 59","question":"ما سرّ التعبير بـ﴿وَتِلْكَ الْقُرَى أَهْلَكْنَاهُمْ﴾ فجمع القرى وأعاد الضمير إلى أهلها؟","answer":"أشار إلى آثار قرى متعددة، ثم راعى سكانها في ضمير العقلاء لأنهم محل الظلم والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص251, تفسير الكهف 59.","url":""}]},{"id":"s18-128","number":128,"surah":18,"verses":[59],"verseLabel":"الكهف: 59","question":"ما سرّ التعبير بـ﴿وَجَعَلْنَا لِمَهْلِكِهِمْ مَوْعِدًا﴾؟","answer":"الهلاك ليس فوضى؛ له وقت مقدر يمهلهم إلى تمام الحجة ثم لا يتأخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص254, تفسير الكهف 59.","url":""}]},{"id":"s18-129","number":129,"surah":18,"verses":[60],"verseLabel":"الكهف: 60","question":"ما سرّ التعبير بـموسى ﴿لَا أَبْرَحُ حَتَّى أَبْلُغَ﴾؟","answer":"عبّر عن استمرار السير بلا فتور حتى الغاية، فصار طلب العلم عزمًا مفتوح المدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص263, تفسير الكهف 60.","url":""}]},{"id":"s18-130","number":130,"surah":18,"verses":[60],"verseLabel":"الكهف: 60","question":"ما سرّ التعبير بـ﴿مَجْمَعَ الْبَحْرَيْنِ﴾ لا «ملتقى البحرين»؟","answer":"المجمع يصور الموضع الذي يجتمع فيه الماءان ويصير علامة مقصودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص265, تفسير الكهف 60.","url":""}]},{"id":"s18-131","number":131,"surah":18,"verses":[60],"verseLabel":"الكهف: 60","question":"ما سرّ التعبير بـ﴿أَوْ أَمْضِيَ حُقُبًا﴾؟","answer":"يبالغ في طول الاستعداد للسفر؛ فالحقب زمن طويل، والعلم يستحق الصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص267, تفسير الكهف 60.","url":""}]},{"id":"s18-132","number":132,"surah":18,"verses":[61],"verseLabel":"الكهف: 61","question":"ما سرّ التعبير بـ﴿فَلَمَّا بَلَغَا مَجْمَعَ بَيْنِهِمَا﴾؟","answer":"«لما» تصل بلوغ الغاية مباشرة بالحدث العجيب الذي كان علامة الموعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص271, تفسير الكهف 61.","url":""}]},{"id":"s18-133","number":133,"surah":18,"verses":[61],"verseLabel":"الكهف: 61","question":"ما سرّ التعبير بـالحوت ﴿فَاتَّخَذَ سَبِيلَهُ فِي الْبَحْرِ سَرَبًا﴾؟","answer":"شبّه طريقه في الماء بنفق يبقى أثره ظاهرًا، فكان خرقًا معتادًا علامة لموسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص274, تفسير الكهف 61.","url":""}]},{"id":"s18-134","number":134,"surah":18,"verses":[62],"verseLabel":"الكهف: 62","question":"لماذا لم يشعر موسى بالنصب إلا بعد مجاوزة الموعد؟","answer":"صرف الله عنه التعب حتى تجاوز المكان، ثم جعله سببًا للرجوع إلى العلامة التي نسيها فتاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص281, تفسير الكهف 62.","url":""}]},{"id":"s18-135","number":135,"surah":18,"verses":[62],"verseLabel":"الكهف: 62","question":"ما سرّ التعبير بـ﴿آتِنَا غَدَاءَنَا﴾ بالإيتاء لا الإعطاء؟","answer":"الإيتاء يناسب إحضار الطعام وتمكينه منه في مقام الحاجة بعد السفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص283, تفسير الكهف 62.","url":""}]},{"id":"s18-136","number":136,"surah":18,"verses":[63],"verseLabel":"الكهف: 63","question":"ما سرّ التعبير بـالفتى ﴿أَرَأَيْتَ إِذْ أَوَيْنَا إِلَى الصَّخْرَةِ﴾؟","answer":"بدأ باستدعاء انتباه موسى إلى الموضع الحاسم قبل ذكر النسيان والعجب.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص289, تفسير الكهف 63.","url":""}]},{"id":"s18-137","number":137,"surah":18,"verses":[63],"verseLabel":"الكهف: 63","question":"لماذا أضاف الإيواء إلى الصخرة لا إلى مجمع البحرين؟","answer":"الصخرة هي العلامة المحسوسة التي استراحا عندها ووقع عندها فقد الحوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص292, تفسير الكهف 63.","url":""}]},{"id":"s18-138","number":138,"surah":18,"verses":[63],"verseLabel":"الكهف: 63","question":"ما سرّ التعبير بـ﴿نَسِيتُ الْحُوتَ﴾ مع أن المنسي تذكر خبره؟","answer":"حذف المضاف وأقام الحوت مقام ذكره؛ أي نسيت أن أخبرك بشأنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص293, تفسير الكهف 63.","url":""}]},{"id":"s18-139","number":139,"surah":18,"verses":[63],"verseLabel":"الكهف: 63","question":"ما سرّ التعبير بـ﴿وَمَا أَنْسَانِيهُ إِلَّا الشَّيْطَانُ﴾؟","answer":"قصر سبب النسيان العارض على وسوسة الشيطان، مع بقاء الحدث داخل تدبير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص295, تفسير الكهف 63.","url":""}]},{"id":"s18-140","number":140,"surah":18,"verses":[63],"verseLabel":"الكهف: 63","question":"لماذا عطف ﴿وَاتَّخَذَ سَبِيلَهُ﴾ بالواو، وفي الآية 61 بالفاء؟","answer":"الفاء هناك لترتيب الحدث، والواو هنا من حكاية الفتى تجمع الخبرين دون قصد ترتيب جديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص297, تفسير الكهف 63.","url":""}]},{"id":"s18-141","number":141,"surah":18,"verses":[64],"verseLabel":"الكهف: 64","question":"ما سرّ التعبير بـموسى ﴿ذَلِكَ مَا كُنَّا نَبْغِ﴾؟","answer":"أدرك أن فقد الحوت هو العلامة المطلوبة؛ فاسم الإشارة يحسم أن هذا عين المقصود.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص303, تفسير الكهف 64.","url":""}]},{"id":"s18-142","number":142,"surah":18,"verses":[64],"verseLabel":"الكهف: 64","question":"ما سرّ التعبير بـ﴿فَارْتَدَّا عَلَى آثَارِهِمَا قَصَصًا﴾ لا «فرجعا»؟","answer":"الارتداد رجوع على الطريق نفسه، و«قصصًا» يصور تتبع الأثر بدقة حتى لا يضيعا الموضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص307, تفسير الكهف 64.","url":""}]},{"id":"s18-143","number":143,"surah":18,"verses":[65],"verseLabel":"الكهف: 65","question":"ما سرّ التعريف بـالخضر بأنه ﴿عَبْدًا مِنْ عِبَادِنَا﴾ ولم يُذكر اسمه؟","answer":"العبرة بوصف العبودية والعلم الموهوب لا بالاسم، وفي التنكير تعظيم لعبد خاص أخفاه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص314, تفسير الكهف 65.","url":""}]},{"id":"s18-144","number":144,"surah":18,"verses":[65],"verseLabel":"الكهف: 65","question":"ما سرّ التعبير بـ﴿آتَيْنَاهُ رَحْمَةً مِنْ عِنْدِنَا وَعَلَّمْنَاهُ مِنْ لَدُنَّا عِلْمًا﴾؟","answer":"قدم الرحمة لأنها أساس صلاح العلم، وخص العلم بـ«لدنا» للدلالة على تعليم خاص مباشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص318, تفسير الكهف 65.","url":""}]},{"id":"s18-145","number":145,"surah":18,"verses":[65],"verseLabel":"الكهف: 65","question":"ما سرّ تقديم ﴿مِنْ لَدُنَّا﴾ على ﴿عِلْمًا﴾؟","answer":"لقصر مصدر هذا العلم الخاص على تعليم الله، لا على كسب معتاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص320, تفسير الكهف 65.","url":""}]},{"id":"s18-146","number":146,"surah":18,"verses":[66],"verseLabel":"الكهف: 66","question":"ما سرّ التعبير بـموسى ﴿هَلْ أَتَّبِعُكَ﴾ مع أنه نبي؟","answer":"تواضع المتعلم لمن عنده علم لا يعلمه، واستأذن في الصحبة بدل أن يطالب بالتعليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص324, تفسير الكهف 66.","url":""}]},{"id":"s18-147","number":147,"surah":18,"verses":[66],"verseLabel":"الكهف: 66","question":"ما سرّ التعبير بـ﴿مِمَّا عُلِّمْتَ رُشْدًا﴾ لا «علمًا»؟","answer":"طلب من العلم ما يقود إلى الصواب والعمل، لا معلومات مجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص329, تفسير الكهف 66.","url":""}]},{"id":"s18-148","number":148,"surah":18,"verses":[67],"verseLabel":"الكهف: 67","question":"ما سرّ التعبير بـالخضر ﴿لَنْ تَسْتَطِيعَ مَعِيَ صَبْرًا﴾؟","answer":"لم يطعن في موسى، بل أخبر أن ظاهر الأفعال سيصادم علم الشريعة الذي يحمله قبل كشف بواطنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص337, تفسير الكهف 67.","url":""}]},{"id":"s18-149","number":149,"surah":18,"verses":[68],"verseLabel":"الكهف: 68","question":"ما سرّ التعبير بـ﴿وَكَيْفَ تَصْبِرُ عَلَى مَا لَمْ تُحِطْ بِهِ خُبْرًا﴾؟","answer":"السؤال يقرر قاعدة: الصبر على المشهد المقلق يعسر حين تغيب أسبابه وعاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص341, تفسير الكهف 68.","url":""}]},{"id":"s18-150","number":150,"surah":18,"verses":[68],"verseLabel":"الكهف: 68","question":"ما سرّ التعبير بـ﴿خُبْرًا﴾ لا «علمًا»؟","answer":"الخبر معرفة باطن الشيء وتجربته، وهو المطلوب لفهم الأفعال الغريبة لا مجرد علم إجمالي.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص344, تفسير الكهف 68.","url":""}]},{"id":"s18-151","number":151,"surah":18,"verses":[69],"verseLabel":"الكهف: 69","question":"ما سرّ التعبير بـموسى ﴿سَتَجِدُنِي إِنْ شَاءَ اللَّهُ صَابِرًا﴾؟","answer":"ربط وعده بالمشيئة تأدبًا، واختار اسم الفاعل ليدل على ثبات الصبر المقصود.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص349, تفسير الكهف 69.","url":""}]},{"id":"s18-152","number":152,"surah":18,"verses":[69],"verseLabel":"الكهف: 69","question":"ما سرّ التعبير بـ﴿وَلَا أَعْصِي لَكَ أَمْرًا﴾ ولم يقل «لن أعصي»؟","answer":"النفي بـ«لا» يتوجه إلى صفة العصيان في صحبته، مع بقاء الأدب وعدم القطع بالمستقبل استقلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص354, تفسير الكهف 69.","url":""}]},{"id":"s18-153","number":153,"surah":18,"verses":[70],"verseLabel":"الكهف: 70","question":"لماذا اشترط الخضر ﴿فَلَا تَسْأَلْنِي عَنْ شَيْءٍ حَتَّى أُحْدِثَ لَكَ مِنْهُ ذِكْرًا﴾؟","answer":"نظم طريق التعلم: يؤخر السؤال حتى يكتمل الحدث ويأتي وقت البيان، لأن الحكم على الجزء يضلل.","sources":[{"label":"التحرير والتنوير، ج15، ص372–373، تفسير الكهف 70.","url":""}]},{"id":"s18-154","number":154,"surah":18,"verses":[71],"verseLabel":"الكهف: 71","question":"ما سرّ التعبير بـ﴿خَرَقَهَا﴾ فور ركوب السفينة؟","answer":"بادر الخضر إلى الخرق عند الركوب؛ وتقديم ظرف الركوب يدل على أن الخرق وقع بمجرده، وأن الفعل كان مقصودًا مدبرًا من قبل.","sources":[{"label":"التحرير والتنوير، ج15، ص374، تفسير الكهف 71.","url":""}]},{"id":"s18-155","number":155,"surah":18,"verses":[71],"verseLabel":"الكهف: 71","question":"ما سرّ التعبير بـموسى ﴿لَقَدْ جِئْتَ شَيْئًا إِمْرًا﴾؟","answer":"الإِمر هو الأمر العظيم المنكر؛ فأكد موسى إنكاره لما ظهر له من كون الخرق ذريعة إلى إغراق أهل السفينة.","sources":[{"label":"التحرير والتنوير، ج15، ص374–375، تفسير الكهف 71.","url":""}]},{"id":"s18-156","number":156,"surah":18,"verses":[72],"verseLabel":"الكهف: 72","question":"لماذا ذكّره الخضر بلفظه نفسه ﴿لَنْ تَسْتَطِيعَ مَعِيَ صَبْرًا﴾؟","answer":"ليعيده إلى الشرط الذي قبله وهو يرى تحقق الخبر عمليًا.","sources":[{"label":"التحرير والتنوير، ج15، ص375، تفسير الكهف 72.","url":""}]},{"id":"s18-157","number":157,"surah":18,"verses":[73],"verseLabel":"الكهف: 73","question":"ما سرّ التعبير بـموسى ﴿لَا تُؤَاخِذْنِي بِمَا نَسِيتُ﴾؟","answer":"اعتذر موسى بأن اعتراضه الأول صدر عن نسيان شرط الصحبة، وسأل الصفح عنه.","sources":[{"label":"التحرير والتنوير، ج15، ص376، تفسير الكهف 73.","url":""}]},{"id":"s18-158","number":158,"surah":18,"verses":[73],"verseLabel":"الكهف: 73","question":"ما سرّ التعبير بـ﴿وَلَا تُرْهِقْنِي مِنْ أَمْرِي عُسْرًا﴾؟","answer":"طلب ألا يعامله الخضر بالشدة بسبب نسيانه، وأن يغضي ويصفح ليستمر أمر الصحبة.","sources":[{"label":"التحرير والتنوير، ج15، ص376، تفسير الكهف 73.","url":""}]},{"id":"s18-159","number":159,"surah":18,"verses":[74],"verseLabel":"الكهف: 74","question":"لماذا انتقل من خرق سفينة إلى قتل غلام؟","answer":"جاء قتل الغلام عقب لقائه مباشرة، وكانت المبادرة به أسرع من المبادرة بخرق السفينة؛ فاشتد إنكار موسى لأن الفساد هنا حاصل في نفس، لا مجرد ذريعة فساد.","sources":[{"label":"التحرير والتنوير، ج15، ص377، تفسير الكهف 74.","url":""}]},{"id":"s18-160","number":160,"surah":18,"verses":[74],"verseLabel":"الكهف: 74","question":"ما سرّ التعبير بـموسى ﴿نَفْسًا زَكِيَّةً بِغَيْرِ نَفْسٍ﴾؟","answer":"وصفها بالزكية لأنها نفس غلام لم يبلغ الحلم ولم يقترف ذنبًا، وقوله ﴿بغير نفس﴾ ينفي أن يكون قتله قصاصًا.","sources":[{"label":"التحرير والتنوير، ج15، ص377، تفسير الكهف 74.","url":""}]},{"id":"s18-161","number":161,"surah":18,"verses":[74],"verseLabel":"الكهف: 74","question":"ما سرّ التعبير بـهنا ﴿شَيْئًا نُكْرًا﴾، وفي السفينة ﴿إِمْرًا﴾؟","answer":"النُّكر أشد من الإمر؛ لأن قتل الغلام فساد حاصل، أما خرق السفينة فكان في الظاهر ذريعة إلى فساد.","sources":[{"label":"التحرير والتنوير، ج15، ص377، تفسير الكهف 74.","url":""}]},{"id":"s18-162","number":162,"surah":18,"verses":[75],"verseLabel":"الكهف: 75","question":"لماذا زاد الخضر هنا ﴿لَكَ﴾: ﴿أَلَمْ أَقُلْ لَكَ﴾؟","answer":"زيادة ﴿لك﴾ تحقق وقوع القول وتثبته وتقويه؛ لأن موسى أهمل العمل بالتنبيه السابق، فصار التقرير والإنكار أشد.","sources":[{"label":"التحرير والتنوير، ج16، ص5، تفسير الكهف 75.","url":""}]},{"id":"s18-163","number":163,"surah":18,"verses":[76],"verseLabel":"الكهف: 76","question":"لماذا جعل موسى الاعتراض الثالث نهاية الصحبة؟","answer":"أنصف موسى صاحبه، فجعل له العذر في قطع الصحبة إن عاد إلى السؤال ثالثة، تجنبًا لإحراجه بعد تكرر الاعتراض.","sources":[{"label":"التحرير والتنوير، ج16، ص5–6، تفسير الكهف 76.","url":""}]},{"id":"s18-164","number":164,"surah":18,"verses":[77],"verseLabel":"الكهف: 77","question":"ما سرّ التعبير بـ﴿اسْتَطْعَمَا أَهْلَهَا﴾ لا «طلبا طعامًا»؟","answer":"الاستطعام طلب الطعام، وقد كشف رفض أهل القرية إطعام عابري السبيل عن لؤم عام؛ إذ كانت الضيافة من المواساة الشائعة بين الأمم.","sources":[{"label":"التحرير والتنوير، ج16، ص6–7، تفسير الكهف 77.","url":""}]},{"id":"s18-165","number":165,"surah":18,"verses":[77],"verseLabel":"الكهف: 77","question":"ما سرّ التعبير بـ﴿جِدَارًا يُرِيدُ أَنْ يَنْقَضَّ﴾؟","answer":"استعيرت الإرادة لقرب سقوط الجدار: فقد مال وأشرف على الانقضاض، فشُبّه قرب وقوعه بإرادة العاقل للفعل.","sources":[{"label":"التحرير والتنوير، ج16، ص7–8، تفسير الكهف 77.","url":""}]},{"id":"s18-166","number":166,"surah":18,"verses":[77],"verseLabel":"الكهف: 77","question":"لماذا أقام الخضر الجدار بلا أجر مع لؤم القرية؟","answer":"لم تكن إقامته إحسانًا إلى أهل القرية، بل لطفًا من الله باليتيمين وحفظًا لكنزهما إلى بلوغهما، جزاءً لصلاح أبيهما.","sources":[{"label":"التحرير والتنوير، ج16، ص13–14، تفسير الكهف 77 و82.","url":""}]},{"id":"s18-167","number":167,"surah":18,"verses":[78],"verseLabel":"الكهف: 78","question":"ما سرّ التعبير بـ﴿هَذَا فِرَاقُ بَيْنِي وَبَيْنِكَ﴾؟","answer":"يشير ﴿هذا﴾ إلى ما حصل الآن من تحقق الشرط الذي ألزمه موسى نفسه؛ فصار الاعتراض الثالث هو لحظة انقطاع الصحبة.","sources":[{"label":"التحرير والتنوير، ج16، ص9، تفسير الكهف 78.","url":""}]},{"id":"s18-168","number":168,"surah":18,"verses":[78],"verseLabel":"الكهف: 78","question":"ما سرّ التعبير بـ﴿سَأُنَبِّئُكَ بِتَأْوِيلِ مَا لَمْ تَسْتَطِعْ عَلَيْهِ صَبْرًا﴾؟","answer":"أوفى الخضر بوعده السابق، فأنبأ موسى عند الفراق بأسباب الأفعال التي أنكرها وبعواقبها الخفية.","sources":[{"label":"التحرير والتنوير، ج16، ص9–10، تفسير الكهف 78.","url":""}]},{"id":"s18-169","number":169,"surah":18,"verses":[79],"verseLabel":"الكهف: 79","question":"لماذا نسب الخضر عيب السفينة إلى نفسه: ﴿فَأَرَدْتُ أَنْ أَعِيبَهَا﴾؟","answer":"قال ﴿فأردت أن أعيبها﴾ بدل «فعبتها» ليدل على أن فعل الخرق وقع عن قصد وتأمل؛ وقد قدمت الجملة للاهتمام بفعل ظاهره الإنكار وحقيقته الصلاح.","sources":[{"label":"التحرير والتنوير، ج16، ص10–11، تفسير الكهف 79.","url":""}]},{"id":"s18-170","number":170,"surah":18,"verses":[79],"verseLabel":"الكهف: 79","question":"كيف كان خرق السفينة رحمة؟","answer":"كان العيب المقصود صلاحًا في حقيقته؛ لأنه أبقى السفينة للمساكين ومنع الملك المتربص من أخذها ضمن السفن الصالحة غصبًا.","sources":[{"label":"التحرير والتنوير، ج16، ص10–12، تفسير الكهف 79.","url":""}]},{"id":"s18-171","number":171,"surah":18,"verses":[80],"verseLabel":"الكهف: 80","question":"ما سرّ التعبير بـالغلام ﴿فَخَشِينَا أَنْ يُرْهِقَهُمَا﴾؟","answer":"الخشية توقع ما سيقع لو لم يتدارك الأمر، وضمير الجمع من تواضع المتكلم وإظهار مشاركته لغيره؛ لأن المقام مقام إعلام بأن الله أطلعه وأمره.","sources":[{"label":"التحرير والتنوير، ج16، ص12–13، تفسير الكهف 80.","url":""}]},{"id":"s18-172","number":172,"surah":18,"verses":[80],"verseLabel":"الكهف: 80","question":"لماذا جمع بين ﴿طُغْيَانًا وَكُفْرًا﴾؟","answer":"الطغيان مجاوزة الحد في المعاملة، والكفر فساد الدين؛ فجمعهما لبيان ما كان سيغشى الوالدين من أذى الغلام في دينهما وحياتهما.","sources":[{"label":"التحرير والتنوير، ج16، ص12–13، تفسير الكهف 80.","url":""}]},{"id":"s18-173","number":173,"surah":18,"verses":[81],"verseLabel":"الكهف: 81","question":"ما سرّ التعبير بـ﴿فَأَرَدْنَا أَنْ يُبْدِلَهُمَا رَبُّهُمَا﴾ بضمير الجمع؟","answer":"ضمير الجمع عائد إلى المتكلم الواحد على أسلوب التواضع وإظهار المشاركة؛ لأن المقام مقام إعلام بأن الله أطلع الخضر على الأمر وأمره به.","sources":[{"label":"التحرير والتنوير، ج16، ص13، تفسير الكهف 81.","url":""}]},{"id":"s18-174","number":174,"surah":18,"verses":[81],"verseLabel":"الكهف: 81","question":"ما سرّ اختيار ﴿زَكَاةً﴾ و﴿رُحْمًا﴾ في وصف البديل؟","answer":"الزكاة الطهارة، وفيها مراعاة لقول موسى ﴿نفسًا زكية﴾؛ والرُّحم دال على كثرة الرحمة، أي أن يكون البديل أطهر وأشد رحمة بوالديه.","sources":[{"label":"التحرير والتنوير، ج16، ص13، تفسير الكهف 81.","url":""}]},{"id":"s18-175","number":175,"surah":18,"verses":[82],"verseLabel":"الكهف: 82","question":"ما سرّ التعبير في قصة الجدار بـ﴿فَأَرَادَ رَبُّكَ﴾؟","answer":"أُسندت الإرادة إلى الله لأن حفظ الكنز كرامة محضة لأبي الغلامين بسبب صلاحه، بخلاف القصتين السابقتين ففيهما دفع فساد يدركه من وقف على سره.","sources":[{"label":"التحرير والتنوير، ج16، ص13–14، تفسير الكهف 82.","url":""}]},{"id":"s18-176","number":176,"surah":18,"verses":[82],"verseLabel":"الكهف: 82","question":"لماذا حُفظ كنز الغلامين بسبب ﴿وَكَانَ أَبُوهُمَا صَالِحًا﴾؟","answer":"كان حفظ الكنز لطفًا بالغلامين وجزاءً لأبيهما على صلاحه واهتمامه بمعيشتهما بعده، لئلا ينكشف المال قبل بلوغهما.","sources":[{"label":"التحرير والتنوير، ج16، ص13–14، تفسير الكهف 82.","url":""}]},{"id":"s18-177","number":177,"surah":18,"verses":[82],"verseLabel":"الكهف: 82","question":"لماذا ختم الخضر بـ﴿وَمَا فَعَلْتُهُ عَنْ أَمْرِي﴾؟","answer":"ليزيل إنكار موسى ويبين أن التصرفات رحمة ومصلحة، وأنها لم تصدر عن اجتهاد الخضر أو هوى نفسه بل عن وحي وأمر من الله.","sources":[{"label":"التحرير والتنوير، ج16، ص14، تفسير الكهف 82.","url":""}]},{"id":"s18-178","number":178,"surah":18,"verses":[83],"verseLabel":"الكهف: 83","question":"ما سرّ التعبير بقوله تعالى: ﴿سَأَتْلُو عَلَيْكُمْ مِنْهُ ذِكْرًا﴾؟","answer":"وعدهم بأن يتلو عليهم بعض خبر ذي القرنين مما تتحقق به العبرة المقصودة، فـ﴿منه﴾ للتبعيض.","sources":[{"label":"التحرير والتنوير، ج16، ص15–16، تفسير الكهف 83.","url":""}]},{"id":"s18-179","number":179,"surah":18,"verses":[84],"verseLabel":"الكهف: 84","question":"ما دلالة الجمع لذي القرنين بين التمكين وإيتاء الأسباب؟","answer":"مكّن الله له في الأرض وآتاه وسائل الوصول إلى مقاصده؛ فالسبب هو الوسيلة، ويطلق في سياق رحلاته على الطريق الموصل إلى المكان المقصود.","sources":[{"label":"التحرير والتنوير، ج16، ص23–24، تفسير الكهف 84.","url":""}]},{"id":"s18-180","number":180,"surah":18,"verses":[85],"verseLabel":"الكهف: 85","question":"لماذا تكرر ﴿فَأَتْبَعَ سَبَبًا﴾ في رحلات ذي القرنين؟","answer":"للدلالة على أنه كان يسلك في كل وجهة طريقًا ووسيلة تبلغ به مقصده، فتكرر التركيب مع انتقاله بين جهات فتوحه.","sources":[{"label":"التحرير والتنوير، ج16، ص24، 28، 30، تفسير الكهف 85.","url":""}]},{"id":"s18-181","number":181,"surah":18,"verses":[86],"verseLabel":"الكهف: 86","question":"ما سرّ التعبير بـ﴿وَجَدَهَا تَغْرُبُ فِي عَيْنٍ حَمِئَةٍ﴾؟","answer":"وصف ما يلوح للناظر عند منتهى المعمور من جهة الغرب؛ فليس للشمس مغرب حقيقي في عين، وإنما يبدو ذلك للتخيل عند الأفق.","sources":[{"label":"التحرير والتنوير، ج16، ص24–25، تفسير الكهف 86.","url":""}]},{"id":"s18-182","number":182,"surah":18,"verses":[86],"verseLabel":"الكهف: 86","question":"لماذا خُيّر ذو القرنين بين تعذيب القوم والإحسان إليهم؟","answer":"أذن الله له أن يجري حكمه فيهم بالعقاب أو الإمهال، فاختار التفريق بينهم بحسب الظلم والإيمان والعمل الصالح.","sources":[{"label":"التحرير والتنوير، ج16، ص25–26، تفسير الكهف 86.","url":""}]},{"id":"s18-183","number":183,"surah":18,"verses":[87,88],"verseLabel":"الكهف: 87-88","question":"لماذا فرّق ذو القرنين بين الظالم والمؤمن؟","answer":"أجرى الحكم على ميزان العمل: للظالم عقوبة الدنيا ثم عذاب الآخرة، وللمؤمن العامل صالحًا الحسنى والمعاملة الميسرة.","sources":[{"label":"التحرير والتنوير، ج16، ص26–27، تفسير الكهف 87-88.","url":""}]},{"id":"s18-184","number":184,"surah":18,"verses":[88],"verseLabel":"الكهف: 88","question":"ما سرّ التعبير بـ﴿وَسَنَقُولُ لَهُ مِنْ أَمْرِنَا يُسْرًا﴾؟","answer":"أي نكلف المؤمن بما هو سهل ونخاطبه بلين، فجمع له حسن الجزاء وحسن المعاملة في سلطان ذي القرنين.","sources":[{"label":"التحرير والتنوير، ج16، ص27، تفسير الكهف 88.","url":""}]},{"id":"s18-185","number":185,"surah":18,"verses":[90],"verseLabel":"الكهف: 90","question":"ما دلالة قوله عن القوم ﴿لَمْ نَجْعَلْ لَهُمْ مِنْ دُونِهَا سِتْرًا﴾؟","answer":"كانوا في أرض مكشوفة لا ساتر فيها من حر الشمس، أو لم تكن لهم ثياب ولا مساكن تقيهم منها؛ وهو وصف لشدة انكشاف بيئتهم.","sources":[{"label":"التحرير والتنوير، ج16، ص28–29، تفسير الكهف 90.","url":""}]},{"id":"s18-186","number":186,"surah":18,"verses":[91],"verseLabel":"الكهف: 91","question":"ما دلالة قوله ﴿وَقَدْ أَحَطْنَا بِمَا لَدَيْهِ خُبْرًا﴾؟","answer":"أي أحاط الله علمًا بما عند ذي القرنين من عظمة الملك والجند والقوة والثروة؛ وفي التعبير كناية عن عظم ذلك بحيث لا يحيط به إلا علام الغيوب.","sources":[{"label":"التحرير والتنوير، ج16، ص29–30، تفسير الكهف 91.","url":""}]},{"id":"s18-187","number":187,"surah":18,"verses":[93],"verseLabel":"الكهف: 93","question":"ما سرّ وصف القوم بأنهم ﴿لَا يَكَادُونَ يَفْقَهُونَ قَوْلًا﴾؟","answer":"لغتهم غريبة منقطعة عن اللغات المعروفة حتى عجز تراجمة ذي القرنين عن التفاهم معهم، ويحتمل أيضًا شدة البداوة وقلة الفهم.","sources":[{"label":"التحرير والتنوير، ج16، ص30–31، تفسير الكهف 93.","url":""}]},{"id":"s18-188","number":188,"surah":18,"verses":[94],"verseLabel":"الكهف: 94","question":"ما دلالة قولهم ﴿إِنَّ يَأْجُوجَ وَمَأْجُوجَ مُفْسِدُونَ فِي الْأَرْضِ﴾؟","answer":"بيّنوا سبب طلب السد: كانوا أضعف من يأجوج ومأجوج ويصيب بلادهم فسادهم المتكرر، فطلبوا حاجزًا يقيهم.","sources":[{"label":"التحرير والتنوير، ج16، ص31–33، تفسير الكهف 94.","url":""}]},{"id":"s18-189","number":189,"surah":18,"verses":[94],"verseLabel":"الكهف: 94","question":"لماذا عرض القوم ﴿خَرْجًا﴾ على ذي القرنين؟","answer":"عرضوا مالًا يجمعونه له في مقابلة أن يجعل بينهم وبين المفسدين سدًا، لما علموا أن العمل يحتاج مؤونة وصناعة.","sources":[{"label":"التحرير والتنوير، ج16، ص33، تفسير الكهف 94.","url":""}]},{"id":"s18-190","number":190,"surah":18,"verses":[95],"verseLabel":"الكهف: 95","question":"لماذا رفض المال وقال ﴿مَا مَكَّنِّي فِيهِ رَبِّي خَيْرٌ﴾؟","answer":"استغنى بما مكّنه الله فيه من الملك والقدرة عن مالهم، واكتفى بأن يعينوه بقوة العمل والآلات.","sources":[{"label":"التحرير والتنوير، ج16، ص34، تفسير الكهف 95.","url":""}]},{"id":"s18-191","number":191,"surah":18,"verses":[95],"verseLabel":"الكهف: 95","question":"ما دلالة قوله ﴿فَأَعِينُونِي بِقُوَّةٍ﴾؟","answer":"طلب منهم قوة الأبدان والعمل والآلات لإقامة الردم، بدل المال الذي عرضوه؛ فكانوا عمال التنفيذ تحت تدبيره.","sources":[{"label":"التحرير والتنوير، ج16، ص34–35، تفسير الكهف 95.","url":""}]},{"id":"s18-192","number":192,"surah":18,"verses":[97],"verseLabel":"الكهف: 97","question":"ما سرّ اختلاف الصيغتين في ﴿فَمَا اسْطَاعُوا أَنْ يَظْهَرُوهُ وَمَا اسْتَطَاعُوا لَهُ نَقْبًا﴾؟","answer":"خففت الأولى للتفنن وتجنب إعادة الكلمة، وناسبت الصيغة الزائدة النقب لأنه أشد من تسلق الردم؛ فزيادة المبنى وافقت زيادة المعنى.","sources":[{"label":"التحرير والتنوير، ج16، ص37–38، تفسير الكهف 97.","url":""}]},{"id":"s18-193","number":193,"surah":18,"verses":[98],"verseLabel":"الكهف: 98","question":"ما دلالة قول ذي القرنين ﴿هَذَا رَحْمَةٌ مِنْ رَبِّي﴾ بعد الإنجاز؟","answer":"أشار إلى الردم وجعله رحمة من الله للناس، لما فيه من رد فساد يأجوج ومأجوج عن القوم الصالحين.","sources":[{"label":"التحرير والتنوير، ج16، ص38، تفسير الكهف 98.","url":""}]},{"id":"s18-194","number":194,"surah":18,"verses":[98],"verseLabel":"الكهف: 98","question":"ما دلالة قوله ﴿فَإِذَا جَاءَ وَعْدُ رَبِّي جَعَلَهُ دَكَّاءَ﴾؟","answer":"مهما بلغ الردم من الصلابة فبقاؤه مؤقت إلى الوقت الذي وعد الله فيه بخروج يأجوج ومأجوج؛ عندئذ يسويه بالأرض.","sources":[{"label":"التحرير والتنوير، ج16، ص38–39، تفسير الكهف 98.","url":""}]},{"id":"s18-195","number":195,"surah":18,"verses":[99],"verseLabel":"الكهف: 99","question":"ما سرّ التعبير بـ﴿يَمُوجُ فِي بَعْضٍ﴾؟","answer":"استعير موج البحر لاضطراب كثرتهم وتدافع بعضهم في بعض عند خروجهم وزوال الحاجز.","sources":[{"label":"التحرير والتنوير، ج16، ص39–40، تفسير الكهف 99.","url":""}]},{"id":"s18-196","number":196,"surah":18,"verses":[100],"verseLabel":"الكهف: 100","question":"ما دلالة توكيد ﴿وَعَرَضْنَا جَهَنَّمَ يَوْمَئِذٍ لِلْكَافِرِينَ عَرْضًا﴾ بالمصدر؟","answer":"يفيد إبراز جهنم لهم إبرازًا محققًا حين يساقون إليها، وسمي عرضًا على سبيل التهكم؛ لأن العرض يكون عادة لما يرغب فيه.","sources":[{"label":"التحرير والتنوير، ج16، ص40–42، تفسير الكهف 100.","url":""}]},{"id":"s18-197","number":197,"surah":18,"verses":[101],"verseLabel":"الكهف: 101","question":"ما سرّ التعبير بـ﴿فِي غِطَاءٍ عَنْ ذِكْرِي﴾؟","answer":"الغطاء استعارة لعدم انتفاعهم بدلالة أبصارهم على تفرد الله، و﴿في﴾ تصور تمكن الغطاء منهم، و﴿عن﴾ مجاوزتهم النظر فيما يذكر بالله.","sources":[{"label":"التحرير والتنوير، ج16، ص41–42، تفسير الكهف 101.","url":""}]},{"id":"s18-198","number":198,"surah":18,"verses":[101],"verseLabel":"الكهف: 101","question":"ما سرّ التعبير بـ﴿لَا يَسْتَطِيعُونَ سَمْعًا﴾؟","answer":"ليس المراد فقد الحاسة، بل شدة الكفر التي جعلت نفوسهم لا تطاوعهم على الاستماع للآيات؛ فنفي الاستطاعة مستعمل في نفي الرغبة والإعراض.","sources":[{"label":"التحرير والتنوير، ج16، ص41–42، تفسير الكهف 101.","url":""}]},{"id":"s18-199","number":199,"surah":18,"verses":[102],"verseLabel":"الكهف: 102","question":"لماذا أنكر على الكافرين اتخاذ عباد الله أولياء؟","answer":"الاستفهام إنكاري لحسبانهم الباطل أن أولياءهم من دون الله سينفعونهم وينصرونهم، وقد نشأ هذا الحسبان من إعراضهم عن دلائل التوحيد.","sources":[{"label":"التحرير والتنوير، ج16، ص42–44، تفسير الكهف 102.","url":""}]},{"id":"s18-200","number":200,"surah":18,"verses":[103],"verseLabel":"الكهف: 103","question":"لماذا سأل ﴿هَلْ نُنَبِّئُكُمْ بِالْأَخْسَرِينَ أَعْمَالًا﴾؟","answer":"الاستفهام للتشويق إلى خبر عجيب: أناس ضل عملهم وهم يحسبون أنهم يحسنون، فجمعوا خسارة السعي وخسارة الاعتقاد فيه.","sources":[{"label":"التحرير والتنوير، ج16، ص44–45، تفسير الكهف 103.","url":""}]},{"id":"s18-201","number":201,"surah":18,"verses":[104],"verseLabel":"الكهف: 104","question":"كيف ضل سعيهم مع أنهم ﴿يَحْسَبُونَ أَنَّهُمْ يُحْسِنُونَ صُنْعًا﴾؟","answer":"ضل عملهم عن طريق النفع وبطل أثره، وزاد خسارهم أنهم كانوا يعتقدون فسادهم صلاحًا؛ فجهلوا سوء العمل وسوء اعتقادهم فيه.","sources":[{"label":"التحرير والتنوير، ج16، ص45–46، تفسير الكهف 104.","url":""}]},{"id":"s18-202","number":202,"surah":18,"verses":[105],"verseLabel":"الكهف: 105","question":"ما سرّ التعبير بـ﴿فَحَبِطَتْ أَعْمَالُهُمْ﴾؟","answer":"الحبوط بطلان أثر العمل بعد وجود صورته؛ فكفرهم بآيات الله ولقائه أذهب ما توهموه نافعًا من أعمالهم.","sources":[{"label":"التحرير والتنوير، ج16، ص46–47، تفسير الكهف 105.","url":""}]},{"id":"s18-203","number":203,"surah":18,"verses":[105],"verseLabel":"الكهف: 105","question":"ما سرّ التعبير بـ﴿فَلَا نُقِيمُ لَهُمْ يَوْمَ الْقِيَامَةِ وَزْنًا﴾؟","answer":"نفي الوزن كناية عن عدم الاعتداد بهم وحقارتهم؛ فالشيء التافه لا يوزن، وقد تفرع ذلك على حبوط أعمالهم.","sources":[{"label":"التحرير والتنوير، ج16، ص47–48، تفسير الكهف 105.","url":""}]},{"id":"s18-204","number":204,"surah":18,"verses":[106],"verseLabel":"الكهف: 106","question":"ما دلالة قوله ﴿ذَلِكَ جَزَاؤُهُمْ جَهَنَّمُ﴾؟","answer":"يشير إلى إعداد جهنم السابق، وجاء التصريح بجهنم بدلًا مطابقًا من الجزاء؛ وإعادة اسمها أكسبت الوعيد قوة التوكيد.","sources":[{"label":"التحرير والتنوير، ج16، ص48، تفسير الكهف 106.","url":""}]},{"id":"s18-205","number":205,"surah":18,"verses":[107],"verseLabel":"الكهف: 107","question":"ما سرّ وصف جنات الفردوس بأنها ﴿نُزُلًا﴾؟","answer":"هي ما أعده الله للمؤمنين نزولًا وكرامة، في مقابلة جعل جهنم نزلًا للكافرين على سبيل التهكم؛ والفردوس البستان الجامع لضروب النعيم.","sources":[{"label":"التحرير والتنوير، ج16، ص49–50، تفسير الكهف 107.","url":""}]},{"id":"s18-206","number":206,"surah":18,"verses":[108],"verseLabel":"الكهف: 108","question":"ما سرّ التعبير بـ﴿لَا يَبْغُونَ عَنْهَا حِوَلًا﴾؟","answer":"لا يتطلعون إلى مفارقتها إلى مكان خير، لأنهم يجدون فيها كل ما تشتهيه نفوسهم من ضروب اللذات.","sources":[{"label":"التحرير والتنوير، ج16، ص50، تفسير الكهف 108.","url":""}]},{"id":"s18-207","number":207,"surah":18,"verses":[109],"verseLabel":"الكهف: 109","question":"لماذا جُعل البحر مدادًا لكلمات الله؟","answer":"شبهت معلومات الله التي يخبر بها بالمكتوبات، ورمز إلى الكتابة بالمداد؛ فلو كان البحر حبرًا لكتابتها لنفد مع استحالة نفاد معلومات الله.","sources":[{"label":"التحرير والتنوير، ج16، ص51–53، تفسير الكهف 109.","url":""}]},{"id":"s18-208","number":208,"surah":18,"verses":[109],"verseLabel":"الكهف: 109","question":"ما دلالة قوله ﴿وَلَوْ جِئْنَا بِمِثْلِهِ مَدَدًا﴾؟","answer":"هذه مبالغة ثانية: حتى لو مُد البحر ببحر مثله لبقي نفاد المداد ممكنًا، ولم تقارب كلمات الله النفاد.","sources":[{"label":"التحرير والتنوير، ج16، ص53، تفسير الكهف 109.","url":""}]},{"id":"s18-209","number":209,"surah":18,"verses":[110],"verseLabel":"الكهف: 110","question":"لماذا خُتمت السورة بـ﴿إِنَّمَا أَنَا بَشَرٌ مِثْلُكُمْ﴾؟","answer":"لرد توهم إحاطة الرسول بالمغيبات بعد إجابته عن الأسئلة؛ فهو بشر لا يعلم إلا ما أوحاه الله إليه، وخصوصيته الوحي.","sources":[{"label":"التحرير والتنوير، ج16، ص54، تفسير الكهف 110.","url":""}]},{"id":"s18-210","number":210,"surah":18,"verses":[110],"verseLabel":"الكهف: 110","question":"لماذا لُخّص أهم الوحي في ﴿أَنَّمَا إِلَهُكُمْ إِلَهٌ وَاحِدٌ﴾؟","answer":"لأن توحيد الله أهم ما أوحي إلى الرسول وما بعث لأجله، ثم فرع عليه الإيمان بالبعث والعمل الصالح والنهي عن الإشراك.","sources":[{"label":"التحرير والتنوير، ج16، ص54–55، تفسير الكهف 110.","url":""}]},{"id":"s18-211","number":211,"surah":18,"verses":[110],"verseLabel":"الكهف: 110","question":"ما دلالة الجمع في الختام بين العمل الصالح وترك الشرك؟","answer":"جمع الختام أصول النجاة: توحيد الله، وإثبات البعث بلقاء الرب، والعمل الصالح؛ وأكد التوحيد بالنهي عن الإشراك في العبادة.","sources":[{"label":"التحرير والتنوير، ج16، ص54–55، تفسير الكهف 110.","url":""}]},{"id":"s18-212","number":212,"surah":18,"verses":[110],"verseLabel":"الكهف: 110","question":"ما سرّ تنكير ﴿أَحَدًا﴾ في قوله ﴿وَلَا يُشْرِكْ بِعِبَادَةِ رَبِّهِ أَحَدًا﴾؟","answer":"النكرة في سياق النهي تعم كل أحد، فيكون ختام السورة تأكيدًا لوحدانية الله ونفي كل مشاركة في عبادته.","sources":[{"label":"التحرير والتنوير، ج16، ص55، تفسير الكهف 110.","url":""}]},{"id":"s19-1","number":1,"surah":19,"verses":[1],"verseLabel":"مريم: 1","question":"لماذا افتتحت السورة بالحروف ﴿كهيعص﴾؟","answer":"الحروف المقطعة من المتشابه الذي تُفوَّض حقيقة مراده إلى الله، ومن أشهر وجوه حكمتها التنبيه إلى إعجاز القرآن المؤلف من جنس حروف العرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص705–707.","url":""}]},{"id":"s19-2","number":2,"surah":19,"verses":[2],"verseLabel":"مريم: 2","question":"ما سرّ التعبير بـ﴿ذِكْرُ رَحْمَتِ رَبِّكَ عَبْدَهُ زَكَرِيَّا﴾؟","answer":"جعل القصة نفسها ذكرًا للرحمة، وأضاف الرب إلى النبي للعناية، ووصف زكريا بالعبودية تشريفًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص707–710.","url":""}]},{"id":"s19-3","number":3,"surah":19,"verses":[3],"verseLabel":"مريم: 3","question":"لماذا دعا زكريا ربه ﴿نِدَاءً خَفِيًّا﴾؟","answer":"جمع وصف النداء بالخفاء بين التضرع والمناجاة والإخلاص، وهو أبلغ في أدب الدعاء وأبعد عن اطلاع الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص711–716.","url":""}]},{"id":"s19-4","number":4,"surah":19,"verses":[4],"verseLabel":"مريم: 4","question":"ما سرّ التعبير بـ﴿وَهَنَ الْعَظْمُ مِنِّي﴾ لا «ضعف جسمي»؟","answer":"العظم قوام البدن؛ فإذا دب الوهن في أصله دل على بلوغ الضعف غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص722–724.","url":""}]},{"id":"s19-5","number":5,"surah":19,"verses":[4],"verseLabel":"مريم: 4","question":"ما سر صورة ﴿وَاشْتَعَلَ الرَّأْسُ شَيْبًا﴾؟","answer":"شبّه انتشار الشيب باشتعال النار، فصور سرعة عمومه وسطوعه في الرأس كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص724–727.","url":""}]},{"id":"s19-6","number":6,"surah":19,"verses":[4],"verseLabel":"مريم: 4","question":"ما سرّ التعبير بـ﴿وَلَمْ أَكُنْ بِدُعَائِكَ رَبِّ شَقِيًّا﴾؟","answer":"توسل بسابق لطف الله؛ فلم تكن دعواته الماضية سبب خيبة، فرجا استمرار العناية.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص729–731.","url":""}]},{"id":"s19-7","number":7,"surah":19,"verses":[5],"verseLabel":"مريم: 5","question":"ما سرّ التعبير بـ﴿خِفْتُ الْمَوَالِيَ مِنْ وَرَائِي﴾؟","answer":"خاف ممن يلون أمر قومه بعده أن يضيعوا الدين، لا مجرد فقد وارث لماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص732.","url":""}]},{"id":"s19-8","number":8,"surah":19,"verses":[5],"verseLabel":"مريم: 5","question":"ما سرّ التعبير بـ﴿وَكَانَتِ امْرَأَتِي عَاقِرًا﴾ بصيغة ثابتة؟","answer":"دل الماضي في ﴿كانت﴾ واسم الفاعل ﴿عاقرًا﴾ على أن العقر حال قديمة مستقرة فيها؛ فازدادت البشارة خرقًا للعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص733، 760–761.","url":""}]},{"id":"s19-9","number":9,"surah":19,"verses":[5],"verseLabel":"مريم: 5","question":"لماذا طلب ﴿وَلِيًّا﴾ ولم يقل «ولدًا»؟","answer":"لأنه طلب من يلي أمر الدين ويحفظ الدعوة، لا ولدًا لمجرد الأنس والنسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص734–736.","url":""}]},{"id":"s19-10","number":10,"surah":19,"verses":[6],"verseLabel":"مريم: 6","question":"ما سرّ التعبير بـ﴿يَرِثُنِي وَيَرِثُ مِنْ آلِ يَعْقُوبَ﴾؟","answer":"جمع ميراث علمه ونبوته وما في آل يعقوب من تراث الهداية، فالمقصود بقاء الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص738–740.","url":""}]},{"id":"s19-11","number":11,"surah":19,"verses":[6],"verseLabel":"مريم: 6","question":"ما سرّ التعبير بـ﴿وَاجْعَلْهُ رَبِّ رَضِيًّا﴾؟","answer":"لم يكتف بوجود الوارث، بل سأل صلاحه وقبول الله له؛ فالذرية نعمة بصلاحها.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص741–742.","url":""}]},{"id":"s19-12","number":12,"surah":19,"verses":[7],"verseLabel":"مريم: 7","question":"ما سرّ التعبير بـ﴿لَمْ نَجْعَلْ لَهُ مِنْ قَبْلُ سَمِيًّا﴾؟","answer":"زيادة في تكريمه: اسم مختار لم يسبق إليه، أو نظير لم يُعرف له في صفاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص752–753.","url":""}]},{"id":"s19-13","number":13,"surah":19,"verses":[8],"verseLabel":"مريم: 8","question":"لماذا تعجب زكريا بعد أن طلب الولد؟","answer":"لم يشك في القدرة، وإنما سأل عن كيفية تحقق البشرى مع اجتماع الشيخوخة والعقر.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص758–760.","url":""}]},{"id":"s19-14","number":14,"surah":19,"verses":[8],"verseLabel":"مريم: 8","question":"لماذا وصف نفسه بأنه بلغ من الكبر ﴿عِتِيًّا﴾؟","answer":"العتو بلوغ أقصى اليبس والصلابة؛ فاستعير لشدة الشيخوخة وجفاف القوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص762–764.","url":""}]},{"id":"s19-15","number":15,"surah":19,"verses":[9],"verseLabel":"مريم: 9","question":"لماذا كان الجواب ﴿هُوَ عَلَيَّ هَيِّنٌ﴾؟","answer":"رد الأمر إلى القدرة الإلهية لا إلى الأسباب، ثم احتج بخلقه الأول من العدم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص766–773.","url":""}]},{"id":"s19-16","number":16,"surah":19,"verses":[10],"verseLabel":"مريم: 10","question":"لماذا كانت آيته ألا يكلم الناس ثلاث ليال وهو ﴿سَوِيًّا﴾؟","answer":"انحباس الكلام مع سلامة الجسد علامة خارقة لا تُفسر بمرض أو عجز طبيعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص776–783.","url":""}]},{"id":"s19-17","number":17,"surah":19,"verses":[11],"verseLabel":"مريم: 11","question":"ما سرّ التعبير بـ﴿فَخَرَجَ عَلَى قَوْمِهِ مِنَ الْمِحْرَابِ﴾؟","answer":"رتبت الفاء خروجه على ما وقع في المحراب من البشارة والآية، فانتقل عقب ذلك إلى قومه ليبلغهم بالإشارة ما أُمروا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص786–787.","url":""}]},{"id":"s19-18","number":18,"surah":19,"verses":[11],"verseLabel":"مريم: 11","question":"ما سرّ التعبير بـ﴿فَأَوْحَى إِلَيْهِمْ﴾ مع أنه لم يتكلم؟","answer":"الوحي هنا إشارة سريعة خفية، فالكلمة تناسب حاله حين مُنع النطق.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص787–792.","url":""}]},{"id":"s19-19","number":19,"surah":19,"verses":[12],"verseLabel":"مريم: 12","question":"ما سرّ التعبير بـليحيى ﴿خُذِ الْكِتَابَ بِقُوَّةٍ﴾؟","answer":"القوة جدّ في الفهم والعمل والحفظ، لا مجرد حمل الكتاب أو قراءته.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص797–798.","url":""}]},{"id":"s19-20","number":20,"surah":19,"verses":[12],"verseLabel":"مريم: 12","question":"ما سرّ التعبير بـ﴿وَآتَيْنَاهُ الْحُكْمَ صَبِيًّا﴾؟","answer":"قدم له النضج والحكمة قبل سنهما المعتاد، فكانت صباه نفسه آية.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص798–804.","url":""}]},{"id":"s19-21","number":21,"surah":19,"verses":[13],"verseLabel":"مريم: 13","question":"ما سرّ اختيار لفظ ﴿حَنَانًا﴾ لا «رحمة» فقط؟","answer":"الحنان رحمة مشوبة بعطف ورقة وإقبال، فناسب قلب النبي البار.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص11–14.","url":""}]},{"id":"s19-22","number":22,"surah":19,"verses":[13],"verseLabel":"مريم: 13","question":"لماذا جمع ﴿حَنَانًا مِنْ لَدُنَّا وَزَكَاةً﴾؟","answer":"الأول عطاء الرحمة من الله، والثاني طهارة النفس ونماؤها؛ فجمع مصدر الخير وأثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص13–16.","url":""}]},{"id":"s19-23","number":23,"surah":19,"verses":[14],"verseLabel":"مريم: 14","question":"ما سرّ اختلاف التعبير بين ﴿وَلَمْ يَكُنْ جَبَّارًا عَصِيًّا﴾ في يحيى و﴿وَلَمْ يَجْعَلْنِي جَبَّارًا شَقِيًّا﴾ في عيسى؟","answer":"ناسب يحيىَ نفيُ العصيان بعد وصفه بالبر والتقوى، أما عيسى فنفى عن نفسه الشقاء أدبًا عن تزكية النفس بنفي المعصية، ونفى ﴿جبارًا﴾ على نحو يلائم بره بأمه؛ كما جاء ﴿كان﴾ في خبر يحيى و﴿جعلني﴾ في كلام عيسى موافقةً لنظم السياقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص21–22.","url":""}]},{"id":"s19-24","number":24,"surah":19,"verses":[15],"verseLabel":"مريم: 15","question":"لماذا ذكرت السلامة في يوم الولادة والموت والبعث؟","answer":"هذه أشد مواطن الوحشة والانتقال، فخصه الله بالأمان فيها كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص26–31.","url":""}]},{"id":"s19-25","number":25,"surah":19,"verses":[15,33],"verseLabel":"مريم: 15، 33","question":"ما سرّ تنكير السلام في يحيى ﴿وَسَلَامٌ عَلَيْهِ﴾ وتعريفه في عيسى ﴿وَالسَّلَامُ عَلَيَّ﴾؟","answer":"نُكّر السلام على يحيى للتفخيم والتعظيم، وهو سلام صادر من الله؛ وعُرّف في كلام عيسى لأنه حكاية السلام المعهود المذكور قبل ذلك، مع إفادة جنس السلام كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص27–28، 163–164.","url":""}]},{"id":"s19-26","number":26,"surah":19,"verses":[16],"verseLabel":"مريم: 16","question":"ما سرّ التعبير بـ﴿وَاذْكُرْ فِي الْكِتَابِ مَرْيَمَ﴾؟","answer":"أدخل قصتها في الذكر المتلو الموثق، وردها من جدل الناس إلى خبر الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص32–35.","url":""}]},{"id":"s19-27","number":27,"surah":19,"verses":[16],"verseLabel":"مريم: 16","question":"لماذا انتبذت ﴿مَكَانًا شَرْقِيًّا﴾؟","answer":"اعتزلت أهلها للعبادة، وخص الشرق لأنه جهة الضوء وموضع خلوّتها من البيت المقدس.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص36–41.","url":""}]},{"id":"s19-28","number":28,"surah":19,"verses":[17],"verseLabel":"مريم: 17","question":"ما سرّ التعبير بـ﴿فَاتَّخَذَتْ مِنْ دُونِهِمْ حِجَابًا﴾؟","answer":"زاد على مجرد البعد سترًا حسيًا، تمهيدًا لمفاجأة ظهور الملك في خلوتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص42–46.","url":""}]},{"id":"s19-29","number":29,"surah":19,"verses":[17],"verseLabel":"مريم: 17","question":"لماذا تمثل لها الروح ﴿بَشَرًا سَوِيًّا﴾؟","answer":"لتطيق مخاطبته وتفهم كلامه، وكان كمال هيئته سببًا في شدة خوفها أولًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص42–50.","url":""}]},{"id":"s19-30","number":30,"surah":19,"verses":[18],"verseLabel":"مريم: 18","question":"ما دلالة قولها: ﴿أَعُوذُ بِالرَّحْمَنِ مِنْكَ﴾؟","answer":"استجارت باسم الرحمة في مقام الخوف، واستثارت تقواه بقولها ﴿إن كنت تقيا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص54–55.","url":""}]},{"id":"s19-31","number":31,"surah":19,"verses":[19],"verseLabel":"مريم: 19","question":"ما سرّ وصف الغلام بـ﴿زَكِيًّا﴾؟","answer":"ليطمئنها أن الولد طاهر النفس مبارك، لا وصمة فيه رغم غرابة مولده.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص62.","url":""}]}]);
